window.ENAMED_LOCAL_QUESTION_BANK = window.ENAMED_LOCAL_QUESTION_BANK || {};
window.ENAMED_LOCAL_QUESTION_BANK["13"] = {"block":13,"count":121,"questions":[{"id":"b13-violencia-sexual-q01","number":1,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"A anticoncepção de emergência deve ser usada nas situações em que a mulher sofreu abuso sexual nas primeiras 72 horas após o coito. Sobre o método anticoncepcional a ser usado, assinale a alternativa correta:","options":{"A":"O método preferido deve ser o de Yuzpe via oral, porque é mais eficaz e ocasiona menos efeitos colaterais.","B":"A preferência deve ser pelo uso do Levonorgestrel via oral, por ter maior eficácia e menos efeitos colaterais.","C":"Deve-se preferir sempre o uso de um injetável mensal, porque a eficácia é maior e os efeitos colaterais raramente ocorrem.","D":"A eficácia de qualquer método é baixa, em torno de 50%, mas deve ser administrado em todos os casos pelos riscos de uma gestação indesejada."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O levonorgestrel via oral é o método de anticoncepção de emergência de eleição, pois possui maior eficácia e menor taxa de efeitos colaterais (como náuseas e vômitos) em comparação ao método de Yuzpe.\nPor que as outras estão erradas:\nA: O método de Yuzpe (estrógeno + progestina) é menos eficaz e causa mais efeitos colaterais gastrointestinais.\nC: Injetáveis mensais não são indicados para anticoncepção de emergência.\nD: A eficácia do levonorgestrel é em torno de 85% se usado nas primeiras 72h, e não 50%.\nPonto de prova: Escolha do método anticoncepcional de emergência pós-violência sexual.\nFlashcard sugerido: Qual o método preferencial de anticoncepção de emergência? Levonorgestrel dose única.\nPérola: Levonorgestrel é a estrela da emergência.\nArmadilha: Achar que o método de Yuzpe ou injetáveis são melhores.","tags":["Clínica Médica","Medicina Interna","Anticoncepção de Emergência","Violência Sexual","Conhecimento Conceitual","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Existe um remédio para evitar gravidez depois de uma violência, e o melhor deles é um comprimido chamado levonorgestrel, porque funciona muito bem e deixa a pessoa passar menos mal (menos enjoo) do que outras opções mais antigas."},{"id":"b13-tecnica-operatoria-q01","number":2,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"A sequência de bloqueio das fibras nervosas, pelo anestésico local, é:","options":{"A":"Frio - calor - dor - motor - tato.","B":"Calor - frio - dor - tato - motor.","C":"Dor - calor - frio - motor - tato.","D":"Dor - frio - calor - tato - motor.","E":"Dor - tato - frio - calor - motor."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A sequência de bloqueio das fibras nervosas pelos anestésicos locais segue a ordem do menor para o maior diâmetro/mielinização: dor (B), frio (B), calor (C), tato (A-beta) e motor (A-alfa).\nPor que as outras estão erradas:\nA, B, C, E: Apresentam a ordem incorreta do bloqueio das fibras nervosas.\nPonto de prova: Farmacologia dos anestésicos locais e sequência de bloqueio nervoso.\nFlashcard sugerido: Ordem de bloqueio do anestésico local? Dor > Frio > Calor > Tato > Motor.\nPérola: \"Dor, Frio, Calor, Tato, Motor\" - do menor pro maior.\nArmadilha: Achar que o motor é bloqueado antes do tato.","tags":["Cirurgia","Anestesiologia","Anestésicos Locais","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"O remédio que tira a dor age primeiro nos fios mais finos do nervo, por isso a dor some primeiro, depois o frio, depois o calor, depois o toque, e só por último a força dos músculos para se mexer."},{"id":"b13-tecnica-operatoria-q02","number":3,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Paciente, sexo masculino, 27 anos de idade, é trazido por populares à Unidade de Pronto Atendimento, UPA, após ser vítima de agressão física. Relata que sofreu agressão com um soco na boca, há cerca de 45 minutos, após discussão em um bar. Refere ferimento em lábio inferior com dor e sangramento. Nega outros sintomas. Ao exame físico, bom estado geral, lúcido e orientado, presença de ferimento corto-contuso em região central do lábio inferior, medindo 3cm de espessura total (exposição de mucosa), sem perda de substância e com sangramento ativo em pequena quantidade. Identifique o número mínimo de planos anatômicos que devem ser fechados no reparo do ferimento desse paciente.","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Ferimento de espessura total de lábio envolve pele, músculo e mucosa, exigindo fechamento em 3 planos anatômicos distintos.\nPor que as outras estão erradas:\nA e B: Planos insuficientes para um fechamento adequado por planos.\nD: Não há um quarto plano anatômico a ser fechado neste ferimento.\nPonto de prova: Reparo de ferimentos lábio-bucais.\nFlashcard sugerido: Quantos planos fechar em ferimento lábio de espessura total? 3 (mucosa, músculo, pele).\nPérola: Lábio de espessura total = 3 planos anatômicos.\nArmadilha: Esquecer do plano muscular.","tags":["Cirurgia","Trauma","Reparo de Feridas","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Quando o corte no lábio atravessa tudo até dentro da boca, o médico precisa costurar em três camadas separadas — por dentro, o músculo e depois a pele por fora — para o ferimento cicatrizar direito."},{"id":"b13-pneumonia-q01","number":4,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Paciente de 32 anos, portador de síndrome da imunodeficiência humana adquirida por infecção do vírus HIV, foi internado por pneumonia comunitária grave e necessitou de vaga em leito de terapia intensiva. A cultura da secreção traqueal evidenciou o crescimento de Staphylococcus aureus resistente à oxacilina. Os seguintes antimicrobianos poderiam ser utilizados para tratar esse caso, EXCETO:","options":{"A":"Vancomicina.","B":"Linezolida.","C":"Teicoplanina.","D":"Tigeciclina.","E":"Daptomicina."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A daptomicina é inativada pelo surfactante pulmonar, sendo contraindicada para tratamento de pneumonias, mesmo aquelas causadas por MRSA.\nPor que as outras estão erradas:\nA, B, C, D: Vancomicina, linezolida, teicoplanina e tigeciclina são opções válidas e eficazes para pneumonia por MRSA.\nPonto de prova: Tratamento de pneumonia por MRSA e propriedades da daptomicina.\nFlashcard sugerido: Qual droga NÃO usar em pneumonia por MRSA? Daptomicina (inativada pelo surfactante).\nPérola: Daptomicina no pulmão não funciona (surfactante mata).\nArmadilha: Escolher a daptomicina por ser uma droga potente para MRSA.","tags":["Clínica Médica","Pneumologia","HIV/AIDS","Pneumonia","Conhecimento Conceitual","Assistência Hospitalar"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Existe um remédio forte contra uma bactéria perigosa, mas ele não funciona nos pulmões porque uma substância que reveste os pulmões o desativa, então para infecção pulmonar o médico escolhe outros remédios."},{"id":"b13-derrame-pleural-q01","number":5,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um homem com 61 anos de idade, hipertenso, atendido em unidade de saúde, tem febre, tosse com secreção amarelada, dor torácica à direita ventilatório−dependente, dispneia aos esforços moderados e hiporexia há 3 dias. É adequadamente vacinado para pneumococo e não tem história de internações no último ano. Ao primeiro exame, apresentou−se orientado, hidratado, com temperatura axilar = 38,5 ˚C, frequência cardíaca (FC) = 90 batimentos por minuto (bpm), pressão arterial (PA) = 130 x 80 mmHg, frequência respiratória (FR) = 22 incursões respiratórias por minuto (irpm), sem esforço respiratório, frêmito toracovocal diminuído e estertores crepitantes no terço inferior de hemitórax direito. O resultado da oximetria de pulso em ar ambiente foi de 96% e o da radiologia simples de tórax mostrou infiltrado em lobo inferior direito com derrame pleural de 2 cm em decúbito lateral. Foi−lhe prescrito amoxicilina + clavulanato para tratamento ambulatorial e solicitada punção de líquido pleural. No terceiro dia de tratamento, o paciente relatou melhora da febre e da dispneia, mas manutenção da tosse, da dor torácica e da hiporexia, e apresentou os seguintes resultados: temperatura axilar = 37,2 ˚C, FC = 80 bpm, PA = 130 x 70mmHg, FR = 18 irpm, oximetria de pulso em ar ambiente = 98%. O resultado da punção torácica, guiada por ultrassom, estimou o derrame em 200 mL, cuja análise mostrou líquido amarelo−citrino, 2.300 células com predomínio de neutrófilos, pH = 7,3, glicose = 60 mg/dL, LHD = 300 U/L, proteína = 4 g/L, Gram: não se visualizaram bactérias. A amostra sérica colhida no dia da punção mostrou glicose = 80 mg/dL (valor de referência [VR]= 60−99 mg/dL), proteínas totais = 6,6 g/dL (VR = 6,4−8,3 g/dL), LDH = 400 (VR = 180−450 U/L). Diante desse quadro clínico e dos dados apresentados, a abordagem adequada para o paciente é:","options":{"A":"A referenciar o paciente para a assistência hospitalar para drenagem de tórax.","B":"Manter o tratamento com amoxicilina + clavulanato e repetir o estudo radiológico em 1 semana.","C":"Suspender a amoxicilina + clavulanato, prescrever levofloxacina e reavaliar o paciente em 3 dias.","D":"Manter o tratamento com amoxicilina + clavulanato, colher bacilos álcool−ácido resistente (BAAR) em escarro e reavaliar o paciente no final do tratamento."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O líquido é exsudato (LDH relativo >0.6), mas não complicado (pH > 7.2, glicose > 60). Como o paciente está melhorando, mantém-se o antibiótico e observa-se.\nPor que as outras estão erradas:\nA: Não há indicação de drenagem de tórax, pois não é um derrame complicado.\nC: Suspender amox/clav não é necessário se o paciente está melhorando clínico.\nD: Não há indicação de pesquisar BAAR (quadro agudo de pneumonia bacteriana).\nPonto de prova: Manejo de derrame parapneumônico não complicado.\nFlashcard sugerido: Parapneumônico não complicado (pH>7.2)? Manter antibiótico e observar.\nPérola: pH > 7.2 e glicose > 60: só antibiótico.\nArmadilha: Indicar drenagem precoce em derrame não complicado.","tags":["Clínica Médica","Pneumologia","Trauma Torácico","Derrame Parapneumônico","Prevenção e Rastreamento","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"O líquido que se acumulou ao redor do pulmão foi analisado e não está complicado, e como o paciente já está melhorando com o remédio, o certo é continuar com o mesmo tratamento e só ir observando, sem precisar de mais nada."},{"id":"b13-violencia-sexual-q02","number":6,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Mulher de 25 anos procura atendimento na emergência da maternidade, desejando a realização de um abortamento, referindo que a gestação é resultado de estupro. Segundo relato da paciente, ela foi a uma festa, onde fez uso de bebidas alcoólicas em altas doses, ficando desacordada, não se lembrando de nada após isso. Sua primeira lembrança foi ter acordado em uma casa ao lado de um desconhecido, que afirmou ter mantido relações sexuais com ela. Relata que não procurou atendimento médico na época por vergonha do ocorrido. Há três dias, fez o diagnóstico de gestação, com idade gestacional compatível com o episódio. Nessa situação, a adequada orientação a ser dada pelo profissional é:","options":{"A":"Abertura de processo judicial, solicitando autorização para realização do procedimento.","B":"Encaminhamento para exame de corpo de delito e realização de boletim de ocorrência policial com vistas à confirmação de crime de estupro.","C":"Não realização do procedimento visto que a paciente é maior de idade e fez uso de bebidas alcoólicas por livre vontade, não se caracterizando nesta situação crime de estupro","D":"Realização de entrevista com equipe multidisciplinar da maternidade e assinatura de relato consubstanciado e termo de consentimento livre e esclarecido pela paciente para realização do procedimento."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Para o aborto legal por estupro, basta o relato circunstanciado da vítima e a assinatura do termo de consentimento, não sendo necessário boletim de ocorrência.\nPor que as outras estão erradas:\nA, B: Não é necessário processo judicial ou boletim de ocorrência.\nC: O uso de álcool pela vítima não anula o crime de estupro nem o direito ao aborto legal.\nPonto de prova: Legislação sobre aborto legal por estupro.\nFlashcard sugerido: Aborto por estupro precisa de BO? Não, basta relato circunstanciado.\nPérola: Relato da vítima basta para o aborto legal.\nArmadilha: Exigir BO ou exame de corpo de delito.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Abortamento","Raciocínio Diagnóstico","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Para interromper uma gravidez que veio de uma violência, não é preciso levar boletim policial nem provar nada na justiça — basta a equipe do hospital conversar com a pessoa e ela assinar um papel dizendo que concorda com o procedimento."},{"id":"b13-tecnica-operatoria-q03","number":7,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Motorista, 32 anos de idade, utilizando cinto de segurança de 3 pontos, foi vítima de acidente automobilístico, sendo atendido no PS com dor abdominal importante. A tomografia abdominal evidenciou grande quantidade de líquido abdominal, sendo indicada laparotomia exploradora, com achado de laceração intraperitoneal da bexiga urinária de aproximadamente 5 cm de extensão. Assinale a alternativa CORRETA quanto à escolha do fio a ser utilizado na sutura vesical:","options":{"A":"Poliamida.","B":"Poliglactina.","C":"Polipropileno.","D":"Poliéster."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A bexiga urinária exige sutura com fio absorvível (como poliglactina/Vicryl) para evitar cálculos e reações a corpo estranho na mucosa.\nPor que as outras estão erradas:\nA, C, D: Fios não absorvíveis (poliamida, polipropileno, poliéster) atuam como corpo estranho e nidus para litíase na via urinária.\nPonto de prova: Escolha de fios cirúrgicos em urologia/vísceras.\nFlashcard sugerado: Sutura de bexiga usa qual fio? Absorvível (poliglactina).\nPérola: Bexiga e vísceras ocas pedem absorvível.\nArmadilha: Usar fio não absorvível por achar que dá mais segurança.","tags":["Cirurgia","Trauma","Reparo de Feridas","Dor Abdominal","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Para costurar um órgão como a bexiga, que guarda o xixi, o médico usa um fio que o corpo consegue dissolver sozinho depois, porque um fio que fica lá para sempre pode virar uma pedrinha incômoda."},{"id":"b13-tecnica-operatoria-q04","number":9,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Considerando os fios cirúrgicos utilizados para sutura, assinale a alternativa correta:","options":{"A":"O fio de PDS é monofilamentar e inabsorvível.","B":"O fio de categute é um dos que causam menor reação tecidual.","C":"O fio de vicryl permanece com sua força tênsil em mais de 50% em 5 semanas.","D":"O fio de monocryl é monofilamentar e produz reação tecidual mínima.","E":"O fio de prolene é multifilamentar e absorvível."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O Monocryl (poliglecaprone) é um fio monofilamentar absorvível que causa reação tecidual mínima.\nPor que as outras estão erradas:\nA: PDS é absorvível.\nB: Catgut causa muita reação tecidual.\nC: Vicryl perde 50% da força tênsil em 3 semanas, não 5.\nE: Prolene é monofilamentar e não absorvível.\nPonto de prova: Características dos fios cirúrgicos.\nFlashcard sugerado: Fio monofilamentar absorvível com mínima reação? Monocryl.\nPérola: Monocryl é monofilamentar e de baixa reação.\nArmadilha: Confundir PDS, Vicryl e Prolene.","tags":["Clínica Médica","Medicina Interna","Reparo de Feridas","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Existe um fio de costura cirúrgica fininho e único, que o corpo absorve sozinho e quase não causa irritação na pele — por isso é uma ótima escolha quando se quer o mínimo de incômodo."},{"id":"b13-tecnica-operatoria-q05","number":10,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Em relação aos anestésicos locais, assinale a alternativa CORRETA.","options":{"A":"A potência dos anestésicos locais tem relação direta com a lipossolubilidade da droga.","B":"Os do grupo amida têm reações alérgicas mais frequentes que os do grupo éster.","C":"A duração de ação dos anestésicos locais tem relação inversa com o seu grau de ligação às proteínas plasmáticas.","D":"A velocidade de ação dos anestésicos locais tem relação direta com o seu grau de ionização.","E":"Os do grupo amida têm metabolização pela pseudocolinesterase plasmática, fazendo com que sua duração anestésica seja menor, quando comparada aos do grupo éster."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A potência dos anestésicos locais tem relação direta com a sua lipossolubilidade (quanto mais lipossolúvel, mais cruza a membrana, mais potente).\nPor que as outras estão erradas:\nB: As reações alérgicas são mais comuns nos ésteres, não amidas.\nC: A duração tem relação direta (não inversa) com a ligação a proteínas plasmáticas.\nD: A velocidade tem relação inversa com o grau de ionização (a forma não ionizada atravessa a membrana).\nE: As amidas são metabolizadas no fígado, ésteres pela pseudocolinesterase.\nPonto de prova: Propriedades farmacocinéticas dos anestésicos locais.\nFlashcard sugerido: Potência do AL se relaciona com o quê? Lipossolubilidade.\nPérola: Mais lipossolúvel = mais potente.\nArmadilha: Inverter as relações de potência e duração.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Quanto mais o remédio anestésico consegue se misturar na gordura das células do nervo, melhor ele entra e mais forte é o seu efeito para tirar a dor."},{"id":"b13-violencia-sexual-q04","number":11,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e náuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses e que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está atrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência sexual de seu vizinho de 25 anos de idade, há 2 anos, e que o mesmo a ameaça para que não conte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o penúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está positivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente compatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas cabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim como a paciente, pois não desejam a gestação. Com base nos dados do caso, sobre o período da última violência sexual, é correto afirmar:","options":{"A":"Não está compatível com a idade gestacional, visto que a gestação está com duração provável de 6 semanas e a violência ocorreu há 4 semanas.","B":"Está compatível com a idade gestacional e o abortamento legal, nesse caso, é permitido se for o desejo da paciente e dos seus pais.","C":"Está compatível com a idade gestacional, porém o abortamento legal, nesse caso, não é permitido já que se trata de paciente menor que 18 anos.","D":"Não está compatível com a idade gestacional, sendo necessária uma avaliação pelo Instituto Médico Legal para decidir o que deve ser feito."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A gestação de 6 semanas (calculada a partir da DUM) é compatível com a violência há 4 semanas (idade gestacional = semanas de fecundação + 2). O aborto é permitido se houver desejo da paciente e consentimento dos pais.\nPor que as outras estão erradas:\nA: Há compatibilidade entre a idade gestacional e o tempo do estupro.\nC: É permitido em menores com o consentimento dos responsáveis.\nD: Não é necessária avaliação do IML.\nPonto de prova: Cálculo de idade gestacional e permissivos legais para aborto.\nFlashcard sugerado: Gestação de 6 sem x relação há 4 sem = compatível? Sim.\nPérola: IG = relação + 2 semanas.\nArmadilha: Achar que 6 semanas de gestação significa fecundação há 6 semanas.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Dor Abdominal","Interpretação de Exames","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Contando direitinho as semanas, o tempo da gravidez bate com a data da violência que a menina sofreu, então ela e a família podem pedir para interromper a gestação, já que isso é permitido nesses casos."},{"id":"b13-violencia-sexual-q05","number":12,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e náuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses e que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está atrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência sexual de seu vizinho de 25 anos de idade, há 2 anos, eque o mesmo a ameaça para que não conte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o penúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está positivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente compatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas cabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim como a paciente, pois não desejam a gestação. Considerando a violência sexual, nesse caso, é correto afirmar:","options":{"A":"Não deve ser realizada profilaxia para prevenção de ISTs nesse momento.","B":"É necessário prescrição de profilaxia para prevenção de HIV, sífilis, hepatite B, clamídia e gonococo no momento.","C":"A profilaxia para prevenção de HIV já não pode ser mais ser realizada pelo tempo de ocorrência do evento, mas é possível a profilaxia de sífilis, hepatite B, clamídia e gonococo.","D":"A profilaxia para prevenção de HIV e Hepatite B já não pode ser mais ser realizada pelo tempo de ocorrência do evento, mas é possível a profilaxia de sífilis, clamídia e gonococo."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A profilaxia para HIV tem prazo de 72h, portanto não pode mais ser feita (ocorreu há 4 semanas). A profilaxia para ISTs não virais e hepatite B ainda pode ser feita.\nPor que as outras estão erradas:\nB, C, D: O HIV não pode ser profilaxiado após 72h, e a hepatite B ainda pode ser profilaxiada com vacina/imunoglobulina.\nPonto de prova: Prazos para profilaxia pós-violência sexual.\nFlashcard sugerado: Prazo para PEP HIV? 72h. Para outras ISTs? Pode ser feito tardiamente.\nPérola: HIV = 72h. Outras ISTs = ainda dá tempo.\nArmadilha: Achar que hepatite B também não pode mais ser profilaxiada.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Dor Abdominal","Interpretação de Exames","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Para proteger contra o vírus HIV depois de uma violência, o remédio só funciona se for tomado em até três dias — como já se passaram semanas, não dá mais para usar esse remédio específico, mas ainda dá tempo de prevenir outras infecções."},{"id":"b13-derrame-pleural-q02","number":13,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Mulher, 40 anos de idade, procura pronto atendimento queixando-se de dispneia, tosse com expectoração amarelada e febre, há 48 horas. Nega comorbidades ou tabagismo. Ao exame físico, apresenta- se em regular estado geral, com FR: 28irpm, PA: 120x70mmHg, FC: 90bpm, Temperatura axilar: 38,0ºC, SatO :94%. Ao exame torácico, macicez à percussão e murmúrios vesiculares abolidos nos dois terços inferiores de hemitórax direito, sem ruídos adventícios à ausculta. Radiografia de tórax evidenciou derrame pleural à direita. **Com base nos dados do caso clínico, a conduta diagnóstica mais adequada, neste momento, é:**","options":{"A":"Não realizar procedimento invasivo, pois a presença de febre indica que o derrame é parapneumônico.","B":"Realizar toracocentese para esvaziamento completo do derrame, visto que há infecção associada.","C":"Puncionar na linha hemiescapular direita, na borda inferior do arco costal, logo abaixo do limite superior do derrame.","D":"Realizar toracocentese diagnóstica para avaliar a etiologia do derrame."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Na presença de febre e derrame pleural, está indicada toracocentese diagnóstica para avaliar a etiologia e classificar o líquido.\nPor que as outras estão erradas:\nA: Febre sugere parapneumônico, mas não exclui outras causas, sendo necessária a punção.\nB: Não se esvazia completamente o derrame de imediato sem análise prévia.\nC: Local de punção incorreto (deve ser no dorso, abaixo do limite superior do derrame).\nPonto de prova: Conduta diagnóstica em derrame pleural com febre.\nFlashcard sugerado: Derrame pleural com febre? Toracocentese diagnóstica.\nPérola: Derrame de causa incerta = punciona.\nArmadilha: Não puncionar por achar que é só parapneumônico.","tags":["Clínica Médica","Pneumologia","Trauma Torácico","Derrame Pleural","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando alguém tem febre e líquido acumulado ao redor do pulmão, o primeiro passo é sempre colher uma amostra desse líquido com uma agulha para descobrir do que se trata, antes de decidir qualquer outro tratamento."},{"id":"b13-violencia-sexual-q06","number":14,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Nuligesta, 19 anos, menarca aos 11 anos, DUM: não recorda, usa anticoncepcional hormonal oral, procura atendimento na urgência referindo ter sofrido estupro há 4 horas atrás. Em relação as profilaxias que esta mulher deve receber, a melhor opção é?","options":{"A":"Levonorgestrel; tenofovir, lamivudina e dolutegravir, azitromicina e ceftriaxona.","B":"Acetato de medroxiprogesterona, zidovudina e efavirenz, penicilina cristalina e ceftriaxone.","C":"O tempo decorrido da violência contraindica anticoncepção de emergência e profilaxia para HIV.","D":"DIU de cobre, zidovudina, lamivudina e lopinavir com ritonavir, azitromicina e penicilina cristalina."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A profilaxia padrão após violência sexual inclui anticoncepção de emergência (Levonorgestrel), PEP HIV (TDF+3TC+DTG) e profilaxia de ISTs bacterianas (azitromicina + ceftriaxona).\nPor que as outras estão erradas:\nB: Penicilina cristalina não é profilaxia padrão e o esquema ARV está desatualizado.\nC: O tempo decorrido (4h) indica uso das profilaxias.\nD: DIU de cobre pode ser usado, mas o esquema ARV e bacteriano descrito está incorreto.\nPonto de prova: Profilaxias pós-violência sexual.\nFlashcard sugerado: Profilaxia pós-estupro? Levonorgestrel + TDF/3TC/DTG + Azitro + Ceftriaxona.\nPérola: 4 profanias: gravidez, HIV, sífilis, gonorreia/clamídia.\nArmadilha: Usar esquemas antigos de ARV ou penicilina.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Depois de uma violência sexual, a pessoa recebe um conjunto de remédios ao mesmo tempo: um para evitar gravidez, um combo atual contra o HIV e antibióticos para as infecções bacterianas mais comuns."},{"id":"b13-tecnica-operatoria-q06","number":15,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Em relação aos anestésicos locais, afirma-se: 1\\. São exemplos de anestésicos do grupo amida: tetracaína\\, lidocaína\\, bupivacaína e ropivacaína\\. 2\\. São bases fracas que carregam uma carga positiva no grupo amida\\, em pH fisiológico\\, tendo\\, portanto\\, sua ação prejudicada em meio ácido\\. 3\\. Seu mecanismo de ação é o bloqueio dos canais de cálcio nas membranas dos neurônios\\, sendo as fibras nervosas menores bloqueadas antes das fibras maiores\\. Em relação às afirmações\\, apenas:","options":{"A":"1 e 2 são corretas.","B":"2 e 3 são corretas.","C":"1 e 3 são corretas.","D":"A 2 é correta.","E":"A 1 é correta"},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A assertiva 2 está correta: anestésicos são bases frac, ionizam em meio ácido, prejudicando a difusão pela membrana. A 1 está errada (tetracaína é éster) e a 3 está errada (bloqueiam canais de sódio, não cálcio).\nPor que as outras estão erradas:\nA, B, C, E: Contêm assertivas incorretas (tetracaína é éster e bloqueia sódio).\nPonto de prova: Farmacologia dos anestésicos locais.\nFlashcard sugerado: AL bloqueia qual canal? Sódio. Tetracaína é o quê? Éster.\nPérola: Tetracaína é éster. AL bloqueia sódio.\nArmadilha: Achar que AL bloqueia cálcio ou que tetracaína é amida.","tags":["Cirurgia","Anestesiologia","Distúrbios do Cálcio","Fisiopatologia","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Os anestésicos são como chaves fracas que só abrem a porta da dor quando o ambiente não está muito ácido; e essas chaves trancam a passagem de um sal (sódio) nos nervos, não a de outro (cálcio)."},{"id":"b13-violencia-sexual-q07","number":16,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e náuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses e que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está atrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência sexual de seu vizinho de 25 anos de idade, há 2 anos, eque o mesmo a ameaça para que não conte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o penúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está positivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente compatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas cabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim como a paciente, pois não desejam a gestação. Sobre o abortamento no Brasil, em caso de confirmação de gestação ocasionada por violência sexual, é correto afirmar:","options":{"A":"Pode ser realizado em qualquer momento da gestação, visto ser um direito da mulher que sofreu a violência sexual.","B":"Não é legalizado no Brasil.","C":"Pode ser realizado por profissional médico capacitado, de forma legalizada, desde que seja apresentado um boletim de ocorrência informando sobre a violência sexual.","D":"Pode ser realizado até 20ª ou 22ª semana, ou quando o feto pese até 500 gramas, e não necessita de boletim de ocorrência."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O aborto em caso de estupro pode ser realizado até 22 semanas ou feto até 500g, e não exige boletim de ocorrência.\nPor que as outras estão erradas:\nA: Há limite temporal/peso atualmente.\nB: É legalizado no Brasil.\nC: Não exige boletim de ocorrência.\nPonto de prova: Norma técnica de aborto legal por estupro.\nFlashcard sugerado: Limite para aborto por estupro no Brasil? 22 semanas ou 500g.\nPérola: Aborto por estupro: 22 sem ou 500g, sem BO.\nArmadilha: Achar que não tem limite de idade gestacional.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Abortamento","Interpretação de Exames","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"No Brasil, quando a gravidez vem de uma violência, a lei permite interromper até um certo ponto da gestação, e não é preciso levar nenhum boletim de ocorrência da polícia para isso."},{"id":"b13-semanais-q17","number":17,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"**Quais são os documentos a serem solicitados para a realização de um abortamento em uma gravidez por estupro?**","options":{"A":"Termo de responsabilidade, parecer técnico, boletim de ocorrência ou autorização judicial, termo de consentimento livre e esclarecido.","B":"Parecer técnico, termo de aprovação do procedimento, termo de responsabilidade, termo de consentimento livre e esclarecido e autorização judicial.","C":"Boletim de ocorrência, relato circunstanciado do evento, parecer técnico, termo de aprovação do procedimento e termo de responsabilidade.","D":"Relato circunstanciado do evento, parecer técnico, termo de aprovação do procedimento, termo de responsabilidade e termo de consentimento livre e esclarecido."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Os documentos necessários são: relato circunstanciado, parecer técnico, termo de aprovação do procedimento, termo de responsabilidade e termo de consentimento livre e esclarecido.\nPor que as outras estão erradas:\nA, B, C: Não exigem boletim de ocorrência ou autorização judicial.\nPonto de prova: Documentação para aborto legal.\nFlashcard sugerado: Documentos para aborto por estupro? Relato + parecer + aprovação + responsabilidade + consentimento.\nPérola: Não precisa de BO para abortar por estupro.\nArmadilha: Incluir o BO como documento essencial.","tags":["Clínica Médica","Medicina Interna","Abortamento","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Para fazer esse procedimento depois de uma violência, o hospital pede alguns papéis próprios da equipe de saúde — um relato da pessoa, uma avaliação médica e um termo de consentimento — mas nunca um boletim de ocorrência da polícia."},{"id":"b13-tecnica-operatoria-q07","number":18,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Paciente, sexo masculino, 27 anos de idade, é trazido por populares à Unidade de Pronto Atendimento (UPA) após ser vítima de agressão física. Relata que sofreu agressão com um soco na boca, há cerca de 45 minutos, após discussão em um bar. Refere ferimento em lábio inferior com dor e sangramento. Nega outros sintomas. Ao exame físico, bom estado geral, lúcido e orientado, presença de ferimento cortocontuso em região central do lábio inferior, medindo 3 cm de espessura total (exposição de mucosa), sem perda de substância e com sangramento ativo em pequena quantidade. **Indique o tipo de fio mais adequado para ser utilizado no reparo da lesão da mucosa.**","options":{"A":"Poligalactina.","B":"Poliamida.","C":"Poliéster.","D":"Polidioxanona."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O reparo de mucosa oral deve usar fios absorvíveis (como poligalactina/Vicryl) para não necessitar remoção.\nPor que as outras estão erradas:\nB, C, D: Fios não absorvíveis (poliamida, poliéster) ou de absorção muito lenta (PDS) são desconfortáveis e exigem retirada na mucosa.\nPonto de prova: Fios em sutura de mucosa.\nFlashcard sugerado: Sutura de mucosa oral usa qual fio? Absorvível (Vicryl).\nPérola: Mucosa gosta de absorvível.\nArmadilha: Usar fio não absorvível que incomoda o paciente.","tags":["Cirurgia","Trauma","Interpretação de Exames","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Para costurar a parte de dentro da boca, o médico usa um fio que se dissolve sozinho, assim ninguém precisa voltar para tirar o ponto de um lugar tão incômodo de mexer."},{"id":"b13-violencia-sexual-q09","number":19,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Mulher, 40a, procura o serviço para orientação sobre aborto legal. Refere estar na sétima semana de gestação, após estupro, sem registro de Boletim de Ocorrência. Antecedente pessoal: profissional do sexo, faz uso de preservativos em todas as relações profissionais. A orientação é que ela:","options":{"A":"Não tem direito ao aborto legal, por impossibilidade da confirmação do estupro.","B":"Deve registrar queixa na Delegacia de Defesa da Mulher para o aborto legal.","C":"Deve obter autorização judicial para ter direito ao aborto legal.","D":"Tem direito ao aborto legal mesmo sem a realização do Boletim de Ocorrência."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Mesmo sem boletim de ocorrência, a vítima de estupro tem direito ao aborto legal, bastando o relato circunstanciado.\nPor que as outras estão erradas:\nA, B, C: Não é necessário provar o estupro, registrar queixa ou obter autorização judicial.\nPonto de prova: Direito ao aborto legal sem BO.\nFlashcard sugerado: Aborto por estupro precisa de BO? Não.\nPérola: A palavra da vítima basta.\nArmadilha: Exigir registro policial.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Abortamento","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Mesmo sem ter feito boletim de ocorrência, e não importando qual seja o trabalho da pessoa, ela tem o mesmo direito de qualquer outra de interromper uma gravidez causada por violência."},{"id":"b13-violencia-sexual-q10","number":20,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Jovem de 24 anos chega ao serviço de saúde relatando estar grávida de 8 semanas, após ter sofrido violência sexual, e desejando interromper a gravidez. Não realizou nenhum boletim de ocorrência e não possui ordem judicial, tendo apenas passado por atendimento em unidade de saúde na época da violência. Ela deve ser informada de que tem direito ao aborto:","options":{"A":"Após início de ação penal e notificação policial.","B":"Mediante realização de boletim de ocorrência.","C":"Com apresentação de autorização judicial.","D":"Sem procedimento policial ou judicial."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O aborto por estupro independe de procedimento policial ou judicial.\nPor que as outras estão erradas:\nA, B, C: Não exige ação penal, boletim de ocorrência ou ordem judicial.\nPonto de prova: Legislação do aborto por estupro.\nFlashcard sugerado: Aborto por estupro precisa de ordem judicial? Não.\nPérola: Sem juiz, sem polícia, só a palavra.\nArmadilha: Achar que precisa de autorização judicial.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Abortamento","Conhecimento Conceitual","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Ela não precisa passar pela polícia nem pedir permissão a um juiz para ter o direito de interromper essa gravidez."},{"id":"b13-redes-atencao-q01","number":21,"collectionBlock":13,"documentBlock":13,"area":"Medicina de Família e Comunidade","topic":"Redes de Atenção à Saúde","stem":"Os cinco gestores da Região de Saúde (RS) X solicitaram uma reunião extraordinária da Comissão Intergestores Regional (CIR) da Região de Saúde Y para discutir especificamente duas questões: a falta de Agentes Comunitários que estava prejudicando o cadastramento da população nas Unidades de Atenção Primária e a fila de espera de 8 meses para a realização de colonoscopia, disponibilizada apenas no município sede da RS para enfrentar esse problema, os gestores fizeram a pactuação de tentar organizar colaborativamente o sistema de saúde regional nos formatos de Redes de Atenção à Saúde (RAS), pois eles acreditavam ser esse o caminho mais acertado para se melhorar o atendimento de saúde à população. Quais elementos constitutivos da RAS estavam prejudicados na RS do caso descrito?","options":{"A":"Estrutura operacional e modelo de atenção","B":"Modelo de atenção e sistemas logísticos.","C":"Sistemas logísticos e governança.","D":"Gestão de base populacional e sistemas de apoio."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O caso demonstra falhas na gestão de base populacional (falta de agentes comunitários) e nos sistemas de apoio (fila de espera para colonoscopia).\nPor que as outras estão erradas:\nA, B, C: Embora pertinentes, a questão foca nos sistemas de apoio e gestão de base populacional descritos no caso.\nPonto de prova: Elementos constitutivos das Redes de Atenção à Saúde (RAS).\nFlashcard sugerado: O que compõe a RAS? Gestão de base populacional, sistemas de apoio e logístico.\nPérola: RAS precisa de gestão populacional e apoio.\nArmadilha: Confundir com modelo de atenção.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Faltavam duas coisas importantes para o sistema de saúde daquela região funcionar bem: gente para visitar e cadastrar as famílias, e exames especializados disponíveis rápido o suficiente para todo mundo."},{"id":"b13-tecnica-operatoria-q08","number":22,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Com relação aos fios cirúrgicos, assinale a alternativa correta:","options":{"A":"O fio de seda é feito a partir do bicho Bombyx mori.","B":"Os fios de algodão são fibras trançadas de algodão e poliéster.","C":"A polidioxanona é um fio sintético trançado, sendo de absorção lenta.","D":"Os fios de ácido poliglicólico são ideais para a síntese cutânea.","E":"O fio de Catgut é feito a partir do intestino de gatos de laboratório."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A seda é um fio natural não absorvível, produzido a partir do casulo do bicho-da-seda (Bombyx mori).\nPor que as outras estão erradas:\nB: Algodão é fibra vegetal, não de poliéster.\nC: PDS é monofilamentar, não trançado.\nD: Ácido poliglicólico causa reação e não é ideal para pele.\nE: Catgut é feito de intestino de ovelhas ou bovinos, não de gatos.\nPonto de prova: Origem e características dos fios cirúrgicos.\nFlashcard sugerado: De onde vem a seda? Do bicho-da-seda (Bombyx mori).\nPérola: Catgut é de ovelha/vaca, não de gato.\nArmadilha: Achar que catgut vem de gato.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"O fio de seda usado em cirurgia vem do casulo de uma lagartinha chamada bicho-da-seda, e o fio chamado 'catgut', apesar do nome parecido, não vem de gatos — vem do intestino de ovelhas ou bois."},{"id":"b13-derrame-pleural-q03","number":23,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Paciente com história de dispneia, com 2 semanas de evolução e piora progressiva. Constatou-se na investigação derrame pleural a esquerda, do qual foi feita toracocentese diagnóstica, com os resultados que se seguem: LDH=180 U/ L, proteínas totais=4,1 g/ dL, glicose=84 mg/ dL, adenosina desaminase=12 UI/ L, bacterioscopia, cultura para germes comuns e citologia oncótica negativas. Exames séricos: LDH=200 U/L (referência 135- 225), Proteínas Totais=6,8 g/dL (referência 6,5-8,1 g/dL). O próximo passo da investigação deve ser:","options":{"A":"Analisar a função hepática.","B":"Angiotomografia pulmonar.","C":"Dosagem sérica de NT-pro-BNP.","D":"Analisar novamente o líquido pleural.","E":"Avaliar a positividade para fator reumatoide."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O líquido é exsudato (LDH pleural/sérico = 180/200 = 0.9 > 0.6) com ADA baixo e cultura negativa. O próximo passo em exsudato não parapneumônico/tuberculoso é investigar embolia pulmonar.\nPor que as outras estão erradas:\nA, C, D, E: São etapas de investigação secundária, mas a embolia é causa comum de exsudato sem causa clara.\nPonto de prova: Investigação de derrame pleural exsudativo de causa não óbvia.\nFlashcard sugerado: Exsudato sem causa aparente em adulto? Pense em TEP.\nPérola: Exsudato misterioso = AngioTc.\nArmadilha: Não reconhecer o exsudato.","tags":["Clínica Médica","Pneumologia","Dispneia","Derrame Pleural","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"O líquido do pulmão não é do tipo mais simples, mas também não parece uma infecção comum. Quando isso acontece sem explicação clara, o médico deve pensar em um coágulo preso no pulmão e pedir um exame de imagem para confirmar."},{"id":"b13-violencia-sexual-q11","number":24,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Em relação ao atendimento de adolescentes vítimas de violência sexual, assinale a alternativa **CORRETA**.","options":{"A":"As unidades de atenção primária não estão preparadas para atendimento de uma adolescente vítima de violência sexual.","B":"Adolescentes vítimas de violência sexual devem ser atendidas exclusivamente na presença da mãe.","C":"O médico da família e comunidade deve sempre referenciar a adolescente com urgência ao ginecologista.","D":"As unidades de saúde, em todos os níveis de cuidado, devem estar capacitadas para o atendimento e o cuidado de uma adolescente vítima de violência sexual."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Todos os níveis de cuidado, incluindo a APS, devem estar capacitados para acolher e iniciar o atendimento à vítima de violência sexual.\nPor que as outras estão erradas:\nA: A APS está preparada e deve atender.\nB: Pode ser atendida sem a presença da mãe, garantindo sigilo.\nC: O médico de família pode e deve realizar o atendimento inicial.\nPonto de prova: Atendimento à violência sexual na APS.\nFlashcard sugerado: Onde atender vítima de violência sexual? Em qualquer nível de atenção.\nPérola: A violência começa a ser cuidada na porta de entrada que a mulher procurar.\nArmadilha: Achar que só o ginecologista atende.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Toda unidade de saúde, desde o postinho do bairro até o hospital, precisa estar preparada para acolher e cuidar de uma adolescente que sofreu violência sexual — não é só trabalho do especialista."},{"id":"b13-derrame-pleural-q04","number":26,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um paciente de 25 anos, portador de paralisia cerebral foi trazido ao hospital por familiares, por apresentar desconforto respiratório há cerca de duas semanas. Ao exame físico, havia tiragem nos espaços intercostais direitos. À ausculta, percebia-se abolição do murmúrio vesicular no hemitórax direito (HTD), onde também não se identificava frêmito tóraco- vocal ou ressonância vocal. À percussão do HTD, obtinha-se som submaciço. Qual dos diagnósticos abaixo justificaria esses achados do exame físico?","options":{"A":"Tuberculose pleural.","B":"Aspiração de corpo estranho.","C":"Pneumonia lobar.","D":"Asma brônquica.","E":"Pneumotórax."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Os achados (retração do hemitórax, macicez, abolição do murmúrio vesicular) indicam atelectasia. Em criança com paralisia cerebral, aspiração de corpo estranho é causa comum de atelectasia obstrutiva.\nPor que as outras estão erradas:\nA: Tuberculose pleural geralmente dá derrame.\nC: Pneumonia dá consolidação (egofonia, MV aumentado).\nD: Asma dá sibilos e hiperinsuflação.\nE: Pneumotórax dá hipersonoridade.\nPonto de prova: Semiologia respiratória e diagnóstico diferencial.\nFlashcard sugerado: Retração + macicez + MV abolido = Atelectasia.\nPérola: Atelectasia retrai e abole o MV.\nArmadilha: Confundir com pneumonia (que dá consolidação).","tags":["Clínica Médica","Medicina Interna","Trauma Torácico","Interpretação de Exames","Assistência Hospitalar","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Uma parte do pulmão encolheu porque algo entalou e bloqueou a passagem de ar — em pessoas com dificuldade de engolir, é comum que um pedacinho de comida ou objeto entre no lugar errado e cause esse bloqueio."},{"id":"b13-pneumonia-q02","number":27,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Paciente do sexo masculino, de 76 anos, pardo, tabagista 40 anos/ maço, foi internado em um hospital de atenção secundária, por apresentar tosse com escarro purulento e raios de sangue, temperatura axilar de 38 °C, dor torácica e rouquidão. O paciente relatou que esta era a sua segunda internação por essas manifestações nos últimos três meses, tendo o episódio anterior melhorado com uso de amoxicilina- clavulanato, mas evoluído com hiporexia, astenia e perda de peso no mesmo período. As manifestações atuais se iniciaram havia dois dias. No exame do tórax, o paciente apresentava à ausculta murmúrio vesicular abolido em hemitórax direito e, à percussão, macicez em base de hemitórax direito e hipersonoridade logo acima da área de macicez. No caso desse paciente, as hipóteses diagnósticas a serem cogitadas são:","options":{"A":"Silicose, tuberculose e pneumotórax.","B":"Pneumonia pós-obstrutiva, derrame pleural e neoplasia pulmonar.","C":"Tromboembolismo pulmonar e neoplasia de cabeça e pescoço.","D":"Granulomatose eosinofílica com poliangiíte e infecção de vias aéreas superiores."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Tabagista com hemoptise, febre e derrame. A combinação de macicez (derrame/atelectasia) e hipersonoridade acima (pneumotórax/compensação) sugere neoplasia obstruindo brônquio, causando pneumonia pós-obstrutiva e derrame.\nPor que as outras estão erradas:\nA, C, D: Não explicam bem o conjunto de hemoptise, derrame e hipersonoridade/macicez no tabagista.\nPonto de prova: Hipóteses diagnósticas em paciente tabagista com hemoptise.\nFlashcard sugerado: Tabagista com hemoptise e pneumonia de repetição? Neoplasia.\nPérola: Hemoptise + tabagismo = câncer até prova em contrário.\nArmadilha: Não pensar em obstrução tumoral.","tags":["Clínica Médica","Medicina Interna","Trauma Torácico","Tabagismo","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Num fumante que tosse com sangue e vive tendo a mesma infecção no pulmão sem melhorar de vez, o médico precisa pensar que pode haver algo entupindo a passagem de ar, o que causa infecção repetida e acúmulo de líquido."},{"id":"b13-derrame-pleural-q05","number":28,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Paciente de 40 anos de idade, sexo masculino, compareceu ao pronto- socorro com história de tosse produtiva e expectoração mucopurulenta, de coloração “esverdeada”, dor ventilatória- dependente em hemitórax direito, taquidispneia e febre alta, constante, havia 1 semana. Realizou exame radiográfico de tórax, em incidências posteroanterior e Laurell, com imagem radiopaca de consolidação em lobo pulmonar médio e derrame pleural à direita. Nessa situação, qual é a conduta subsequente adequada para esse paciente?","options":{"A":"Tomografia de tórax.","B":"Toracocentese à direita.","C":"Ultrassonografia de tórax.","D":"Exame de escarro com pesquisa de BAAR."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Paciente com pneumonia e derrame pleural à direita necessita de toracocentese para análise bioquímica do líquido.\nPor que as outras estão erradas:\nA, C, D: A tomografia ou USG não substituem a análise do líquido, e BAAR não é o primeiro passo.\nPonto de prova: Conduta frente a derrame pleural parapneumônico.\nFlashcard sugerado: Derrame parapneumônico à Rx? Toracocentese.\nPérola: Tem derrame e febre, manda puncionar.\nArmadilha: Pedir TC antes de puncionar.","tags":["Clínica Médica","Pneumologia","Trauma Torácico","Derrame Pleural","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando a pessoa tem infecção no pulmão junto com líquido acumulado ao redor dele, o próximo passo é colher uma amostra desse líquido com uma agulha para descobrir exatamente do que se trata."},{"id":"b13-violencia-sexual-q13","number":29,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"No que se refere ao aborto legal no Brasil, julgue os itens a seguir. I Quando ausentes as situações de estupro ou de feto anencéfalo, há permissão do aborto por risco de vida para a mulher, situação em que é aconselhável avaliação clínica por pelo menos dois médicos, sendo um deles obstetra. II Em caso de estupro, a apresentação de boletim de ocorrência policial sobre tal fato não é um requisito para a permissão do aborto legal. III Havendo indicação de aborto por risco de vida materno, o procedimento somente pode ser realizado se atendidos os seguintes dois critérios, simultaneamente: máximo de 22 semanas de gestação e feto pesando até 500 g. Assinale a opção correta.","options":{"A":"Apenas o item I está certo.","B":"Apenas o item III está certo.","C":"Apenas os itens I e II estão certos.","D":"Apenas os itens II e III estão certos."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: I (aborto por risco de vida é permitido e ideal com avaliação de 2 médicos) e II (aborto por estupro não exige BO) estão corretos. III está errado (risco de vida não tem limite de IG).\nPor que as outras estão erradas:\nA, B, D: Contêm afirmações erradas sobre o item III.\nPonto de prova: Permissivos legais para aborto.\nFlashcard sugerado: Aborto por risco de vida tem limite de IG? Não.\nPérola: Risco de vida = sem prazo. Estupro = 22 sem/500g.\nArmadilha: Achar que risco de vida tem limite.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Abortamento","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Quando a gravidez ameaça a vida da mãe, o aborto pode ser feito em qualquer fase, sem prazo, avaliado por pelo menos dois médicos; já no caso de violência sexual, também não é preciso boletim de ocorrência."},{"id":"b13-derrame-pleural-q06","number":30,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Uma paciente com 54 anos apresenta tosse com expectoração e astenia há 5 dias, acompanhada de dispneia aos médios esforços e um pico febril. Ao exame físico, encontra- se consciente, contatuante, descorada (+2/ +4), desidratada (+2/ +4), com pressão arterial de 90 × 60 mmHg, frequência respiratória de 23 incursões respiratórias por minuto, frequência cardíaca de 120 batimentos por minuto, saturação O2 de 90% em ar ambiente, murmúrio vesicular presente em hemitórax direito e diminuído em hemitórax esquerdo, abolido em base esquerda, sem ruídos adventícios; radiografia de tórax demonstrou derrame pleural à esquerda. Foi realizada toracocentese, seguida de drenagem pleural fechada à esquerda. O líquido, de aspecto turvo, foi encaminhado para análise, sendo confirmado empiema pleural. Acerca do líquido analisado, infere-se que","options":{"A":"O pH foi maior que 7,2.","B":"A dosagem de LDH foi superior a 1.000 UI.","C":"A dosagem de glicose foi superior a 60 mg/dL.","D":"A dosagem de proteínas foi inferior a 3 g/100 ml."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Empiema caracteriza-se por LDH > 1000 UI.\nPor que as outras estão erradas:\nA: pH no empiema é < 7.2.\nC: Glicose é < 60 mg/dL.\nD: Proteínas no exsudato são > 3 g/dL.\nPonto de prova: Critérios laboratoriais de empiema.\nFlashcard sugerado: LDH no empiema é quanto? > 1000 UI.\nPérola: Empiema: pH < 7.2, glic < 60, LDH > 1000.\nArmadilha: Confundir os pontos de corte.","tags":["Clínica Médica","Pneumologia","Trauma Torácico","Derrame Pleural","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando o líquido do pulmão vira pus de verdade (uma infecção grave), um dos sinais no exame é uma enzima aparecendo bem alta no resultado."},{"id":"b13-pneumonia-q03","number":31,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Um paciente com 20 anos, previamente hígido, é recebido em pronto atendimento referindo que iniciou, há cinco dias, tosse produtiva acompanhada de astenia e febre diária entre 38 e 39 °C e que evoluiu com dor no hemitórax direito, que piorava com inspiração profunda e dispneia progressiva. Conta que procurou médico há 3 dias, o qual lhe prescreveu analgésicos e anti- inflamatórios, não tendo obtido melhora significativa do quadro. Ao exame físico, o paciente encontra-se em regular estado geral, com expansibilidade da caixa torácica reduzida à direita, frêmito toracovocal reduzido, com submacicez e murmúrio vesicular abolido em base pulmonar à direita. Com base na situação apresentada, a hipótese diagnóstica mais provável é:","options":{"A":"Pneumonia viral complicada com atelectasia.","B":"Neoplasia de pulmão complicada com atelectasia.","C":"Tuberculose pulmonar complicada com pneumotórax.","D":"Pneumonia bacteriana complicada com derrame pleural."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Febre, tosse, dor pleurítica e sinais de derrame (submacicez, MV abolido) indicam pneumonia complicada com derrame pleural.\nPor que as outras estão erradas:\nA, B, C: Vírus, neoplasia e TB/pneumotórax não fecham o quadro agudo infeccioso com derrame típico.\nPonto de prova: Diagnóstico de pneumonia complicada.\nFlashcard sugerado: Pneumonia + dor pleurítica + MV abolido = Derrame parapneumônico.\nPérola: Agudo, febril e macio = parapneumônico.\nArmadilha: Achar que é neoplasia.","tags":["Clínica Médica","Medicina Interna","Trauma Torácico","Dispneia","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Febre, dor no peito que piora ao respirar fundo e um som mais 'cheio' ao bater na parte de baixo das costas mostram que uma infecção bacteriana no pulmão já juntou líquido ao redor dele."},{"id":"b13-violencia-sexual-q14","number":32,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Mulher de 22 anos de idade, profissional do sexo, está grávida de 5 semanas. Comparece ao serviço de saúde solicitando um aborto legal por ter sido vítima de estupro e concorda em assinar o termo de consentimento para esse procedimento. O médico que a atende poderá","options":{"A":"Rejeitar a solicitação pela impossibilidade de se comprovar o estupro devido a atividade profissional da paciente.","B":"Encaminhar a paciente à Delegacia da Mulher para assinar Termo de Autorização para Aborto Legal antes de decidir pelo procedimento.","C":"Atender seu pedido após abrir boletim de ocorrência relatando o estupro e aprovação de mais 2 membros da equipe de saúde.","D":"Atender seu pedido após receber cópia de boletim de ocorrência do estupro e termo de aprovação de interrupção da gestação assinado por 3 profissionais de saúde.","E":"Atender o pedido mediante relatório médico e termo de aprovação de interrupção da gestação assinado por 3 profissionais de saúde."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O médico pode atender mediante relatório médico e termo de aprovação assinado por 3 profissionais de saúde, sem necessidade de BO.\nPor que as outras estão erradas:\nA, B, C, D: Exigem BO ou não se aplicam à norma atual do Ministério da Saúde.\nPonto de prova: Legislação sobre aborto por estupro.\nFlashcard sugerado: Aborto por estupro precisa de quantas assinaturas? Relato + termo de 3 profissionais.\nPérola: 3 assinaturas selam o aborto por estupro.\nArmadilha: Exigir BO.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Abortamento","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O médico pode atender o pedido dela com um relatório da própria equipe de saúde e a aprovação de mais dois profissionais, sem precisar de boletim de ocorrência nem se importar com a profissão dela."},{"id":"b13-tecnica-operatoria-q09","number":33,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Paciente com 70 kg está sendo submetido a drenagem de abscesso no cotovelo, sob anestesia local com lidocaína a 1% com vasoconstritor. Após usar 20 mi da solução, o paciente continua apresentando sensibilidade dolorosa na região. Qual das alternativas explicaria o quadro?","options":{"A":"O vasoconstritor não deveria ser usado nesse tipo de situação.","B":"A sensibilidade dolorosa persistente constitui sinal precoce de toxicidade.","C":"O anestésico local continua em sua forma solúvel (ionizada).","D":"A bupivacaína a 0,25% com vasoconstritor deveria ter sido usada no lugar da lidocaína.","E":"A dose de anestésico utilizada foi insuficiente."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A persistência de dor indica que o anestésico está na forma ionizada (solúvel), sem conseguir penetrar a membrana do nervo de forma eficaz.\nPor que as outras estão erradas:\nA, B, D, E: A dose de 20mL de lido a 1% (200mg) está longe da dose tóxica (4.5mg/kg = ~300mg). O problema é o pH ou técnica, não a dose.\nPonto de prova: Mecanismo de ação de anestésicos locais.\nFlashcard sugerado: AL não faz efeito por quê? Ionizado em pH ácido.\nPérola: Ionizado não anestesia.\nArmadilha: Achar que é toxicidade precoce.","tags":["Cirurgia","Anestesiologia","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Se depois de aplicar o anestésico a dor continua, na maioria das vezes é porque o remédio ainda está numa forma que não consegue atravessar a parede do nervo — não porque a dose foi baixa demais nem porque já é sinal de perigo."},{"id":"b13-pneumonia-q04","number":34,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Paciente masculino de 72 anos dá entrada em hospital com quadro de tosse produtiva e confusão mental há 02 dias. Ao exame físico, apresenta FC: 112 bpm; FR: 32 irpm; satO2: 96%; T: 38,5oC; PA: 88x55 mmHg e ausculta pulmonar com murmúrios vesiculares diminuídos e estertores crepitantes em base pulmonar esquerda. Foi realizada radiografia de tórax a qual evidenciou consolidações em base e terço médio do pulmão esquerdo. A respeito do caso descrito, assinale a alternativa correta.","options":{"A":"O paciente pode ser tratado ambulatorialmente com macrolídeos ou betalactâmicos, a depender de fatores como: uso recente de antibióticos, história de alergia a essas drogas e fator de risco para resistência.","B":"O paciente tem indicação de internação em UTI e tratamento com amoxicilina + clavulanate ou macrolídeos, a depender de fatores como: uso recente de antibióticos, história de alergia a essas drogas e fator de risco para resistência.","C":"TC de tórax é mandatária antes de se iniciar o tratamento.","D":"Se a etiologia for viral, provavelmente a procalcitonina estará elevada.","E":"O paciente possui indicação para tratamento em UTI, podendo utilizar cefalosporinas de terceira geração (ceftriaxona ou cefotaxima)."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: CURB-65: Confusão, FR>30 (FR=32), e PA 88x55 (PAS<90). Total 3 pontos = Internar UTI. Cefalosporina de 3ª geração está indicada.\nPor que as outras estão erradas:\nA: Ambulatorial está errado (3 pontos).\nB: Amox/clavulanato não é para UTI.\nC: TC não é mandatória.\nD: Etiologia viral não eleva PCR significativamente.\nPonto de prova: Escore CURB-65 e tratamento de PAC grave.\nFlashcard sugerado: PAC com 3 pontos no CURB-65? UTI + Ceftriaxona.\nPérola: CURB 3 = UTI.\nArmadilha: Tratar ambulatorialmente.","tags":["Clínica Médica","Medicina Interna","Tosse","Interpretação de Exames","Pessoa Idosa","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Esse senhor está confuso, respirando muito rápido e com a pressão baixa — tudo isso junto mostra uma pneumonia grave, que precisa de UTI e de um antibiótico forte."},{"id":"b13-derrame-pleural-q07","number":35,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"São causas de derrame pleural classificado como exsudato, exceto:","options":{"A":"Síndrome de Meigs.","B":"Uremia.","C":"Tuberculose pleural.","D":"Mixedema."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Mixedema (hipotireoidismo) geralmente causa transudato, não exsudato.\nPor que as outras estão erradas:\nA, B, C: Síndrome de Meigs, uremia e TB são causas clássicas de exsudato.\nPonto de prova: Etiologias de derrame pleural.\nFlashcard sugerado: Mixedema causa que tipo de derrame? Transudato.\nPérola: Mixedema = transudato.\nArmadilha: Achar que mixedema é exsudato.","tags":["Clínica Médica","Pneumologia","Derrame Pleural","Classificação Clínica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando a tireoide está muito preguiçosa, o líquido que se acumula no pulmão costuma ser do tipo mais simples e aguado, diferente das outras causas dessa lista, que dão um líquido mais 'grosso'."},{"id":"b13-pneumonia-q05","number":36,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Um policial leva ao pronto-socorro um homem em situação de rua, com idade aproximada de 55 anos, que está com febre (temperatura axilar de 38,8 °C) e com tosse com expectoração pútrida abundante, iniciadas há várias semanas. O paciente é etilista, usuário de crack e não sabe informar sobre a existência de doenças prévias. Foi realizada uma radiografia de tórax, a qual pode ser vista a seguir. Com base nesse quadro clínico, assinale a opção que indica, respectivamente, o diagnóstico mais provável e a conduta inicial mais apropriada.","options":{"A":"Tromboembolismo pulmonar; iniciar anticoagulação.","B":"Abscesso pulmonar; iniciar antibioticoterapia empírica.","C":"Neoplasia pulmonar primária; aguardar broncoscopia e biópsia.","D":"Tuberculose pulmonar; aguardar resultado de cultura de M. tuberculosis."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: B.\nPor que está certa: Febre, escarro pútrido e paciente etilista indicam abscesso pulmonar. Conduta é antibioticoterapia empírica.\nPor que as outras estão erradas:\nA, C, D: TEP, neoplasia e TB não justificam escarro pútrido de início agudo.\nPonto de prova: Diagnóstico e conduta em abscesso pulmonar.\nFlashcard sugerado: Escarro pútrido = Abscesso pulmonar.\nPérola: Escarro fétido = anaeróbio/abscesso.\nArmadilha: Aguardar biópsia para neoplasia.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Tosse","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Um catarro com cheiro muito forte e podre, numa pessoa que bebe muito álcool, é sinal clássico de uma bolsa de pus se formando dentro do pulmão, e o tratamento é começar antibiótico logo."},{"id":"b13-derrame-pleural-q08","number":37,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Paciente do sexo masculino, 73 anos, apresentou desconforto respiratório progressivo na última semana e foi avaliado no pronto- socorro. Ao exame físico, apresentava, na ausculta pulmonar, murmúrio vesicular abolido em 2/3 inferiores, tendo sido confirmado derrame pleural moderado por radiografia de tórax. Após ser avaliado pela cirurgia torácica, optou- se por toracocentese de alívio e diagnóstica. Os exames séricos do paciente eram: Proteína total 3,8/ dl, DHL 154 U/ L. A rotina laboratorial de líquido pleural: Proteína total 1,7 g/ dl, DHL 60 U/ L. Observação: Desidrogenase láctica (DHL) – valores séricos normais de referência 120 a 246 U/L. Após análise dos resultados dos exames séricos e da rotina do líquido pleural do paciente, são aplicados os critérios de Light. Assinale a alternativa correta em relação a esse caso: <br>","options":{"A":"Os resultados da análise indicam características de transudato, e insuficiência cardíaca poderia ser uma das hipóteses diagnósticas.","B":"A relação entre LDH do líquido pleural/nível sérico preenche um dos critérios de Light, característico de exsudato.","C":"Os resultados da análise indicam características de exsudato pelos critérios de Light, e pneumonia bacteriana é uma das hipóteses diagnósticas.","D":"Para transudato, é necessário preencher pelo menos dois dos critérios de Light.","E":"Um dos critérios de Light é que o DHL do líquido pleural seja > 1/3 do valor do limite superior sérico."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Proteína pleural/sérica = 1.7/3.8 = 0.44 (<0.5) e LDH pleural/sérica = 60/154 = 0.38 (<0.6). É transudato. IC é a principal causa.\nPor que as outras estão erradas:\nB, C, D: Os critérios não preenchem exsudato. Para exsudato, basta 1 critério de Light.\nE: O critério de Light é LDH pleural > 2/3 do limite superior sérico, não 1/3.\nPonto de prova: Aplicação dos critérios de Light.\nFlashcard sugerado: Critérios de Light: Proteína > 0.5, LDH > 0.6 ou LDH > 2/3 do limite superior sérico.\nPérola: Basta um critério para ser exsudato.\nArmadilha: Exigir dois critérios para exsudato.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Critérios de Light","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Comparando os valores do líquido do pulmão com os do sangue, dá para ver que ele é do tipo mais simples e aguado, e a causa mais provável para esse tipo de líquido é o coração não estar bombeando bem."},{"id":"b13-pneumonia-q06","number":38,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Homem, 75 anos de idade, procura pronto- socorro por dispneia de longa data, principalmente ao subir ladeiras, com piora progressiva há 3 dias, associada a tosse com secreção amarelada em grande quantidade. Nega febre. Tem antecedente de hipertensão arterial sistêmica e tabagismo, com carga tabágica de 80 maços- ano. Está em uso de formoterol 2 vezes ao dia. Relata quadro semelhante há 2 meses quando foi internado para antibioticoterapia. Ao exame físico, está com estado geral regular, FC: 105 bpm/minuto, FR: 35 irpm/minuto, temperatura axilar: 38°C, saturação periférica de oxigênio de 86% a.a. e PA: 110 x 78 mmHg. Ausculta pulmonar globalmente reduzida com estertores na base direita, sem outras alterações. Foram realizados testes de antígeno que descartaram infecção por influenza vírus e SARS- CoV-2. Entre as opções abaixo, a melhor antibioticoterapia para este paciente é:","options":{"A":"Levofloxacino.","B":"Ceftriaxone + oxacilina.","C":"Claritromicina.","D":"Amoxicilina com clavulanato."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Paciente com DPOC e exacerbação grave. Levofloxacino cobre os principais patógenos e atípicos, sendo opção válida em casos graves.\nPor que as outras estão erradas:\nB, C, D: Não são os esquemas de primeira linha recomendados para exacerbação grave de DPOC sem Pseudomonas.\nPonto de prova: Tratamento de exacerbação de DPOC.\nFlashcard sugerado: Exacerbação grave de DPOC? Levofloxacino ou ceftriaxona/azitro.\nPérola: DPOC grave pede respiratório de largo espectro.\nArmadilha: Usar amoxicilina simples.","tags":["Clínica Médica","Medicina Interna","Dispneia","Tosse","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Essa pessoa tem uma doença crônica de pulmão que piorou bastante, com falta de ar grave, e nesse caso um antibiótico mais potente, que cobre vários tipos de bactéria de uma vez, é a melhor escolha."},{"id":"b13-pneumonia-q07","number":39,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Dentre as alternativas a seguir, qual apresenta o agente infeccioso bacteriano mais comum na pneumonia adquirida na comunidade?","options":{"A":"Streptococcus pneumoniae.","B":"Mycoplasma pneumoniae.","C":"Streptococcus aureus.","D":"Chlamydia pneumoniae.","E":"Pseudomonas aeruginosa."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O Streptococcus pneumoniae (pneumococo) é o agente bacteriano mais comum da pneumonia adquirida na comunidade (PAC).\nPor que as outras estão erradas:\nB, C, D, E: Mycoplasma, Chlamydia, Staph aureus e Pseudomonas são menos frequentes globalmente.\nPonto de prova: Etiologia da PAC.\nFlashcard sugerado: Agente mais comum de PAC? Pneumococo.\nPérola: Pneumococo reina na PAC.\nArmadilha: Achar que é Mycoplasma.","tags":["Clínica Médica","Pneumologia","Pneumonia","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"A bactéria que mais causa pneumonia pega fora do hospital tem um nome comprido, pneumococo, e é ela a principal suspeita quando alguém adoece assim."},{"id":"b13-pneumonia-q08","number":40,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Um médico, trabalhando em uma unidade de pronto atendimento, atende um paciente de 70 anos com queixa de febre de início há 4 dias, acompanhada de tosse produtiva e astenia. O paciente é diabético e hipertenso, encontra- se consciente e orientado, porém, no momento, está com a visão prejudicada, devido à cirurgia recente de correção de catarata. Ele não tem tomado as medicações de uso contínuo por não estar conseguindo identificá-las. Seu filho, que mora há 450 Km de distância, chegará em 2 dias para poder acompanhá-lo. Ao exame físico, apresenta frequência respiratória de 24 irpm, pressão arterial de 100x64 mmHg, exame laboratorial: ureia 45 mg/dl e creatinina 0,6 mg/dL. Diante do exposto, qual seria a conduta adequada?","options":{"A":"Internar o paciente para início do tratamento, por possuir 4 pontos no escore de prognóstico “CURB-65.”","B":"O paciente pode realizar o tratamento ambulatorial por possuir apenas 1 ponto no escore de prognóstico “CURB-65”.","C":"Apesar de o paciente ter somente 1 ponto no escore de prognóstico “CURB-65”, devido às comorbidades e ao seu contexto social, a conduta mais adequada é interná-lo para o tratamento.","D":"O paciente pode realizar o tratamento ambulatorial por possuir apenas 2 pontos no escore de prognóstico “CURB-65”.","E":"Internar o paciente para início do tratamento, por possuir 3 pontos no escore de prognóstico “CURB-65.”"},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: CURB-65: idade >65 (1 ponto), FR > 24 (1 ponto). Tem 2 pontos, mas o contexto social (cego pós-cirurgia, mora só, filho longe) justifica a internação.\nPor que as outras estão erradas:\nA, B, D, E: Cálculo do escore ou conduta ambulatorial estão errados diante da pontuação e vulnerabilidade social.\nPonto de prova: Aplicação do CURB-65 e clínica social.\nFlashcard sugerado: CURB-65 2 pontos + vulnerabilidade social? Internar.\nPérola: Escore não é tudo; contexto social pesa.\nArmadilha: Usar só o escore sem ver o paciente.","tags":["Clínica Médica","Nefrologia","Síndrome Febril","Tosse","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"O placar de gravidade da pneumonia até dava para tratar em casa, mas como o senhor está sozinho, quase não enxerga por causa de uma cirurgia recente e não tem quem cuide dele por alguns dias, o mais seguro é internar mesmo assim."},{"id":"b13-violencia-sexual-q15","number":41,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Paciente, 29 anos, é trazida ao atendimento de urgência por autoridades policiais. A paciente relata ter sido agredida sexualmente quando voltava do trabalho. Chorosa e confusa, refere ter sido forçada a praticar sexo oral e coito vaginal. Não sabe dizer se o agressor usou preservativos. Nega doenças ou uso de medicamentos regulares. Ciclos menstruais regulares e é usuária de DIU T de cobre há cinco anos. Após acolhimento inicial, é levada para realização de exames laboratoriais e abordagem terapêutica. Sobre a assistência à paciente na urgência, é CORRETO afirmar que:","options":{"A":"Está indicado o uso de antirretrovirais por 60 dias.","B":"Não há necessidade de prescrição para contracepção de emergência.","C":"O tratamento profilático de IST deve ser iniciado até 72h após a agressão sexual.","D":"Iniciar prevenção para sífilis, tricomoníase e hepatite C nesse momento."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A paciente usa DIU de cobre, que é um método contraceptivo de alta eficácia, não havendo necessidade de anticoncepção de emergência.\nPor que as outras estão erradas:\nA: PEP HIV é por 28 dias, não 60.\nC: A profilaxia de IST deve ser iniciada o quanto antes, idealmente nas primeiras 72h.\nD: Tricomoníase e hepatite C não têm profilaxia padrão pós-exposição.\nPonto de prova: Manejo de vítima de violência sexual com DIU.\nFlashcard sugerado: Vítima de estupro com DIU de cobre? Não precisa de anticoncepção de emergência.\nPérola: DIU de cobre já protege a gestação.\nArmadilha: Prescrever contracepção de emergência à toa.","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Conduta Terapêutica","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Como ela já usa um método bem eficiente para não engravidar, não é preciso dar mais um remédio extra para evitar a gravidez depois da violência."},{"id":"b13-pneumonia-q09","number":42,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Infecções por Mycoplasma pneumoniae representam um diagnóstico desafiador na clínica médica. Assinale a alternativa que apresenta a combinação de testes que mostra o diagnóstico mais rápido e com maior sensibilidade das infecções por esse agente.","options":{"A":"PCR sérico e PCR de secreções respiratórias.","B":"Cultura respiratória e hemoculturas.","C":"Hemoculturas e testes sorológicos.","D":"Testes sorológicos e cultura respiratória.","E":"PCR das secreções respiratórias e testes sorológicos."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: O PCR das secreções respiratórias é o teste mais rápido e sensível para Mycoplasma, complementado por sorologia.\nPor que as outras estão erradas:\nA, B, C, D: Cultura demora muito e hemoculturas costumam ser negativas.\nPonto de prova: Diagnóstico de Mycoplasma pneumoniae.\nFlashcard sugerado: Diagnóstico de Mycoplasma? PCR respiratório + sorologia.\nPérola: Mycoplasma não tem parede, cultura é difícil.\nArmadilha: Pedir cultura de rotina.","tags":["Clínica Médica","Medicina Interna","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Para descobrir rápido se a infecção é causada por esse micróbio bem diferente dos outros, o melhor é buscar seu material genético direto na secreção do nariz ou garganta e completar com um exame de sangue que procura defesas contra ele."},{"id":"b13-tecnica-operatoria-q10","number":43,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Ao realizar a excisão de um cisto sebáceo sob anestesia local em um homem de 60 kg, um cirurgião decide utilizar lidocaína a 1% sem vasoconstrictor. Qual é o volume máximo seguro de lidocaína que pode ser administrado para garantir uma anestesia eficaz e minimizar os riscos de toxicidade?","options":{"A":"20 mL.","B":"30 mL.","C":"40 mL.","D":"50 mL.","E":"60 mL."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A dose máxima de lidocaína sem vasoconstritor é 4.5 mg/kg. Para 60kg, 4.5 x 60 = 270mg. Lidocaína 1% tem 10mg/mL. 270mg / 10 = 27mL. O volume máximo seguro mais próximo é 30mL.\nPor que as outras estão erradas:\nA, C, D, E: Não correspondem ao cálculo correto para 60kg.\nPonto de prova: Doses máximas de anestésicos locais.\nFlashcard sugerado: Dose máx lido sem vasoconstritor? 4.5 mg/kg.\nPérola: 4.5 (sem) vs 7 (com) mg/kg.\nArmadilha: Usar 7mg/kg sem vasoconstritor.","tags":["Cirurgia","Anestesiologia","Farmacologia Clínica","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Cada remédio anestésico tem uma dose máxima segura calculada pelo peso da pessoa, e para esse paciente de 60 kg, sem o remédio que aperta os vasinhos de sangue, o volume seguro é de cerca de 30 mL."},{"id":"b13-tecnica-operatoria-q11","number":44,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Uma criança do gênero masculino de 12 anos sofre queda da bicicleta e deu entrada no Pronto-Socorro 15 minutos após a ocorrência, apresentando um ferimento de 4,5 cm, superficial, acometendo pele e subcutâneo, em região pré-patelar direita. Há presença de sujidade (terra e grama) no ferimento. Cobertura antitetânica atualizada. Após a limpeza do ferimento, qual tipo de fio cirúrgico seria a melhor escolha para essa situação?","options":{"A":"Trançado não absorvível.","B":"Monofilamentar não absorvível.","C":"Monofilamentar absorvível.","D":"Trançado absorvível."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Região pré-patelar tem pouca cobertura de partes moles, alta tensão. Ferimento superficial e limpo requer fio não absorvível monofilamentar (nylon) para menor reação e retirada fácil.\nPor que as outras estão erradas:\nA: Trançado não absorvível aumenta risco de infecção.\nC: Monofilamentar absorvível tem baixa resistência para pele sob tensão.\nD: Trançado absorvível não é para pele.\nPonto de prova: Escolha de fios em ferimentos cutâneos.\nFlashcard sugerado: Sutura de pele em joelho? Monofilamentar não absorvível.\nPérola: Pele pede nylon (monofilamentar não absorvível).\nArmadilha: Usar absorvível onde há tensão.","tags":["Cirurgia","Trauma","Lesões Cutâneas","Conhecimento Conceitual","Adolescência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Numa área do corpo que estica bastante, como a frente do joelho, o melhor fio é um fio único que não some sozinho, porque ele aguenta a tensão da pele se mexendo sem se romper."},{"id":"b13-violencia-sexual-q16","number":45,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Uma paciente de 20 anos de idade deu entrada no pronto-socorro referindo ter sido vítima de abuso sexual hå duas horas, com queixa de sangramento vaginal de pequena monta, associado a escoriações pelo corpo. Em relação ao atendimento das pacientes vítimas de abuso sexual, assinale a alternativa correta:","options":{"A":"O caso deve ser referenciado ao Instituto Médico Legal de imediato, para exame clínico e para providências legais.","B":"A paciente deverá ser acolhida, o atendimento inicial e o tratamento das lesões deverão ser prestados e, depois disso, ela deverá ser aconselhada a procurar a delegacia para as devidas providências legais pertinentes ao caso.","C":"A profilaxia das doenças sexualmente transmissíveis e o tratamento das lesões somente poderão ocorrer após registro do boletim de ocorrência da autoridade policial.","D":"A paciente deverá acionar a delegacia de polícia para que o atendimento ocorra na presença da autoridade policial."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A vítima deve ser acolhida, tratar as lesões e iniciar profilaxias, para depois ser orientada a procurar a delegacia.\nPor que as outras estão erradas:\nA: Não se manda para o IML antes de tratar.\nC: As profilaxias não dependem de BO.\nD: Não se exige a polícia no atendimento.\nPonto de prova: Fluxo de atendimento à vítima de violência sexual.\nFlashcard sugerado: Ordem do atendimento pós-estupro? Acolher, tratar, orientar polícia depois.\nPérola: Saúde primeiro, polícia depois.\nArmadilha: Exigir BO para iniciar profilaxia.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Sangramento Vaginal","Conhecimento Conceitual","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O primeiro passo é acolher a pessoa, cuidar dos ferimentos e começar os remédios de proteção — só depois disso ela deve ser orientada a ir à delegacia, se quiser."},{"id":"b13-febre-sem-sinais-q01","number":46,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Lactente, 2 meses; peso: 5 kg; sem comorbidades. Os pais procuram atendimento em UPA devido à queixa de febre há dois dias variando de 38,5 – 38,8 °C associada a irritabilidade, choro inconsolável e redução das mamadas. Referem ainda redução da necessidade de troca de fraldas. Negam coriza, tosse e alteração do hábito intestinal. Negam contato da criança com pessoas com sintomas gripais. Ao exame físico: regular estado geral, irritada, choro sem lágrimas, boca seca, febril. (38,6 °C) FC: 200 bpm. FR: 65 ipm. SatO2 94% em ar ambiente. PA: 75 / 50 (66) mmHg. Fontanela anterior plana e normotensa. Otoscopia e Oroscopia sem alterações. AR. Murmúrio vesicular presente sem RA, RSC leve. ACV: 2 bulhas rítmicas e normofonéticas sem sopros. Abdome: semigloboso. RHA presentes. Sem massas ou visceromegalias. Pulsos periféricos finos. TEC 5 segundos. Diante do caso clínico, assinale a alternativa que apresenta o conjunto de exames iniciais mais adequados:","options":{"A":"Hemograma, PCR, hemocultura, gasometria arterial, eletrólitos, lactato, glicemia, urina tipo 1, urocultura, coagulograma, ureia, creatinina, TGO e TGP.","B":"Hemograma, PCR, gasometria arterial, eletrólitos, lactato, glicemia, coagulograma, TGO, TGP, urina tipo 1, ureia e creatinina.","C":"Hemograma, PCR, hemocultura, gasometria arterial, eletrólitos, RX de tórax, USG transfontanela e ecocardiograma.","D":"Hemograma, PCR, cultura de aspirado traqueal, pesquisa de vírus respiratório, coagulograma, ureia e creatinina."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Lactente febril <3 meses com sinais de gravidade (choque, FR 65, FC 200) necessita de investigação completa (hemograma, PCR, hemocultura, gaso, eletrólitos, urina, etc).\nPor que as outras estão erradas:\nB, C, D: Não incluem a investigação completa necessária para sepse neonatal/lactente grave.\nPonto de prova: Investigação de febre sem foco em lactente grave.\nFlashcard sugerado: Lactente febril grave? Hemograma, PCR, hemocultura, gaso, urina, eletrólitos.\nPérola: Bebê grave = painel completo de sepse.\nArmadilha: Esquecer a gasometria e eletrólitos.","tags":["Pediatria","Saúde da Criança","Síndrome Febril","Tosse","Conhecimento Conceitual","Primeira Infância"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Esse bebê tão pequeno está com sinais de que o corpo está lutando muito contra uma infecção (coração acelerado, mãos frias), então o médico precisa pedir uma bateria completa de exames de sangue e urina para achar e tratar a causa rápido."},{"id":"b13-violencia-sexual-q17","number":47,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Na unidade de emergência, uma jovem de 19 anos informa ter sofrido violência sexual, há cerca de 4 horas por um desconhecido. Assinale a alternativa CORRETA sobre como deverá ser sua atuação para dar conta das necessidades desta paciente:","options":{"A":"Encaminhar a paciente para exame com perito de medicina legal, com o objetivo de confirmar a agressão sexual e descrever as lesões genitais.","B":"Solicitar o beta-HCG, independente das demais condições clínicas da paciente, para permitir a prescrição de anticoncepção de emergência.","C":"Proceder aos testes rápidos para sífilis, hepatite B e HIV e prescrever a profilaxia para as IST bacterianas e virais.","D":"Prescrever Penicilina Cristalina 2 milhões de unidades intravenosa + Nitrofurantoína para profilaxia das IST bacterianas."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Testes rápidos devem ser feitos, e a profilaxia para IST virais (HIV, Hep B) e bacterianas (sífilis, gonococo, clamídia) prescritas.\nPor que as outras estão erradas:\nA: O IML não é prioridade no atendimento inicial médico.\nB: Beta-HCG não impede a prescrição da contracepção de emergência (levonorgestrel).\nD: Penicilina cristalina IV não é a profilaxia oral/padrão recomendada.\nPonto de prova: Atendimento inicial pós-violência sexual.\nFlashcard sugerado: Atendimento pós-estupro? Testes rápidos + profilaxia ISTs virais e bacterianas.\nPérola: Toda violência sexual = profilaxia viral e bacteriana.\nArmadilha: Aguardar exames para profilaxia.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Logo no primeiro atendimento, fazem-se testes rápidos para descobrir se já existem certas infecções, e ao mesmo tempo já se começam os remédios que previnem tanto os vírus quanto as bactérias transmitidas na violência."},{"id":"b13-redes-atencao-q02","number":48,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"Considerando os níveis de assistência à saúde, assinale a opção que corresponde a um serviço de atenção secundária ou de média complexidade:","options":{"A":"Consultórios de rua.","B":"Unidades Básicas de Saúde.","C":"Ambulatórios de cardiologia.","D":"Unidades de terapia Intensiva.","E":"Unidades de ensino e pesquisa."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Ambulatórios de especialidades (cardiologia) representam a atenção secundária/média complexidade.\nPor que as outras estão erradas:\nA, B: Atenção primária.\nD: Terciária (alta complexidade).\nE: Não é nível assistencial de saúde.\nPonto de prova: Níveis de atenção à saúde.\nFlashcard sugerado: Exemplo de atenção secundária? Ambulatório de cardiologia.\nPérola: Secundária = especialidades.\nArmadilha: Confundir UPA com secundária.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Um ambulatório de especialista, como o de cardiologia, é um exemplo de atendimento de nível médio — não é o postinho simples, nem o hospital de casos gravíssimos."},{"id":"b13-febre-sem-sinais-q02","number":49,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Pré-escolar, eutrófica, com vacinação do PNI em dia, sem história patológica pregressa, que não frequenta creche e, segundo a mãe\", está com febre há 24 horas e mais nada \". Exame físico: Tax: 37,8 °C, ativa, corada, hidratada, sem qualquer outra alteração. A conduta indicada neste momento, na presença de febre (37,8C), além da observação por 24 horas é:","options":{"A":"Intercalar os antitérmicos ibuprofeno e paracetamol.","B":"Administrar antitérmico e observar a diurese e estado geral.","C":"Solicitar hemograma, PCR e exame de urina.","D":"Prescrever antitérmico, solicitar hemograma e PCR."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Criança > 3 meses com febre baixa (<38.5) e boa aparência pode ser observada com antitérmico em casa.\nPor que as outras estão erradas:\nA, C, D: Exames e intercalação de antitérmicos não são necessários para febre de 24h sem outros sinais.\nPonto de prova: Manejo da febre na infância.\nFlashcard sugerado: Febre baixa, criança bem? Antitérmico e observar.\nPérola: Febre boa aparência = observar.\nArmadilha: Medicar excessivamente.","tags":["Clínica Médica","Medicina Interna","Imunização","Síndrome Febril","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Uma criança que está com febre baixa mas continua ativa e bem disposta não precisa de exame nenhum agora — só um remédio para baixar a febre e ficar de olho em como ela se comporta."},{"id":"b13-pneumonia-q10","number":50,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Uma paciente com 66 anos de idade comparece à consulta na unidade básica de saúde, com queixa de tosse produtiva, com escarro amarelado, fadiga, calafrios e mal-estar. Relata dispneia de decúbito e que, nas duas últimas noites, precisou usar dois travesseiros para conseguir dormir, embora, normalmente, use somente um. Afirma que sentiu piora dos sintomas nos últimos dias. Nega dor precordial, dor no ombro ou braço, mialgia, hemoptise, artralgia, náuseas, vômitos, alteração no hábito intestinal. Informa que não fuma e que é portadora de hipertensão arterial diagnosticada há 10 anos, controlada com uso de losartana 50 mg, duas vezes ao dia; que tem história de asma brônquica na infância; que não usa outros medicamentos e que nunca fez cirurgia. Informa, ainda, uso social de bebidas alcoólicas. Realizam-se os exames necessários, cujos resultados são descritos a seguir. Ao exame físico, apresenta: IMC de 25 kg/m2; T. Ax de 37,5 °C; PA de 136 × 80 mmHg; FC de 88 bpm. À ausculta cardíaca, verificam-se ritmo cardíaco regular, bulhas normofonéticas, sem sopros, sem atrito pericárdico. À ausculta pulmonar, verifica-se murmúrio vesicular presente em ambos os pulmões, presença de estertores crepitantes na base do pulmão esquerdo, inalterados pela tosse ou respiração. Os exames da cavidade oral e do abdome apresentam- se sem alterações, verificando- se ainda ausência de edema de membros inferiores e saturação de O2 de 98% (VR: > 95%). Os resultados dos exames laboratoriais, apresentam leucograma: leucócitos = 9 500 mm3 (VR: 4 500 a 11 000 mm3); neutrófilos = 80% (VR: 40 a 70%); linfócitos = 13% (VR: 23 a 33%); monócitos = 3% (VR: 3 a 7%); eosinófilos = 3% (VR: 1 a 3%); basófilos = 1% (VR: 0,5 a 1%). A radiografia de tórax, visualizou- se infiltrado na base do pulmão esquerdo, sem outros achados. Considerando- se o caso apresentado, a hipótese diagnóstica e a conduta esperada correspondem, respectivamente, a:","options":{"A":"Derrame pleural; realização de toracocentese.","B":"Pneumotórax; realização de drenagem pleural fechada em selo d’água.","C":"Insuficiência cardíaca; hospitalização e diurético de alça por via venosa.","D":"Pneumonia; prescrição de claritromicina, via oral, 250 mg duas vezes ao dia, por sete dias."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Os sintomas e o Rx com infiltrado indicam pneumonia. O tratamento para PAC em paciente com comorbidades (HAS, asma) inclui claritromicina.\nPor que as outras estão erradas:\nA, B, C: Derrame, pneumotórax e IC não justificam o infiltrado e os sintomas descritos.\nPonto de prova: Tratamento de PAC com comorbidades.\nFlashcard sugerado: PAC com comorbidade? Betalactâmico + Macrolídeo.\nPérola: Comorbidade pede cobertura atípica.\nArmadilha: Tratar como IC por causa da ortopneia.","tags":["Clínica Médica","Geriatria","Asma","Tosse","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Apesar de ela ter ficado com falta de ar deitada, o que lembra problema de coração, os exames e o raio-X mostram que é mesmo uma infecção no pulmão, então o tratamento certo é um antibiótico específico para isso."},{"id":"b13-febre-sem-sinais-q03","number":51,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Febre Sem Sinais Localizatórios","stem":"Criança, sexo feminino, de 2 meses trazida ao Pronto Socorro com história de febre há 4 dias. Familiares negam história de tosse, coriza, diarreia, dor abdominal, vômitos ou quaisquer outros sintomas. Criança previamente hígida, nascida a termo de parto cesárea, sem intercorrências neonatais. Ao exame físico, chorosa, BEG, ativo, reativo, T 39,3ºC, FC 174 bpm, FR 50 rpm, Sat O2 94% em ar ambiente. Sem alterações no exame físico. Qual é a melhor conduta?","options":{"A":"Como paciente está em bom estado geral e sem alterações no exame físico, deve ser orientado sobre os sinais de alarme e dada alta hospitalar.","B":"Deve-se avaliar o status vacinal da criança para decidir sobre a coleta de exame de urina.","C":"Deve-se coletar exame de urina, hemograma e, se possível, painel viral respiratório.","D":"Deve-se iniciar antibioticoterapia empírica e coletar exame de urina, hemograma, RX de tórax, LCR e painel viral respiratório."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Lactente <3 meses (2 meses) com febre alta sem foco requer exames: urina, hemograma e painel viral (sempre que possível).\nPor que as outras estão erradas:\nA, D: Não pode dar alta.\nB: Não é necessário raio-x e líquor de início se estiver bem.\nPonto de prova: Investigação de febre sem foco <3 meses.\nFlashcard sugerado: Febre sem foco < 3 meses? Hemograma, urina, painel viral.\nPérola: <3 meses com febre = investigar.\nArmadilha: Liberar sem exames.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Síndrome Febril","Diarreia","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Um bebê tão pequeno com febre alta sem explicação precisa fazer exames de urina, de sangue e, se possível, um teste para vírus, mesmo estando com boa aparência, porque nessa idade o risco de uma infecção grave é maior."},{"id":"b13-febre-sem-sinais-q04","number":52,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Criança, sexo masculino, 24 meses de idade, é levada a UPA com história de febre de 38,2 °C há 24 horas, que cedeu um poucas horas com uso de antitérmico. Criança com a vacinação completa, sem outras queixas. Ao exame físico, encontra-se em bom estado geral ativa, febril, taquicárdica (FC: 160 bpm), eupneica, boa perfusão capilar e sem outras alterações. Entre as opções abaixo, a melhor conduta neste momento para este paciente é:","options":{"A":"Colher hemograma e PCR.","B":"Prescrever antitérmicos e reavaliar a criança diariamente.","C":"Realizar radiografia de tórax e colher urina I e urocultura.","D":"Colher urina I e urocultura."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Febre sem foco em >3 meses bem-aparecente: principal investigação é urina I e urocultura.\nPor que as outras estão erradas:\nA, B, C: Hemograma não é rotina em boa aparência, Rx e retorno diário não são necessários.\nPonto de prova: Febre sem foco em lactente jovem.\nFlashcard sugerado: Febre sem foco em >3 meses bem? Urina I e urocultura.\nPérola: Febre sem foco = pense em ITU.\nArmadilha: Solicitar hemograma e PCR sem indicação.","tags":["Pediatria","Saúde da Criança","Síndrome Febril","Imunização","Conduta Terapêutica","Pediatria Ambulatorial"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Numa criança de 2 anos com febre sem sintoma nenhum que explique, mas que está bem-disposta, a principal suspeita é uma infecção na urina, então o exame mais importante a pedir é o de xixi."},{"id":"b13-violencia-sexual-q18","number":53,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Uma jovem de 19 anos procura a emergência da maternidade com dor importante no baixo ventre e com discreto sangramento. À triagem, apresenta-se muito abalada, relata ter sofrido violência sexual durante um assalto, há 4 horas, e que o agressor não usou preservativo quando a penetrou. Relata que, ao chegar em casa e contar o ocorrido, sua mãe preferiu levá-la para atendimento médico antes de procurar a delegacia da mulher. Informa nunca ter engravidado, ter ciclos menstruais regulares, ter iniciado vida sexual aos 17 anos, com o ex-namorado, e que, atualmente, está sem relações sexuais há 5 meses. De acordo com a norma técnica do Ministério da Saúde, Prevenção e Tratamento dos Agravos Resultantes da Violência Sexual contra Mulheres e Adolescentes, a conduta médica correta é prescrever a contracepção de emergência com:","options":{"A":"Levonorgestrel dose única e profilaxia para ISTs não virais e virais, independentemente do status sorológico do agressor.","B":"Injetável mensal e profilaxia para ISTs não virais e virais, caso os testes rápidos para sífilis, hepatites e HIV forem negativos.","C":"Levonorgestrel dose única, se teste o qualitativo para gravidez for negativo, e profilaxia para ISTs virais com antirretrovirais.","D":"Injetável mensal e profilaxia para ISTs não virais e virais, após o retorno da paciente da delegacia com comprovante de exame pericial."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Levonorgestrel dose única e profilaxia para ISTs virais e bacterianas devem ser iniciadas imediatamente, independente do status do agressor.\nPor que as outras estão erradas:\nB, C, D: Injetável mensal não é anticoncepção de emergência. Testes rápidos não guiam a profilaxia pós-exposição (ela é empírica).\nPonto de prova: Manejo inicial da vítima de estupro.\nFlashcard sugerado: Profilaixa pós-estupro depende do status do agressor? Não.\nPérola: A profilaxia não espera pelo agressor.\nArmadilha: Aguardar testes do agressor.","tags":["Ginecologia e Obstetrícia","Ginecologia","Anticoncepção de Emergência","Violência Sexual","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O remédio para evitar gravidez e os remédios de proteção contra infecções devem ser dados logo, sem esperar para saber se o agressor tem alguma doença — a proteção não depende disso."},{"id":"b13-febre-sem-sinais-q05","number":54,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Lactente com 50 dias de vida, menina, é levada ao pronto-atendimento com história de 1 dia de febre de 38,5 °C, sem outros sintomas associados. Ao exame físico, está em bom estado geral, sem alterações. O plantonista solicitou exames: Hemograma: Hb = 12,3 g/ dL, Ht = 34%, leucócitos = 9800/ mm3 (4% bastonetes, 45% segmentados, 46% linfócitos, 2% eosinófilos, 3% monócitos), plaquetas = 212000/mm3 . Urina tipo I: pH = 5,5, densidade = 1025, glicose +, proteína ausente, nitrito +, esterase leucocitária +, leucócitos = 20/campo, eritrócitos = 2/campo. Frente a esses achados, a conduta indicada é:","options":{"A":"Internar, colher urocultura e iniciar antibiótico parenteral.","B":"Colher urocultura e dar alta com antibiótico oral.","C":"Colher urocultura e orientar retorno em 48 horas para reavaliação e checar resultado.","D":"Dar alta com antitérmico e reavaliar em 24 horas.","E":"Iniciar antibiótico oral e orientar retorno se a febre persistir após 48 horas."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Lactente <2 meses com ITU comprovada (nitrito+, leucócitos+) tem indicação de internação, urocultura e antibiótico parenteral.\nPor que as outras estão erradas:\nB, C, D, E: Tratamento oral ou apenas observação é contraindicado em lactentes jovens com ITU.\nPonto de prova: Tratamento de ITU em lactentes jovens.\nFlashcard sugerado: ITU em <2 meses? Internar e ATB venoso.\nPérola: Bebê com ITU = internação.\nArmadilha: Tratar ambulatorialmente.","tags":["Pediatria","Saúde da Criança","Trombocitopenia","Síndrome Febril","Conduta Terapêutica","Período Neonatal"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Um bebê tão pequeno com sinais claros de infecção na urina precisa ficar internado e tomar antibiótico direto na veia, porque nessa idade não dá para arriscar tratar só em casa."},{"id":"b13-febre-sem-sinais-q06","number":55,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Febre Sem Sinais Localizatórios","stem":"Lactente de 4 meses, feminino previamente hígida com calendário vacinal completo, apresenta febre medida até 39,1oC há 1 dia. A mãe relata discreta anorexia e queda do estado geral. Nega tosse e coriza. Exame físico sem alterações. Assinale a alternativa correta em relação à conduta para esse caso:","options":{"A":"Realização de coleta de exames de sangue e urina, mas não há indicação de raio X de tórax.","B":"Antibioticoterapia de amplo espectro iniciada logo após a coleta de exames, independente dos resultados.","C":"A coleta de urina por sondagem vesical ou punção suprapúbica está indicada.","D":"Este paciente deverá ser internado para o tratamento adequado."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Lactentes <2 anos (4 meses) com suspeita de ITU devem ter a urina coletada por sondagem ou punção suprapúbica (evita contaminação).\nPor que as outras estão erradas:\nA, B, D: A coleta por saco é inadequada, e a internação não é mandatória se estiver bem.\nPonto de prova: Método de coleta de urina em lactentes.\nFlashcard sugerado: Coleta de urina em lactente não tolha-vaso? Sondagem ou punção suprapúbica.\nPérola: Saco coletor é para tela, não para cultura.\nArmadilha: Usar saco coletor para urocultura.","tags":["Cirurgia","Trauma","Imunização","Síndrome Febril","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Para saber com certeza se a urina de um bebê pequeno está infectada, o médico precisa coletar a amostra de um jeito bem cuidadoso, com uma sondinha ou uma agulha fininha, porque o saquinho colado na pele costuma sujar o resultado."},{"id":"b13-derrame-pleural-q09","number":56,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Sobre o derrame pleural, assinale a alternativa CORRETA:","options":{"A":"Insuficiência hepática, insuficiência renal e insuficiência cardíaca congestiva são doenças que podem cursar com exsudato.","B":"No transudato, há aumento da pressão hidrostática (hipervolemia), aumento da pressão oncótica (hiperalbuminemia) e a camada mesotelial está normal, ou seja, não há o acometimento direto da superfície pleural.","C":"As manifestações clínicas secundárias à presença de derrame pleural são: tosse produtiva, ausência de dor torácica e dispneia.","D":"Os achados radiológicos característicos do derrame pleural em posição ortostática são: opacificação dos campos pulmonares basais, sinal do menisco e desvio do mediastino para o lado contralateral."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Os achados radiológicos típicos incluem opacificação basal, sinal do menisco e desvio de mediastino (se volume importante).\nPor que as outras estão erradas:\nA: IC, IR e IH causam transudato.\nB: No transudato há aumento da pressão hidrostática, mas diminuição da oncótica (hipoalbuminemia).\nC: Dor torácica é comum, e a tosse é seca, não produtiva.\nPonto de prova: Fisiopatologia e imagem do derrame pleural.\nFlashcard sugerado: Sinal do menisco = Derrame pleural.\nPérola: Menisco no Rx = líquido na pleura.\nArmadilha: Achar que transudato tem hipoalbuminemia por aumento de oncótica.","tags":["Clínica Médica","Pneumologia","Derrame Pleural","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"No raio-X, quando há líquido acumulado ao redor do pulmão, aparece uma curva característica na base, e, se for muita quantidade, o coração e as estruturas do meio do peito são empurrados para o lado oposto."},{"id":"b13-violencia-sexual-q19","number":57,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Uma paciente de 18 anos chega à emergência do hospital referindo ter sido vítima de violência sexual há 2 horas em uma festa. Relata que, no ato, houve penetração. Ela desconhece o agressor, o qual não usou preservativo. A abordagem inicial deve incluir:","options":{"A":"Atendimento inicial exclusivo por médico","B":"Encaminhamento da paciente primeiramente ao instituto médico legal","C":"Encaminhamento da paciente para realizar o boletim de ocorrência antes do atendimento médico.","D":"Início de profilaxia para as doenças sexualmente transmissíveis e prevenção de gravidez em até 5 dias.","E":"Avaliação do estado geral de saúde, orientação e proteção contra doenças de transmissão sexual, prevenção de gravidez e coleta de materiais biológicos ou outros indícios materiais que permitam a identificação do agressor."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A abordagem envolve avaliação clínica, profilaxia ISTs e gravidez, e coleta de material para identificação do agressor (vestígios).\nPor que as outras estão erradas:\nA: Não deve ser exclusivo do médico (multidisciplinar).\nB, C: O IML ou BO não precedem o atendimento médico e profilaxias.\nD: A profilaxia deve ser em até 72h, idealmente (não 5 dias, exceto DIU cobre até 5 dias).\nPonto de prova: Fluxo de atendimento à vítima de estupro.\nFlashcard sugerado: O que colher na violência sexual? Material biológico para identificar o agressor.\nPérola: Médico trata e colhe vestígios.\nArmadilha: Mandar para o IML antes de tratar.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O atendimento deve avaliar a saúde da pessoa, começar os remédios de proteção contra infecções e gravidez, e também coletar amostras do corpo que podem ajudar a identificar quem fez a violência — tudo isso feito pela equipe de saúde, sem esperar a polícia."},{"id":"b13-febre-sem-sinais-q07","number":58,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Na avaliação de lactentes jovens (até 3 meses) com doença febril, são avaliados os critérios de Rochester, quanto ao baixo risco para doença bacteriana grave. Assinale a alternativa que contempla um critério clínico e um laboratorial:","options":{"A":"Nascido a termo; contagem de leucócitos entre 3.000 e 12.000/mm³.","B":"Ausência de comorbidades; contagem absoluta de bastonetes > 1.500/mm³.","C":"Temperatura < 39ºC; Contagem de leucócitos entre 5 e 15.000/mm³.","D":"Aparência toxemiada; microscopia de fezes com contagem ≤ 5 leucócitos/campo nas crianças com diarreia.","E":"Previamente saudável; microscopia de sedimento urinário com contagem ≤ 10 leucócitos/campo."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Critérios de Rochester incluem criança previamente saudável e urina com <= 10 leucócitos/campo.\nPor que as outras estão erradas:\nA: Leucócitos entre 5 e 15.000 (não é o critério de Rochester, é < 15.000).\nB: Bastonetes deve ser < 1.500.\nC: Temperatura deve ser < 38.9ºC (ou 39ºC).\nD: Criança não deve estar toxemiada.\nPonto de prova: Critérios de Rochester para baixo risco.\nFlashcard sugerado: Rochester exige criança saudável e urina < 10 leuc.\nPérola: Rochester = baixo risco.\nArmadilha: Usar temperatura alta como baixo risco.","tags":["Clínica Médica","Medicina Interna","Interpretação de Exames","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Existe uma lista de pistas que ajuda o médico a saber se um bebê com febre corre pouco risco de infecção grave — duas delas são a criança ter sido sempre saudável antes e a urina não mostrar muitas células de defesa."},{"id":"b13-derrame-pleural-q10","number":59,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Paciente de 45 anos, gênero feminino, é admitida por quadro de tosse produtiva, febre e dispneia há 3 dias. Realizou Rx de tórax cuja imagem é compatível com pneumonia de lobo inferior direito associado a velamento do seio costofrênico ipsilateral. Ao POCUS (Point-of-Care-Ultrasound) foi possível confirmar a hipótese de derrame pleural tendo sido realizada toracocentese e prescritos ceftriaxona associado a azitromicina. Os achados bioquímicos do líquido pleural evidenciam proteínas totais 4,5g/dl (sérica 6,8), (DHL = 12500/M, PH-6.9, celularidade 1800 células/mm² (88% neutrófilos), ADA-120 UIM e cultura em andamento. Qual deve ser a conduta mais adequada neste momento?","options":{"A":"Indicar drenagem torácica.","B":"Escalonar antibioticoterapia para tazocin e vancomicina.","C":"Manter antibioticoterapia e reavaliar resposta clínica em 48h.","D":"Investigar tuberculose como condição facilitadora da pneumonia bacteriana."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Os exames mostram derrame parapneumônico complicado (pH<7.2, glic<60, LDH alto), com indicação de drenagem torácica.\nPor que as outras estão erradas:\nB, C, D: Escalonar antibiótico ou só observar é insuficiente, é necessário drenar.\nPonto de prova: Conduta em derrame parapneumônico complicado.\nFlashcard sugerado: pH < 7.2 no parapneumônico? Drenar.\nPérola: Parapneumônico complicado = dreno.\nArmadilha: Só trocar antibiótico.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Dispneia","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Os números do líquido do pulmão (muito ácido, com pouco açúcar e uma enzima bem alta) mostram que a infecção já complicou, então agora é preciso colocar um tubo para drenar o líquido, e não só trocar o remédio."},{"id":"b13-derrame-pleural-q11","number":60,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Com base na análise da radiografia reproduzida ao lado, realizada em incidência anteroposterior e em posição ortostática, é possível afirmar que: ** **","options":{"A":"Foi realizada lobectomia pulmonar inferior direita.","B":"Há um abscesso no pulmão direito.","C":"Há hidropneumotórax à direita.","D":"Há uma consolidação na metade inferior do pulmão direito."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: A radiografia mostra nível hidroaéreo, compatível com hidropneumotórax à direita.\nPor que as outras estão erradas:\nA, B, D: Não há sinais radiológicos claros de lobectomia, abscesso ou consolidação simples.\nPonto de prova: Interpretação de Rx de tórax.\nFlashcard sugerado: Nível hidroaéreo no Rx = Hidropneumotórax.\nPérola: Líquido e ar junto = hidropneumo.\nArmadilha: Confundir com abscesso (parede espessada).","tags":["Clínica Médica","Medicina Interna","Epidemiologia","Interpretação de Exames","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"A imagem do raio-X mostra uma linha reta separando ar (em cima) de líquido (embaixo) dentro do peito, o que indica que há tanto ar quanto líquido acumulados ao redor do pulmão ao mesmo tempo."},{"id":"b13-redes-atencao-q03","number":61,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"Assinale a alternativa correta sobre as portas de entrada às ações e serviços de saúde nas Redes de Atenção à Saúde (RAS):","options":{"A":"Embora somente as Unidades Básicas de Saúde (UBSs) e os serviços de urgência e emergência sejam considerados portas de entrada às ações e serviços de saúde nas RAS, nos locais mais distantes dos centros urbanos, há uma relativização desse conceito.","B":"As UBSs são as portas de entrada prioritárias a todos os usuários do SUS, com exceção de pessoas em situação de rua, que devem ter acesso às ações e serviços nas RAS somente pelos consultórios nas ruas.","C":"Os serviços de atenção psicossocial deixaram de ser porta de entrada às ações e serviços de saúde nas RAS, mantendo-se nessa categoria apenas para os usuários de álcool.","D":"As UBSs e as unidades de urgência e emergência são as únicas portas de entrada às ações e serviços de saúde do SUS e, portanto, há um esforço para que funcionem 24 horas por dia.","E":"Mediante justificativa técnica e de acordo com o pactuado nas Comissões Intergestores, os entes federativos poderão criar novas portas de entrada às ações e serviços de saúde, considerando as características da Região de Saúde."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Entes federativos podem criar novas portas de entrada mediante justificativa técnica e pactuação na CIR.\nPor que as outras estão erradas:\nA, B, C, D: As UBS não são as únicas portas, e não há restrições severas como descrito.\nPonto de prova: Portas de entrada do SUS (Decreto 7508).\nFlashcard sugerado: Quem pode criar novas portas de entrada? Municípios/Estados via CIR.\nPérola: A CIR pode criar portas.\nArmadilha: Achar que só UBS e Urgência são portas.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Além do postinho de saúde e do pronto-socorro, os gestores podem, com boa justificativa e combinando entre eles, criar outras portas de entrada para o sistema de saúde, dependendo da necessidade de cada região."},{"id":"b13-pneumonia-q11","number":62,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Após a chegada de paciente de 66 anos com pneumonia comunitária, o residente de clínica médica precisou revisar alguns pontos sobre o tema. O paciente estava prostrado e desorientado. Sua frequência respiratória era de 35 ipm e sua pressão arterial, 100 x 60 mmHg. Não havia qualquer comorbidade descompensada ou internação prévia. O paciente era hipertenso leve em bom controle. Sobre a condução nessa primeira abordagem, é correto afirmar que:","options":{"A":"As coletas de gasometria, hemograma, bioquímica e de material para cultura no sangue e no escarro são recomendadas. Também está recomendado o teste de antígeno para influenza em situações de alta circulação do vírus.","B":"Esse paciente, independentemente do resultado dos primeiros exames, tem pneumonia comunitária grave e deve ser internado, ministrando-se carbapenêmico associado-a vancomicina.","C":"A coleta de escarro para coloração por Gram e cultura e a coleta de hemoculturas são desnecessárias nesse caso.","D":"pesquisa de antígeno urinário para Legionella e pneumococo é essencial ao desfecho do caso.","E":"A dosagem procalcitonina pode guiar a terapia antimicrobiana."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: PAC grave (confusão, FR 35) requer internação, coleta de exames (hemocultura, escarro, gaso) e investigação de influenza.\nPor que as outras estão erradas:\nB: Não necessariamente carbapenêmico de início.\nC: Hemoculturas e escarro são necessárias.\nD: Antígenos não são essenciais ao desfecho.\nE: Procalcitonina é opcional.\nPonto de prova: Manejo de PAC grave.\nFlashcard sugerado: PAC grave exige quais exames? Hemocultura, escarro, gasometria.\nPérola: PAC grave = colher tudo e internar.\nArmadilha: Não colher exames antes do antibiótico.","tags":["Clínica Médica","Pneumologia","Pneumonia","Conhecimento Conceitual","Pessoa Idosa","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Quando a pneumonia é grave, com confusão mental e respiração muito acelerada, o médico precisa colher vários exames de sangue e também testar para gripe, além de já internar o paciente."},{"id":"b13-redes-atencao-q04","number":63,"collectionBlock":13,"documentBlock":13,"area":"Saúde Coletiva","topic":"Redes de Atenção à Saúde","stem":"O SUS está organizado de forma regionalizada e hierarquizada para formar as Redes de Atenção à Saúde no âmbito de Regiões de Saúde. Qual é o serviço necessário para que um território seja reconhecido como Região de Saúde?","options":{"A":"Centro de alta complexidade em oncologia.","B":"Centro de Terapia Renal Substitutiva.","C":"Maternidade de alto risco.","D":"Unidade Básica de Saúde."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Para ser Região de Saúde, o território precisa ter, no mínimo, uma Unidade Básica de Saúde (UBS).\nPor que as outras estão erradas:\nA, B, C: Serviços de alta complexidade não são mandatários para constituir uma região.\nPonto de prova: Constituição de Região de Saúde.\nFlashcard sugerado: O que é mínimo para ser Região de Saúde? UBS.\nPérola: Sem UBS não há Região de Saúde.\nArmadilha: Achar que precisa de hospital.","tags":["Saúde Coletiva","Medicina de Família e Comunidade","Sistema Único de Saúde","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Para um pedaço do mapa ser considerado uma 'Região de Saúde' de verdade, ele precisa ter, no mínimo, um postinho de saúde funcionando — não precisa ter hospital grande nem serviço superespecializado."},{"id":"b13-febre-sem-sinais-q08","number":64,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Uma lactente de 18 meses é levada à emergência com história de febre há 2 dias. Quando a temperatura sobe, fica um pouco parada, voltando a ficar bem quando a temperatura se aproxima novamente de 36,5 ºC. O responsável nega outros sintomas. As vacinas estão em dia. Exame físico: sem qualquer alteração. Para que se trace a conduta adequada a essa criança, os quesitos fundamentais a serem avaliados, além da idade, são:","options":{"A":"A temperatura axilar, o exame físico e o leucograma.","B":"O estado geral, o exame físico e o exame de urocultura.","C":"O estado vacinal, a temperatura axilar e o leucograma.","D":"O estado geral, o estado vacinal e exame de urocultura.","E":"O exame físico, o estado geral da criança e o leucograma."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Na febre sem foco, os quesitos fundamentais são idade, estado geral, exame físico, estado vacinal e exame de urina.\nPor que as outras estão erradas:\nA, B, C, E: Temperatura e leucograma não substituem o estado vacinal e a urocultura.\nPonto de prova: Avaliação de febre sem foco.\nFlashcard sugerado: Febre sem foco: o que avaliar? Idade, estado geral, vacina, urina.\nPérola: Estado vacinal e urina ditam o risco.\nArmadilha: Basear só na temperatura.","tags":["Pediatria","Saúde da Criança","Síndrome Febril","Imunização","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Além da idade do bebê, o médico precisa saber como ele está se comportando no geral, se as vacinas estão em dia, e pedir um exame de urina — são essas as pistas principais para decidir o que fazer."},{"id":"b13-redes-atencao-q05","number":65,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"A atenção secundária à saúde envolve profissionais mais específicos e maior demanda tecnológica, sendo responsável por casos de complexidade intermediária. Sobre o assunto, há as seguintes afirmativas: I - Unidades de Pronto Atendimento (UPAs) representam um exemplo de atuação da atenção secundária. II - A atenção secundária é caracterizada pelo uso de tecnologias avançadas e procedimentos invasivos. III - Serviços de urgência e emergência são comumente utilizados na atenção secundária. Dessa forma, é CORRETO afirmar:","options":{"A":"Apenas I e III estão corretas.","B":"Apenas Il está correta.","C":"Apenas III está correta.","D":"Apenas II e III estão corretas."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: UPAs e serviços de urgência/emergência são considerados atenção secundária/média complexidade. II está errada (terciária é alta complexidade).\nPor que as outras estão erradas:\nB, C, D: Baseiam-se na assertiva II estar correta.\nPonto de prova: Classificação dos níveis de atenção.\nFlashcard sugerado: UPA é qual nível? Secundário.\nPérola: UPA = secundária.\nArmadilha: Achar que UPA é primária.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"As unidades de pronto atendimento e os serviços de urgência fazem parte do nível intermediário de cuidado, não do nível mais simples do postinho de bairro."},{"id":"b13-derrame-pleural-q12","number":66,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Uma mulher de 50 anos, tabagista e sem comorbidades conhecidas, é hospitalizada com febre alta, dispneia progressiva e dor torácica. A radiografia de tórax mostra derrame pleural moderado à direita, e a toracocentese é realizada. Resultados do líquido pleural mostram proteína de 4,2 g/ dL, DHL de 800 U/ L, glicose de 30 mg/ dL, pH de 7,0 e predomínio de neutrófilos na citologia. Com base nos achados clínicos e laboratoriais, qual é a conduta mais apropriada?","options":{"A":"Iniciar antibióticos e observar a evolução.","B":"Aumentar a hidratação e monitorar parâmetros respiratórios.","C":"Realizar drenagem pleural e iniciar antibióticos.","D":"Realizar pleurodese para prevenção de recorrência.","E":"Repetir a toracocentese em 48 horas."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: pH 7.0, glicose 30 e exsudato neutrófilo indicam empiema/derrame complicado, requerendo drenagem e antibióticos.\nPor que as outras estão erradas:\nA, B, D, E: Observação, hidratação, pleurodese ou repetir punção são insuficientes.\nPonto de prova: Conduta em empiema.\nFlashcard sugerado: pH 7.0 + glic 30? Drenar.\nPérola: Empiema = dreno.\nArmadilha: Só observar.","tags":["Clínica Médica","Pneumologia","Tabagismo","Derrame Parapneumônico","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"O líquido do pulmão está muito ácido, com pouco açúcar e cheio de células de defesa, sinal de uma infecção grave formando pus lá dentro — por isso é preciso colocar um dreno e dar antibiótico ao mesmo tempo."},{"id":"b13-febre-sem-sinais-q09","number":67,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Entre as indicações para o uso de ibuprofeno em pediatria, aquela respaldada por sua ação farmacológica é:","options":{"A":"Redução da febre e alívio da dor leve a moderada em infecções virais e bacterianas.","B":"Prevenção de crises asmáticas em crianças com hiper-responsividade brônquica","C":"Controle de convulsões febris em crianças suscetíveis, como terapia de manutenção.","D":"Tratamento de infecções bacterianas do trato respiratório superior com dor associada.","E":"Alívio de náuseas e vômitos em doenças gastrointestinais autolimitadas."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Ibuprofeno é indicado para redução de febre e alívio de dor leve a moderada.\nPor que as outras estão erradas:\nB, C, D, E: Ibuprofeno não previne asma, convulsões, nem trata infecções ou vômitos.\nPonto de prova: Indicações do ibuprofeno em pediatria.\nFlashcard sugerado: Ibuprofeno serve para o quê? Febre e dor.\nPérola: Ibuprofeno: febre e dor.\nArmadilha: Usar para prevenir convulsão.","tags":["Clínica Médica","Medicina Interna","Ibuprofeno","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"O ibuprofeno serve para baixar a febre e aliviar dor de leve a moderada — não serve para prevenir crise de asma, convulsão ou tratar infecção diretamente."},{"id":"b13-violencia-sexual-q20","number":68,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Maria tem 17 anos e sofreu violência sexual [sic]. Já está grávida de 30 semanas e deseja usufruir de seu direito de abortar legalmente, embora não tenha como comprovar essa condição de abuso. Ela procura o serviço de referência na cidade-sede de sua Diretoria Regional de Saúde (DRS) e é atendida pelo Dr. Roberto. Maria está tentando resolver esse problema desde as 16 semanas de gravidez e agora, para piorar, está ficando hipertensa. Assinale a alternativa CORRETA:","options":{"A":"Maria terá de fazer um boletim de ocorrência para obter o direito de abortar, já que não fez o exame de corpo de delito tempestivamente.","B":"Dr. Roberto cometeu infração ética porque disse a Maria que não fará o aborto, alegando seu direito legal e ético à objeção de consciência.","C":"Maria só tem direito ao aborto legal com 30 semanas de gestação, porque está hipertensa e pode evoluir com pré-eclâmpsia ou eclâmpsia.","D":"O Código Penal Brasileiro não estabelece limite de idade gestacional para os permissivos legais ao aborto induzido."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O Código Penal não estabelece limite de idade gestacional para os permissivos (estupro, risco de vida). A norma técnica do MS estabelece 22 sem/500g, mas legalmente não há limite.\nPor que as outras estão erradas:\nA: Não precisa de BO.\nB: Objeção de consciência é individual, não institucional.\nC: O aborto por estupro independe de patologias maternas.\nPonto de prova: Legislação sobre aborto.\nFlashcard sugerado: O Código Penal limita a IG para aborto por estupro? Não.\nPérola: A lei não tem prazo, a norma técnica sim.\nArmadilha: Confundir norma técnica com lei penal.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"A lei brasileira que permite o aborto em caso de violência sexual não coloca um prazo máximo de quantas semanas de gravidez — diferente de uma norma técnica do Ministério da Saúde, que sugere um limite prático, a lei em si não tem esse prazo."},{"id":"b13-redes-atencao-q06","number":69,"collectionBlock":13,"documentBlock":13,"area":"Saúde Coletiva","topic":"Redes de Atenção à Saúde","stem":"Um paciente de 48 anos procura diretamente o serviço de emergência de um hospital terciário, queixando- se de pressão arterial elevada (160/100 mmHg) há 1 mês. Após avaliação, a equipe médica identifica que a condição é crônica, e controlável com acompanhamento ambulatorial. O paciente é orientado a procurar uma Unidade Básica de Saúde (UBS) para seguimento regular, mas ele fica irritado, alegando que quer ser acompanhado no ambulatório do próprio hospital e acusa a equipe de omissão de socorro. Com base nos princípios do SUS, qual das seguintes afirmações está correta em relação ao atendimento e encaminhamento deste paciente?","options":{"A":"O paciente tem o direito de ser atendido exclusivamente no hospital terciário, pois o princípio da universalidade garante o atendimento em qualquer nível do sistema.","B":"A equipe de saúde cometeu omissão de socorro ao não oferecer seguimento ambulatorial no próprio hospital, desrespeitando o princípio da integralidade.","C":"O paciente deve ser encaminhado para a Unidade Básica de Saúde (UBS), pois o princípio da hierarquização e regionalização organiza o sistema para que o primeiro atendimento e seguimento de casos crônicos ocorram nos serviços de atenção primária.","D":"O paciente pode escolher livremente onde quer realizar seu seguimento, conforme o princípio da descentralização do SUS.","E":"O hospital terciário tem a obrigação de oferecer seguimento para todos os casos que entram na emergência, sem necessidade de encaminhamento para outros serviços."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Pela hierarquização e regionalização, casos crônicos e de baixa complexidade devem ser acompanhados na APS (UBS).\nPor que as outras estão erradas:\nA, B, D, E: Universalidade não significa atendimento em qualquer nível. Integralidade não obriga hospital a tratar o ambulatorial.\nPonto de prova: Princípios do SUS.\nFlashcard sugerado: Hipertensão controlada vai para qual nível? UBS.\nPérola: Hierarquização manda o crônico pra UBS.\nArmadilha: Usar a integralidade para justificar o erro.","tags":["Saúde Coletiva","Medicina de Família e Comunidade","Sistema Único de Saúde","Conhecimento Conceitual","Urgência e Emergência","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Uma pressão alta que já está sob controle deve ser acompanhada no postinho de saúde perto de casa, e não no hospital de emergência — cada nível de cuidado cuida do que é da sua responsabilidade, para o sistema funcionar melhor para todo mundo."},{"id":"b13-redes-atencao-q07","number":70,"collectionBlock":13,"documentBlock":13,"area":"Medicina de Família e Comunidade","topic":"Redes de Atenção à Saúde","stem":"As Redes de Atenção à Saúde (RAS) são determinantes para assegurar a integralidade do cuidado dos usuários do sistema de saúde, caracterizando uma atenção contínua, com a coordenação integrada entre os níveis de atenção e a centralização dos cuidados na atenção primária. Sobre as RAS, é correto afirmar:","options":{"A":"A organização das RAS prioriza exclusivamente o cuidado às condições agudas, reduzindo a relevância das condições crônicas no planejamento da atenção à saúde.","B":"As RAS buscam substituir os sistemas fragmentados por sistemas integrados, promovendo uma atenção à saúde proativa e contínua, considerando a rede hospitalar como o ponto principal do cuidado.","C":"O modelo de financiamento das RAS deve ser baseado exclusivamente no volume de recursos, sem levar em consideração a geração de valor para os usuários dos serviços de saúde.","D":"Nas RAS tem-se um cuidado pautado na atenção colaborativa realizada por equipes multiprofissionais.","E":"O modelo de gestão das RAS é caracterizado pela gestão por estruturas isoladas (gerência hospitalar, gerência da atenção básica, gerência dos ambulatórios especializados)."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A RAS preconiza cuidado colaborativo e multidisciplinar.\nPor que as outras estão erradas:\nA: Cuida de condições crônicas e agudas.\nB: A APS é o ponto principal, não a hospitalar.\nC: O financiamento visa valor, não só volume.\nE: A gestão é integrada, não isolada.\nPonto de prova: Princípios das RAS.\nFlashcard sugerado: Como é o cuidado na RAS? Colaborativo e multiprofissional.\nPérola: RAS une a equipe.\nArmadilha: Achar que o hospital é o centro.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Na rede de atenção à saúde, o cuidado funciona melhor quando vários profissionais de diferentes áreas trabalham juntos e conversam entre si, em vez de cada um cuidar sozinho e sem se comunicar."},{"id":"b13-febre-sem-sinais-q10","number":71,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"A febre é uma das queixas mais frequentes nos atendimentos pediátricos, estima- se que 20% a 30% das consultas pediátricas têm a febre como sintoma principal. Analise as seguintes afirmativas sobre febre: I - O uso do ácido acetilsalicílico não é recomendado para o controle da febre, pelo risco de Síndrome de Reye. II - O paracetamol, a dipirona e o ibuprofeno são bem tolerados e efetivos nas doses recomendadas para o controle da febre. III - O uso do termômetro de mercúrio é o mais fidedigno e seguro. IV - É recomendada a prática de intercalar os antitérmicos para o controle da febre. É correto afirmar que:","options":{"A":"Todas as alternativas estão corretas.","B":"Somente I e II estão corretas.","C":"I, II e Ill estão corretas.","D":"Somente IV está correta."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: AAS é contraindicado por risco de Síndrome de Reye. Paracetamol, dipirona e ibuprofeno são seguros. Mercúrio não é seguro e a alternância não é recomendada.\nPor que as outras estão erradas:\nA, C, D, E: Contêm afirmações incorretas sobre mercúrio e alternância.\nPonto de prova: Manejo da febre em pediatria.\nFlashcard sugerado: Antitérmico a evitar na criança? AAS (Reye).\nPérola: AAS proibido para criança.\nArmadilha: Intercalar antitérmicos.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Ácido Acetilsalicílico","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Existe um remédio para dor e febre que nunca deve ser dado a crianças porque pode causar uma doença rara e grave no fígado e no cérebro; já outros remédios comuns são seguros, mas não se deve misturar vários tipos ao mesmo tempo tentando controlar a febre."},{"id":"b13-pneumonia-q12","number":72,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Um homem com 54 anos de idade, transplantado renal há 3 meses, apresenta, há cerca de 7 dias, febre elevada (> 40 o C), tosse pouco produtiva (escarro pouco purulento) e dor torácica à esquerda. Ele procurou o serviço onde realizou o transplante de órgão, sendo observada a presença de febre elevada e ausculta pulmonar com estertores crepitantes difusos, além de semiologia compatível com derrame pleural à esquerda. O Gram de escarro não mostrou patógenos, mas apenas alguns polimorfonucleares. A Tomografia Computadorizada de Tórax (TCT), realizada no mesmo dia, revelou opacidades alveolares arredondadas e derrame pleural leve à esquerda. Como o paciente respondeu bem à administração de antitérmico, mantendo bom estado hemodinâmico e padrão respiratório satisfatório, foi liberado para casa com prescrição de amoxicilina-clavulanato. No entanto, após 4 dias de tratamento, mantinha-se febril, sem melhora do quadro clínico. Nova TCT revelou que algumas das opacidades parenquimatosas haviam evoluído com escavação central. Foi formulada a hipótese de pneumonia por Legionella pneumophila. Em função de o paciente estar em tratamento imunossupressor com ciclosporina e tacrolimus, qual é o tratamento antimicrobiano adequado a ser prescrito?","options":{"A":"Sulfametoxazol-trimetoprim.","B":"Levofloxacino.","C":"Azitromicina.","D":"Doxiciclina."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O paciente imunossuprimido com Legionella e usando tacrolimus/ciclosporina deve ser tratado com fluorquinolona (levofloxacino), pois macrolídeos interagem com a calcineurina.\nPor que as outras estão erradas:\nA, C, D: SMZ-TMP, azitromicina e doxiciclina não são adequadas ou têm interação problemática.\nPonto de prova: Tratamento de Legionella em transplantados.\nFlashcard sugerado: Legionella em transplantado (tacrolimus)? Levofloxacino.\nPérola: Macrolídeo briga com tacrolimus.\nArmadilha: Usar azitromicina.","tags":["Clínica Médica","Pneumologia","Amoxicilina com Clavulanato","Pneumonia","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Essa pessoa toma remédios especiais para o corpo não rejeitar o rim transplantado, e um tipo comum de antibiótico briga com esses remédios — por isso o médico escolhe outro antibiótico que não atrapalha o tratamento do transplante."},{"id":"b13-febre-sem-sinais-q11","number":73,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Lactente de 6 meses, sexo feminino, com história de ITU prévia aos 4 meses (USG de rins e vias urinárias sem alterações), é levada ao pronto- socorro por apresentar febre há 48 horas. Mãe nega outros sintomas, refere que criança está irritada e acha que pode estar com dor na barriga. Eliminações presentes e habituais. Ao exame físico, criança apresenta- se sem alterações. Sobre este caso clínico, podemos afirmar: I) O diagnóstico mais provável é uma infecção viral. II) A investigação diagnóstica envolve, necessariamente, coleta de hemograma, PCR e análise de sedimento urinário. III) Está indicada coleta de líquor para essa paciente. IV) Caso trate-se de infecção urinária, está indicado o uso de Nitrofurantoína.","options":{"A":"Todas as afirmações são verdadeiras.","B":"Três afirmações são verdadeiras.","C":"Duas afirmações são verdadeiras","D":"Apenas uma afirmação é verdadeira."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Apenas uma afirmação está correta (a necessidade de coleta de urina/sedimento urinário para investigar ITU).\nPor que as outras estão erradas:\nI, III, IV: Não se indica líquor de rotina, nitrofurantoína não é para febre sem foco inicial.\nPonto de prova: Febre sem foco em lactente com ITU prévia.\nFlashcard sugerado: Febre sem foco em <3 meses? Urina sempre.\nPérola: ITU prévia pede urina novamente.\nArmadilha: Solicitar líquor desnecessariamente.","tags":["Pediatria","Saúde da Criança","Infecção Urinária","Parada Cardiorrespiratória","Raciocínio Diagnóstico","Primeira Infância"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Para esse bebê com febre e sem outros sintomas, a única coisa realmente necessária é examinar a urina — não é preciso fazer exame de líquido da coluna nem usar um antibiótico específico sem confirmação primeiro."},{"id":"b13-febre-sem-sinais-q12","number":74,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Recém-nascido de 28 dias de vida é trazido à consulta ambulatorial com queixa de pico febril nas últimas 12 horas. A criança está aparentemente bem, em vestimentas adequadas para o clima, sem alterações na amamentação ou nas eliminações fisiológicas. Ao exame físico desnudo, a temperatura axilar é de 37,7ºC, sem outras alterações nos demais aparelhos. Qual a conduta mais adequada para o manejo desse paciente?","options":{"A":"Orientar os pais a reduzirem a quantidade de roupas, pois a febre pode ser causada por superaquecimento, e retornar para reavaliação após 24-48 horas.","B":"Considerar o quadro febril como benigno, sem alterações ao exame físico. Orientar os pais a administrar antitérmico e retornar em 24 horas para reavaliação.","C":"Encaminhar o paciente para o pronto-socorro pediátrico para coleta de exames e internação hospitalar.","D":"Realizar coleta de hemograma e exame de urina para investigação mais aprofundada."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: RN com 28 dias e febre (mesmo 37.7ºC) é considerado RN febril, exigindo internação, exames completos e ATB venoso.\nPor que as outras estão erradas:\nA, B, D: Condutas ambulatoriais ou parciais são inseguras em RN <1 mês.\nPonto de prova: Conduta em febre no recém-nascido.\nFlashcard sugerado: RN <1 mês com febre? Internar e investigar tudo.\nPérola: RN febril não vai pra casa.\nArmadilha: Alta com antitérmico.","tags":["Pediatria","Saúde da Criança","Aleitamento Materno","Conduta Terapêutica","Período Neonatal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Um recém-nascido com menos de um mês que tem febre, mesmo que pareça bem, precisa ser internado e investigado a fundo, porque nessa fase da vida qualquer febre pode esconder uma infecção séria."},{"id":"b13-febre-sem-sinais-q13","number":75,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Em relação à abordagem da febre sem sinais localizatórios (FSSL) em pediatria, assinale a alternativa cuja conduta está em desacordo com as recomendações mais recentes da Sociedade Brasileira de Pediatria (SBP, 2025):","options":{"A":"Lactente de 2 meses apresenta febre há 3 dias (Tmáx = 38,5 °C),sem outros sinais ou sintomas. Anamnese e exame físico sem alterações. História perinatal e pregressa sem intercorrências. Foi realizada coleta de hemograma e exame de urina (EAS/ urina I).","B":"Recém-nascido de 13 dias é levado ao PS por febre (T = 37,8 °C)há 3 horas. Está ativo, mamando bem e sem sinais clínicos de gravidade. Sem intercorrências obstétricas. Foi internado, submetido à coleta de exames laboratoriais (hemograma, urina I, culturas, líquor, Rx de tórax) e iniciado antibiótico empírico.","C":"Lactente de 8 meses, com febre aferida há 02 dias (Tmáx de 38,3°C). Anamnese e exame físico sem qualquer indício de gravidade ou de etiologia do quadro febril. Última vacina administrada foi aos 3 meses de vida. Diante do esquema vacinal incompleto (valoriza- se em especial as vacinas contra pneumococo e hemófilo), o próximo passo é avaliar nível de temperatura axilar e fatores de risco para infecção do trato urinário.","D":"Menina de 12 meses, com quadro febril há 03 dias (Tmáx de 38,5°C), está com histórico vacinal atrasado (pais são anti- vacina e criança recebeu, apenas, as doses administradas na maternidade). Foi solicitada avaliação inicial com urocultura, hemocultura e líquor."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está casa: Criança anti-vacina é de alto risco para IBG, exigindo coleta de urina, hemocultura e líquor.\nPor que as outras estão erradas:\nA, B, C: São condutas de baixo risco que não se aplicam a crianças não vacinadas.\nPonto de prova: FSSL em criança não vacinada.\nFlashcard sugerado: Febre sem foco + não vacinado? Líquor, urina e hemocultura.\nPérola: Sem vacina = alto risco.\nArmadilha: Tratar como baixo risco.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Uma criança que não tomou as vacinas contra certas bactérias perigosas está mais desprotegida, então quando ela tem febre sem causa aparente, o médico precisa investigar bem mais fundo, incluindo o líquido que envolve o cérebro."},{"id":"b13-derrame-pleural-q13","number":76,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Homem de 65 anos, portador de DPOC leve, comparece ao ambulatório queixando- se de piora recente da dispneia e novo desconforto torácico ao respirar. Nega tosse produtiva ou febre. No exame físico: FR: 22irpm, PA: 130x80mmHg, FC: 88bpm, Temperatura: 36,8ºC, SatO : 92%. Apresenta retração leve do hemitórax direito e redução de expansibilidade neste lado. Percussão revela submacicez na base direita, enquanto a ausculta evidencia murmúrio vesicular ausente na mesma região, sem ruídos adventícios. Diante deste caso, relacione os achados semiológicos fornecidos com o diagnóstico mais provável e assinale a alternativa correta quanto à interpretação desses sinais na propedêutica respiratória:","options":{"A":"A presença de submacicez à percussão associada à ausência de murmúrio vesicular praticamente descarta atelectasia como hipótese.","B":"O conjunto de retração do hemitórax, submacicez e ausência de murmúrio vesicular é compatível com atelectasia extensa, caracterizando redução do volume pulmonar.","C":"O achado de retração do hemitórax com expansibilidade diminuída é mais específico da consolidação pulmonar do que da atelectasia.","D":"A presença de submacicez à percussão praticamente exclui doenças como tumores pulmonares e massas.","E":"Na DPOC, esses achados são comuns e sinalizam uma exacerbação clássica da doença."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Retração do hemitórax, macicez e MV abolido indicam perda de volume (atelectasia).\nPor que as outras estão erradas:\nA: Macicez não descarta atelectasia.\nC: Retração é específica de atelectasia, não consolidação.\nD: Tumores podem causar atelectasia.\nE: Exacerbação de DPOC não dá macicez localizada.\nPonto de prova: Semiologia respiratória.\nFlashcard sugerado: Retração + macicez = Atelectasia.\nPérola: Retração = tirou volume.\nArmadilha: Confundir consolidação com atelectasia.","tags":["Clínica Médica","Pneumologia","DPOC","Trauma Torácico","Raciocínio Diagnóstico","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando um lado do peito encolhe, fica com som mais 'cheio' ao bater e sem ar entrando, isso mostra que uma parte do pulmão perdeu volume e murchou."},{"id":"b13-redes-atencao-q08","number":77,"collectionBlock":13,"documentBlock":13,"area":"Saúde Coletiva","topic":"Redes de Atenção à Saúde","stem":"Sobre a organização das Redes de Atenção à Saúde (RAS) e das Regiões de Saúde no âmbito do SUS, analise as assertivas abaixo: I. As Redes de Atenção à Saúde devem funcionar de forma segmentada, com autonomia entre os pontos de atenção, para garantir agilidade no atendimento e diminuir os custos operacionais. II. A Região de Saúde é um espaço geográfico contínuo constituído por agrupamentos de municípios, definidos a partir de critérios como identidade cultural, econômica e social, bem como por redes de comunicação e infraestrutura de transporte. III. A Atenção Primária à Saúde exerce papel central nas RAS, sendo responsável por coordenar o cuidado e organizar os fluxos assistenciais entre os diferentes pontos da rede. IV. A estrutura das RAS inclui portas especiais na atenção terciária, uma vez que essa se refere ao cuidado hospitalar especializado e precisa destas portas para que realize articulação com os demais níveis. Assinale a alternativa correta:","options":{"A":"Apenas I e IV estão corretas.","B":"Apenas II e III estão corretas.","C":"Apenas III e IV estão corretas.","D":"Apenas I, II e III estão corretas."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: II (Região de Saúde é espaço contínuo) e III (APS coordena o cuidado) estão corretas. I (segmentação) e IV (portas na terciária) estão erradas.\nPor que as outras estão erradas:\nA, C, D: Contêm afirmações erradas sobre segmentação ou atenção terciária.\nPonto de prova: Conceitos de RAS e Regiões de Saúde.\nFlashcard sugerado: APS coordena o cuidado nas RAS? Sim.\nPérola: RAS é integrada e coordenada pela APS.\nArmadilha: Achar que RAS funciona de forma segmentada.","tags":["Saúde Coletiva","Medicina de Família e Comunidade","Sistema Único de Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"As regiões de saúde são formadas por cidades vizinhas que têm coisas em comum, como cultura e economia, e é o postinho de saúde da atenção primária que organiza e coordena o caminho do paciente dentro do sistema."},{"id":"b13-febre-sem-sinais-q14","number":78,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Qual é a principal infecção bacteriana grave em crianças que se apresentam com febre sem foco?","options":{"A":"Meningite.","B":"Pneumonia.","C":"Faringoamigdalite.","D":"Infecção urinária.","E":"Otite média aguda."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A infecção urinária é a infecção bacteriana grave (IBG) mais comum em crianças com febre sem foco.\nPor que as outras estão erradas:\nA, B, C, E: Meningite, pneumonia e otite podem ocorrer, mas a ITU é a mais comum.\nPonto de prova: Causas de IBG na infância.\nFlashcard sugerado: IBG mais comum em febre sem foco? ITU.\nPérola: Febre sem foco = pense em urina.\nArmadilha: Achar que é pneumonia.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Quando uma criança tem febre sem nenhuma pista de onde vem, a causa bacteriana grave mais comum, de longe, é uma infecção escondida na urina."},{"id":"b13-violencia-sexual-q21","number":79,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Violência Sexual","stem":"Adolescente de 16 anos é levada, por sua mãe, ao pronto-socorro, relatando que foi vítima de abuso sexual há cerca de 24 horas. A jovem está abalada emocionalmente, mas consciente e cooperativa. A mãe afirma que a adolescente não está usando nenhum método contraceptivo e que não houve uso de preservativo no ato de violência. Considerando essa situação, qual é a abordagem inicial apropriada no manejo dessa paciente?","options":{"A":"Coletar amostras para exames forenses e solicitar testes de infecções sexualmente transmissíveis (ISTs), adiar a administração de profilaxia até que os resultados estejam disponíveis.","B":"Prescrever anticoncepção de emergência, realizar profilaxia para ISTs, fornecer suporte psicológico, orientar o seguimento e realizar exames forenses.","C":"Fornecer suporte psicológico, uma vez que a violência ocorreu há mais de 24 horas e os testes forenses podem não ser mais válidos.","D":"Encaminhar a paciente para internação psiquiátrica, para observação e apoio psicológico intensivo, adiando o tratamento físico."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A abordagem inclui anticoncepção de emergência, profilaxia ISTs, suporte e exames forenses.\nPor que as outras estão erradas:\nA, C, D: Adiar profilaxia, não fazer exames por tempo ou focar só em psiquiatria é incorreto.\nPonto de prova: Manejo pós-violência sexual em adolescente.\nFlashcard sugerado: Pós-estupro em adolescente? EC, profilaxia IST, suporte e forense.\nPérola: Não espere para medicar.\nArmadilha: Adiar profilaxia por exames.","tags":["Ginecologia e Obstetrícia","Ginecologia","Violência Sexual","Contracepção","Conduta Terapêutica","Adolescência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Tudo deve acontecer ao mesmo tempo: o remédio para evitar gravidez, os remédios contra infecções, o apoio emocional e a coleta de provas — nada disso deve esperar o resultado de exame nenhum."},{"id":"b13-febre-sem-sinais-q15","number":80,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Recém-nascido (RN) de 7 dias de vida é levado ao pronto-socorro por febre aferida de 38,3°C há 1 dia, sem outras queixas. Ao exame clínico, encontra- se responsivo a estímulos, fontanelas normotensas, choroso, sem linfonodos palpáveis, com temperatura axilar de 38,5°C, frequência respiratória de 51 irpm, sem alterações respiratórias. Exame cardiopulmonar sem alterações, com pulsos centrais e periféricos presentes. Sem lesões de pele ou mucosas, coto umbilical mumificado. A partir dessas informações, assinale a alternativa correta:","options":{"A":"RN com febre há menos de 48 horas, em bom estado geral. Orientar sinais de alarme, como não aceitação de dieta e redução de diurese; observação por mais 24 horas em casa. Caso a febre persista por mais 24 horas, retornar ao pronto-socorro.","B":"RN com febre há menos de 48 horas, em bom estado geral. Solicitar coleta de exame de urina e urocultura e iniciar antibioticoterapia oral para domicílio, em observação por mais 24 horas.","C":"RN com febre sem sinais localizatórios. Deve- se solicitar internação, com coleta, hemograma, hemocultura, proteína C reativa, exame de urina e urocultura, eletrólitos. Iniciar antibioticoterapia endovenosa.","D":"RN com febre sem sinais localizatórios. Deve- se solicitar internação, com coleta de líquor, hemograma, hemocultura, proteína C reativa, exame de urina e urocultura, eletrólitos e radiografia de tórax. Iniciar antibioticoterapia endovenosa."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está casa: RN de 7 dias com febre exige internação, exames completos (líquor, hemocultura, urina, Rx) e ATB venoso.\nPor que as outras estão erradas:\nA, B, C: Alta ou ATB oral são proibidos. É necessário líquor e Rx.\nPonto de prova: Manejo de febre em RN.\nFlashcard sugerado: RN 7 dias febril? Internação + exames completos + ATB.\nPérola: RN febril = sepse até prova em contrário.\nArmadilha: Faltar o líquor.","tags":["Pediatria","Saúde da Criança","Síndrome Febril","Lesões Cutâneas","Interpretação de Exames","Período Neonatal"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Um bebê de só uma semana de vida com febre é tratado como se pudesse ter uma infecção grave espalhada pelo corpo, então precisa internar, colher vários exames, inclusive do líquido da coluna, e já começar antibiótico na veia."},{"id":"b13-derrame-pleural-q14","number":81,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um homem de 40 anos, com histórico de tabagismo e perda de peso nos últimos meses, procura atendimento por dor torácica e tosse seca persistente. O exame físico revela macicez à percussão e diminuição do murmúrio vesicular na base do hemitórax direito. A toracocentese mostra líquido pleural com proteína de 5,2 g/ dL, DHL de 900 U/ L, glicose de 50 mg/ dL e células malignas na citologia. Qual a melhor abordagem inicial?","options":{"A":"Indicar cirurgia torácica para ressecção pulmonar imediata.","B":"Apenas administrar antibióticos e monitorar a evolução.","C":"Repetir a toracocentese em 48 horas para confirmar o diagnóstico.","D":"Prescrever corticoides para reduzir a inflamação pleural.","E":"Instalar drenagem pleural e considerar pleurodese para controle do derrame maligno."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Derrame maligno recidivante é melhor tratado com drenagem e pleurodese (esclerose) para evitar recidivas.\nPor que as outras estão erradas:\nA, B, C, D: Cirurgia imediata, só antibiótico ou repetir punção não resolvem o problema de produção contínua.\nPonto de prova: Manejo de derrame pleural maligno.\nFlashcard sugerado: Derrame maligno recorrente? Pleurodese.\nPérola: Maligno recidiva, pleurodese resolve.\nArmadilha: Repetir toracocentese.","tags":["Clínica Médica","Medicina Interna","Derrame Parapneumônico","Tabagismo","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Quando o líquido ao redor do pulmão tem células de câncer e volta sempre que é retirado, a solução é colocar um dreno e depois 'colar' as duas camadas que envolvem o pulmão para o líquido parar de se formar."},{"id":"b13-febre-sem-sinais-q16","number":82,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"Qual dos seguintes pacientes apresentando febre sem sinais localizatórios poderia ir para casa para acompanhamento diário mesmo sem realização de hemograma?","options":{"A":"Lactente de 1 mês sem comorbidade, em bom estado geral, com temperatura axilar de 39ºC.","B":"Recém-nascido com temperatura referida de 39°C.","C":"Criança de 28 meses com febre de 38,2ºC e não aceitando dieta, com vacinação completa.","D":"Pré-escolar, com temperatura axilar maior que 39ºC, EAS normal, sem vacinas.","E":"Lactente de 19 meses, com temperatura axilar de 38,2ºC, bom estado geral e vacinação completa."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Lactente de 19 meses, bem, vacinado e febre baixa pode ir para casa com observação.\nPor que as outras estão erradas:\nA, B, C, D: RN e <3 meses exigem internação/exames. Criança não vacinada ou que não aceita dieta não pode ir para casa sem exames.\nPonto de prova: Critérios de observação domiciliar na febre sem foco.\nFlashcard sugerado: Febre sem foco vai pra casa se? >3 meses, bem, vacinado, aceita dieta.\nPérola: Bem e vacinado pode ir pra casa.\nArmadilha: Liberar criança sem vacina.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Uma criança maior de um ano, vacinada em dia, com febre baixa e se sentindo bem pode ir para casa com acompanhamento diário, sem precisar fazer exame de sangue agora."},{"id":"b13-derrame-pleural-q15","number":83,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Paciente de 65 anos, tabagista, com história de dispneia progressiva e dor torácica pleurítica. Ao exame físico, apresenta macicez à percussão e redução do murmúrio vesicular em base pulmonar esquerda. Foi realizada toracocentese, e a análise do líquido pleural revelou: * Aspecto: Exsudato amarelado límpido; * pH: 7.2; * Glicose: 40 mg/dL; * Proteínas: 4,5 g/dL; * LDH: 250 U/L; * Células: Predomínio de linfócitos (90%). Qual das seguintes é a hipótese etiológica diagnóstica MAIS PROVÁVEL para o derrame pleural desse paciente?","options":{"A":"Insuficiência cardíaca congestiva.","B":"Pneumonia bacteriana.","C":"Tuberculose.","D":"Embolia pulmonar.","E":"Neoplasia."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Exsudato linfocitário com pH ácido e glicose baixa é altamente sugestivo de tuberculose.\nPor que as outras estão erradas:\nA: IC dá transudato.\nB: Pneumonia dá neutrófilos.\nD: TEP pode dar exsudato, mas linfocítico é menos típico.\nE: Neoplasia pode dar linfocítico, mas TB é mais provável no contexto.\nPonto de prova: Diagnóstico diferencial de exsudato linfocítico.\nFlashcard sugerado: Exsudato linfocítico = TB ou Neoplasia.\nPérola: Linfócito no líquido = tuberculose.\nArmadilha: Achar que é IC.","tags":["Clínica Médica","Pneumologia","Tabagismo","Derrame Parapneumônico","Raciocínio Diagnóstico","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Um líquido do pulmão cheio de um tipo específico de célula de defesa, meio ácido e com pouco açúcar, é bem característico de tuberculose."},{"id":"b13-redes-atencao-q09","number":84,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"Observe o encaminhamento realizado por um médico de família. \"À cardiologia, encaminho o Sr. J. L. S., de 56 anos, com diagnóstico de cardiopatia isquêmica, que sofreu um infarto agudo do miocárdio há 3 meses. Tem orientação para o uso de antiagregantes plaquetários, mas tem história de úlcera péptica e teve reação alérgica ao clopidogrel e à ticlopidina. Desta forma, solicito orientação quanto à conduta preventiva.\" Ao ser assistido pelo cardiologista, o paciente será atendido em qual nível de atenção e receberá que tipo de prevenção, respectivamente?","options":{"A":"Primário; secundário.","B":"Secundário; secundário.","C":"Terciário; terciário.","D":"Quaternário; terciário."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Ambulatório de cardiologia é atenção secundária, e a prevenção de novo infarto em paciente com cardiopatia isquêmica é secundária.\nPor que as outras estão erradas:\nA, C, D: Níveis e prevenções não se encaixam.\nPonto de prova: Níveis de atenção e tipos de prevenção.\nFlashcard sugerado: Tratar doença existente = Secundário/Secundária.\nPérola: Previne secundária na atenção secundária.\nArmadilha: Confundir prevenção primária com secundária.","tags":["Clínica Médica","Cardiologia","Infarto Agudo do Miocárdio","Clopidogrel","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Como ele já teve um infarto e agora está sendo acompanhado por um especialista para evitar que aconteça de novo, isso é um atendimento de nível médio com o objetivo de prevenir a doença voltar, já que ela já apareceu uma vez."},{"id":"b13-febre-sem-sinais-q17","number":85,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Criança de 6 meses foi trazida à Emergência com história de febre há 3 dias, sem identificação de foco. A mãe negou tosse, coriza, diarreia e alteração de humor. Ao exame físico, encontrava-se ativa, hidratada e corada, com temperatura axilar de 39,4ºC; à oroscopia e otoscopia, não foram identificadas alterações; à ausculta cardíaca, o ritmo era regular, sem sopros; à ausculta respiratória, os pulmões estavam limpos; à palpação, o abdômen estava flácido e sem visceromegalias. As extremidades estavam com bons pulsos e boa perfusão periférica. Com base no quadro, assinale a alternativa que contempla o conjunto de condutas recomendado no momento:","options":{"A":"Coleta de sangue para hemograma, hemocultura e PCR – início de antibiótico.","B":"Coleta de sangue para hemograma, hemocultura e PCR – realização de raio-X de tórax – sem antibiótico até os resultados dos exames.","C":"Coleta de urina para EQU com urocultura – sem antibiótico até o resultado do exame.","D":"Coleta de urina para EQU com urocultura – realização de raio-X de tórax – coleta de secreção nasal para pesquisa de vírus respiratórios – início de antibiótico."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Criança de 6 meses com febre 39.4 e 3 dias requer coleta de urina, mas se está bem, não precisa de antibiótico imediato nem hemograma de urgência.\nPor que as outras estão erradas:\nA, B, D: Hemograma, hemocultura e Rx não são de primeira linha se a criança está estável sem foco. A urina é mandatória.\nPonto de prova: Investigação de febre sem foco em 6 meses.\nFlashcard sugerado: 6 meses bem com febre >3 dias? Urina.\nPérola: >3 dias, manda urina.\nArmadilha: Pedir hemograma à toa.","tags":["Pediatria","Saúde da Criança","Síndrome Febril","Diarreia","Interpretação de Exames","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Uma criança pequena com febre há vários dias, mas que está bem e ativa, precisa principalmente de um exame de urina — não é preciso começar antibiótico antes de saber o resultado."},{"id":"b13-redes-atencao-q10","number":86,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"Em relação ao decreto n°7508, de 28 de junho de 2011, as alternativas abaixo contemplam ações e serviços de saúde de uma região de saúde, exceto:","options":{"A":"Atenção Primária.","B":"Urgência e Emergência.","C":"Atenção Psicossocial.","D":"Atenção Hospitalar Terciária.","E":"Vigilância em saúde."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O Decreto 7508 não separa ações de \"Atenção Hospitalar Terciária\" como categoria distinta; inclui atenção de média e alta complexidade.\nPor que as outras estão erradas:\nA, B, C, E: São ações descritas na organização da RAS.\nPonto de prova: Decreto 7508 e Região de Saúde.\nFlashcard sugerado: O que NÃO está no Decreto 7508? Atenção Terciária.\nPérola: O decreto fala em alta complexidade, não terciária.\nArmadilha: Usar jargão \"terciária\".","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"A lei que organiza as regiões de saúde não usa a palavra 'hospital de alta complexidade' como uma categoria separada — ela fala de outras ações, como atenção básica, urgência, saúde mental e vigilância."},{"id":"b13-tecnica-operatoria-q12","number":87,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Técnica Operatória - Fios e Anestésicos","stem":"Sobre as contraindicações e precauções relacionadas ao uso de anestésicos locais nas diferentes técnicas anestésicas, assinale a alternativa correta:","options":{"A":"A anestesia com lidocaína associada à adrenalina é contraindicada em bloqueios peridurais devido ao risco aumentado de neurotoxicidade.","B":"A anestesia tópica com lidocaína a 5% pode ser aplicada em mucosa oral em crianças pequenas, desde que a dose total não ultrapasse 10 mg/kg.","C":"A infiltração com lidocaína 1% associada à adrenalina 1:200.000 deve ser evitada em áreas com circulação terminal, como dedos, pênis, nariz e orelhas, devido ao risco de isquemia e necrose.","D":"A bupivacaína a 0,5% não deve ser utilizada para bloqueios de nervos periféricos por seu alto risco de toxicidade, sendo restrita à anestesia raquidiana com dose máxima de 5 mg/kg."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Adrenalina é vasoconstritor e não deve ser usada em áreas terminais (dedos, pênis, nariz) por risco de isquemia.\nPor que as outras estão erradas:\nA: Lido + adrenalina é usada em peridural sem problema de neurotoxicidade.\nB: Tópica em boca de crianças tem risco de toxicidade sistêmica rápido.\nD: Bupivacaína é usada para bloqueios periféricos.\nPonto de prova: Precauções com anestésicos locais e vasoconstritores.\nFlashcard sugerado: Onde não usar adrenalina? Dedos, nariz, pênis, orelha.\nPérola: Extremidades não gostam de adrenalina.\nArmadilha: Usar adrenalina no dedo.","tags":["Clínica Médica","Medicina Interna","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Existe um remédio que, junto com o anestésico, aperta os vasinhos de sangue para durar mais tempo, mas ele não pode ser usado em partes do corpo que têm pouca circulação de reserva, como dedos, nariz, orelha e pênis, porque pode cortar o sangue daquele pedacinho."},{"id":"b13-febre-sem-sinais-q18","number":88,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Febre Sem Sinais Localizatórios","stem":"Um lactente de 2 meses, nascido a termo, sem comorbidades até o momento, é trazido ao pronto- atendimento por apresentar pico febril aferido em 38,4 °C. A mãe nega tosse, vômitos, diarreia, coriza ou outros sintomas associados. Calendário vacinal completo, sendo administrada a última vacina há mais de 15 dias. Ao exame físico, o bebê está em bom estado geral, alerta, hidratado, corado, bem perfundido, sem alterações nas auscultas, sem lesões cutâneas e sem rigidez de nuca. Diante desse quadro, qual é a melhor conduta inicial?","options":{"A":"Liberar para casa com antitérmico e retorno apenas se a febre durar mais de 72 horas.","B":"Solicitar apenas hemograma e raio-X de tórax, se normal, liberar com sintomáticos.","C":"Solicitar hemograma completo, rotina de urina e painel viral. Diante dos resultados, avaliar antibioticoterapia.","D":"Indicar internação hospitalar para investigação laboratorial completa e iniciar antibioticoterapia empírica imediata."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Correta: C. Lactente de 2 meses com febre sem sinais localizatórios, mas em bom estado geral, deve ser investigado com hemograma completo, exame de urina (rotina/urocultura) e painel viral, reservando a decisão sobre antibioticoterapia para depois da estratificação de risco com base nesses resultados — evitando tanto a conduta excessivamente conservadora de liberar sem exames (A) quanto a internação com antibiótico empírico imediato sem investigação prévia (D), reservada aos lactentes de alto risco.","tags":["Pediatria","Saúde da Criança","Diarreia","Imunização","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags 13.txt","answerAudit":"official-source","answerSource":"QUESTÕES BLOCO 13 (SEMANAIS).txt","scheduleId":"cron-124","kids":"Mesmo o bebê parecendo bem, com menos de 3 meses de vida a febre precisa ser investigada com exames de sangue, urina e um teste de vírus antes de decidir se vai precisar de antibiótico."},{"id":"b13-febre-sem-sinais-q19","number":89,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Febre Sem Sinais Localizatórios","stem":"A febre é uma das principais queixas nos departamentos de emergências pediátricas. Na avaliação de um paciente com febre sem sinais localizatórios com idade entre 1 a 3 meses, a definição entre alto e baixo risco de uma infecção bacteriana grave depende dos seguintes exames:","options":{"A":"Hemograma, urinálise.","B":"Hemograma, coprocultura e líquor.","C":"Hemograma, hemocultura, urinálise.","D":"Hemograma, urinálise, líquor e raio-X de tórax."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A definição de risco em 1-3 meses usa hemograma e urinálise (e às vezes PCR).\nPor que as outras estão erradas:\nB, C, D: Coprocultura e Rx não são de rotina para definir risco em 1-3 meses sem sintomas.\nPonto de prova: Avaliação de lactente febril 1-3 meses.\nFlashcard sugerado: Exames para lactente 1-3 meses febril? Hemograma e urina.\nPérola: Hemograma e urina definem o risco.\nArmadilha: Achar que Rx é obrigatório.","tags":["Clínica Médica","Medicina Interna","Síndrome Febril","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Para saber se um bebê entre 1 e 3 meses com febre corre risco alto ou baixo de infecção grave, os exames principais são o de sangue e o de urina."},{"id":"b13-pneumonia-q17","number":90,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Um clínico está atendendo um paciente hospitalizado com pneumonia adquirida na comunidade (PAC) de apresentação grave. Considerando a seleção adequada da antibioticoterapia empírica nesses casos, analise as afirmações a seguir: I. A introdução precoce de terapia voltada contra Staphylococcus aureus resistente à meticilina (MRSA) deve ser considerada diante de fatores de risco fortes, como colonização prévia conhecida. II. Pacientes com história recente de uso de antibiótico intravenoso, bronquiectasias ou múltiplas exacerbações de DPOC com necessidade frequente de antibióticos apresentam fatores de risco para Pseudomonas aeruginosa, podendo a decisão por uso de cobertura antipseudomonas ser individualizada. III. Em casos de pneumonia aspirativa complicada por abscesso pulmonar ou empiema, a cobertura para anaeróbios deve ser acrescentada ao esquema antibiótico. A alternativa que apresenta somente as afirmativas corretas é:","options":{"A":"I e III.","B":"III apenas.","C":"I e II.","D":"II e III.","E":"I, II e III."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: As três afirmações estão corretas: risco de MRSA, risco de Pseudomonas e cobertura de anaeróbios em abscesso/aspirativa são diretrizes atuais.\nPor que as outras estão erradas:\nA, B, C, D: Excluem alguma afirmação correta.\nPonto de prova: Tratamento de PAC grave.\nFlashcard sugerado: PAC grave com abscesso? Cubra anaeróbios.\nPérola: Abscesso = anaeróbio.\nArmadilha: Não cobrir anaeróbios.","tags":["Clínica Médica","Pneumologia","Pneumonia","DPOC","Conhecimento Conceitual","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Na pneumonia grave, o médico escolhe o antibiótico pensando em fatores de risco específicos: se a pessoa já teve uma bactéria resistente antes, se tem uma doença pulmonar que favorece outra bactéria mais complicada, ou se engasgou com comida — cada situação pede um reforço diferente no remédio."},{"id":"b13-pneumonia-q15","number":91,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Pneumonia: PAC e Hospitalar","stem":"Mulher de 59 anos, tabagista e portadora de doença pulmonar obstrutiva crônica (DPOC), procura o serviço de emergência apresentando quadro de febre alta, cefaleia intensa, mialgia, dor abdominal e diarreia há 3 dias. Refere tosse seca, início súbito dos sintomas e relata ter ficado hospedada em um hotel durante viagem recente. Ao exame, apresenta confusão mental, pressão arterial de 130x76 mmHg, frequência cardíaca de 94 bpm, frequência respiratória de 22 irpm e saturação de O2 de 94% (AA), além de estertores à ausculta pulmonar. Laboratorialmente, observa-se hiponatremia, elevação discreta de transaminases e PCR elevada (125 mg/ L). O raio- X evidencia infiltrado alveolar em base pulmonar direita. Considerando os dados clínicos e laboratoriais, assinale a alternativa que indica o exame diagnóstico MAIS indicado e o tempo mínimo recomendado de tratamento para o provável agente etiológico:","options":{"A":"Solicitar PCR viral para influenza e iniciar oseltamivir por 7 dias.","B":"Solicitar sorologia para Mycoplasma pneumoniae e tratar por 10 dias com claritromicina.","C":"Solicitar teste de antígeno urinário para Legionella e iniciar levofloxacino por no mínimo 5 dias.","D":"Solicitar cultura de escarro comum e tratar por 7 dias com cefuroxima.","E":"Solicitar hemoculturas e iniciar piperacilina-tazobactam por 14 dias."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: O quadro (febre, confusão, hiponatremia, transaminases altas, hotel) sugere Legionella. O exame é antígeno urinário e o tratamento levofloxacino por 5-7 dias.\nPor que as outras estão erradas:\nA, B, D, E: Influenza, Mycoplasma, cultura comum e pip/tazo não se encaixam.\nPonto de prova: Diagnóstico e tratamento de Legionella.\nFlashcard sugerado: Legionella pede o quê? Antígeno urinário + Levofloxacino.\nPérola: Hiponatremia e confusão = Legionella.\nArmadilha: Tratar como influenza.","tags":["Clínica Médica","Neurologia","DPOC","Tabagismo","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Febre alta, confusão mental, um sal do sangue baixo e o fígado meio alterado, em quem esteve num hotel recentemente, são pistas fortes de uma bactéria específica — o exame certo é um teste na urina, e o remédio é um antibiótico específico."},{"id":"b13-semanais-q92","number":92,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"No contexto de pneumonia adquirida na comunidade (PAC), em relação ao escore de gravidade CURB-65, podemos afirmar:","options":{"A":"Não sugere possibilidade de tratamento ambulatorial.","B":"Se paciente pontuar apenas na idade em idade ≥ 65, pode ser tratado ambulatorialmente.","C":"Variáveis como nível de consciência pouco interferem em sua análise.","D":"Pontuações a partir de 3 sinalizam quadros de PAC leve."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: CURB-65 com 1 ponto (apenas idade) é PAC leve e pode ser tratado ambulatorialmente.\nPor que as outras estão erradas:\nA: O escore sugere ambulatorial quando 0-1.\nC: Nível de consciência é parte do escore (C).\nD: >=3 é grave.\nPonto de prova: Interpretação do CURB-65.\nFlashcard sugerado: CURB-65 0-1? Ambulatorial.\nPérola: CURB 1 pode ir pra casa.\nArmadilha: Internar só pela idade.","tags":["Clínica Médica","Pneumologia","Pneumonia","Classificação Clínica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Se o único ponto de risco da pessoa no cálculo de gravidade da pneumonia é a idade, ainda assim ela pode ser tratada em casa, porque a pontuação total continua baixa."},{"id":"b13-semanais-q93","number":93,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Paciente com quadro de pneumonia adquirida na comunidade (PAC) possui escore CURB-65 de 4. Olhando para esta pontuação, podemos indicar como local de tratamento:","options":{"A":"Domicílio.","B":"Leito de enfermaria (isolamento de contato).","C":"Leito de terapia intensiva.","D":"Pontuação pouco influencia em local de tratamento."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: CURB-65 de 4 pontos indica PAC muito grave, com indicação de tratamento em UTI.\nPor que as outras estão erradas:\nA, B: Domicílio e enfermaria são para escores menores.\nD: O escore influencia diretamente o local de tratamento.\nPonto de prova: Interpretação do CURB-65.\nFlashcard sugerado: CURB-65 4? UTI.\nPérola: CURB 4 = UTI.\nArmadilha: Internar em enfermaria.","tags":["Clínica Médica","Pneumologia","Pneumonia","Conduta Terapêutica","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-126","kids":"Uma pontuação bem alta nesse cálculo de gravidade da pneumonia mostra que o caso é muito sério, e o lugar certo para tratar é a UTI."},{"id":"b13-semanais-q94","number":94,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Homem, 73 anos de idade, com antecedente de insuficiência cardíaca de fração de ejeção reduzida e hipertensão arterial sistêmica. Internado por descompensação da insuficiência cardíaca por má adesão. Após 8 dias de internação hospitalar, intercorreu com febre, tosse produtiva, taquicardia e pressão arterial média limítrofe. Exames laboratoriais: * Hb: 14,2 mg/dL; * Leucócitos: 9.200/mm³; * Plaquetas: 184 mil/mm³; * Cr: 0,9 mg/dL. Hemocultura com identificação de Staphylococcus epidermidis em frasco aeróbio após 22h, frasco anaeróbio e outro par de hemocultura seguem negativos. Assinale a alternativa que apresenta a antibioticoterapia mais pertinente para o caso apresentado:","options":{"A":"Ceftriaxone e azitromicina.","B":"Piperacilina com tazobactam.","C":"Vancomicina.","D":"Oxacilina."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Staphylococcus epidermidis em 1 frasco de hemocultura geralmente é contaminação. O paciente tem pneumonia nosocomial (8º dia). O tratamento empírico é Pip/tazo.\nPor que as outras estão erradas:\nA: Não é PAC.\nC: Vancomicina só se houvesse cateter e evidência de infecção por SCN real.\nD: Oxacilina não cobre os nosocomiais comuns nem o SCN.\nPonto de prova: Pneumonia nosocomial e interpretação de hemocultura.\nFlashcard sugerado: Hemocultura com S. epidermidis em 1 frasco? Contaminação.\nPérola: Epidermidis solitário é contaminação.\nArmadilha: Tratar contaminação com vanco.","tags":["Clínica Médica","Hematologia","Insuficiência Cardíaca","Hipertensão Arterial","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Quando uma bactéria que normalmente vive na pele aparece em só um dos vários frascos do exame de sangue, geralmente é só sujeira da coleta, e não uma infecção de verdade — o problema real aqui é uma pneumonia pega no próprio hospital, que precisa de um antibiótico mais amplo."},{"id":"b13-semanais-q95","number":95,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Homem de 70 anos, tabagista, com diagnóstico prévio de DPOC moderado e Diabetes Mellitus tipo 2 controlado, procura atendimento por febre (38,4 ),tosse produtiva com expectoração amarelada, prostração e dispneia progressiva há quatro dias. Ao exame físico, encontra- se lúcido e orientado, com frequência respiratória de 28 irpm, pressão arterial de 102/66 mmHg, frequência cardíaca de 108 bpm e saturação de oxigênio de 90% em ar ambiente. Ausculta pulmonar com estertores crepitantes em base esquerda. A radiografia de tórax revela consolidação no lobo inferior esquerdo. Exames laboratoriais mostram leucocitose leve e PCR elevada. Com base nesse caso clínico, a conduta mais apropriada é:","options":{"A":"Prescrever amoxicilina-clavulanato com azitromicina via oral e liberar para tratamento ambulatorial, com retorno precoce.","B":"Prescrever levofloxacino oral em dose única diária, por 7 dias, e solicitar TC de tórax ambulatorial.","C":"Internar em enfermaria para antibioticoterapia venosa com ceftriaxona e azitromicina EV, iniciando coleta de hemoculturas.","D":"Internar em Unidade de Terapia Intensiva para vigilância e suporte respiratório com antibiótico de amplo espectro.","E":"Prescrever ceftriaxona intramuscular em dose única e reavaliar em 48 horas na Unidade Básica de Saúde."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Idade 70 (1) + FR 28 (1) = 2 pontos. Indicação de internação em enfermaria e ATB venoso (ceftriaxona + azitromicina).\nPor que as outras estão erradas:\nA: Ambulatorial é para 0-1.\nB: Levofloxacino é opção, mas internação é necessária.\nD: UTI é para >=3.\nE: IM não é padrão.\nPonto de prova: Manejo de PAC com CURB-65 2.\nFlashcard sugerado: CURB-65 2? Internar enfermaria + ATB venoso.\nPérola: CURB 2 = enfermaria.\nArmadilha: Mandar para casa.","tags":["Clínica Médica","Pneumologia","Diabetes Mellitus Tipo 2","DPOC","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Com essa pontuação de gravidade, o tratamento certo é internar numa enfermaria comum, sem precisar de UTI, e usar dois antibióticos na veia ao mesmo tempo."},{"id":"b13-semanais-q96","number":96,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Paciente feminina de 68 anos é trazida ao pronto atendimento por queixa de tosse produtiva há 5 dias, sendo que hoje passou a apresentar dispneia para caminhar no plano e dor ventilatório- dependente em hemitórax direito. Nega febre, internações ou uso de antibióticos recentes. Nega sintomas gripais antes do início do quadro atual, mas diz que vem apresentando dificuldade para engolir alguns alimentos e tosse com frequência durante a alimentação. Paciente é previamente hipertensa e diabética, com controle adequado das comorbidades em uso de losartana 50 mg 12/12h, anlodipino 5 mg 12/12h, metformina 850 mg 3x/dia e dapagliflozina 10 mg/dia. Ao exame físico, paciente encontra-se em regular estado geral, corada, hidratada, anictérica, afebril, lúcida e orientada, cavidade oral em bom estado. Sinais vitais: frequência cardíaca de 102 bpm, frequência respiratória de 25 ipm, PA = 120 x 70 mmHg, SpO2 = 91% em ar ambiente, glicemia capilar de 95 mg/ L. Ausculta cardíaca e exame abdominal sem alterações, ausculta pulmonar com estertores crepitantes em campo inferior de hemitórax direito. O médico solicita uma radiografia de tórax que mostra consolidação em base do pulmão direito, com alguns infiltrados algodonosos também em campo inferior esquerdo. Exames de sangue mostram: Hb = 12,1 g/ dL, leucócitos 15.000 (75% neutrófilos, 5% bastões), plaquetas 160.000/mm³, Ur = 60 mg/dL, Cr = 1,1 mg/dL, Na = 135 mEq/L, K = 4,5 mEq/L, Proteína C- reativa = 50 mg/dL, gasometria arterial com pH = 7,46 pO2 = 58 mmHg, pCO2 = 34 mmHg, SpO2 = 91%. Com relação ao caso descrito, assinale a alternativa correta:","options":{"A":"Paciente apresenta pneumonia comunitária sem sinais de gravidade, podendo ser tratada ambulatorialmente com amoxacilina-clavulanato e azitromicina. Nenhum exame adicional é necessário.","B":"Paciente com provável pneumonia aspirativa, sendo recomendado tratamento com ceftriaxone e clindamicina em regime de enfermaria, além de oxigenoterapia suplementar por cateter nasal. Solicitar hemoculturas e cultura de escarro.","C":"Paciente com pneumonia comunitária grave com necessidade de internação em UTI. Iniciar antibioticoterapia empírica com ceftriaxone e azitromicina, cateter de alto fluxo e hidrocortisona, colher hemoculturas e pesquisa de antígeno urinário para Legionella.","D":"Paciente com pneumonia adquirida na comunidade, de provável origem aspirativa. Iniciar tratamento empírico com ceftriaxone e azitromicina, cateter nasal de oxigênio, colher hemocultura e cultura de bactérias no escarro, painel de patógenos respiratórios, antígeno urinário para Streptococcus e Legionella."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A paciente tem pneumonia aspirativa (disfagia, tosse na alimentação). Conduta: internação, ceftriaxona + azitromicina.\nPor que as outras estão erradas:\nA: Tem indicação de internação (SaO2 91%, FR 25, aspirativa).\nB: Clindamicina não é mais usada de rotina com ceftriaxone na aspirativa grave sem abscesso.\nC: Não tem critérios de UTI estritos.\nPonto de prova: Manejo de pneumonia aspirativa.\nFlashcard sugerado: Pneumonia aspirativa? Ceftriaxona + (azitro ou clinda).\nPérola: Aspirou, internou.\nArmadilha: Usar amoxi-clavulonato oral.","tags":["Clínica Médica","Endocrinologia","Trauma Torácico","Trombocitopenia","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Dor no peito e o líquido estar concentrado de um lado só são pistas de que esse líquido é do tipo mais 'inflamado', cheio de proteína, enquanto o inchaço geral do corpo é sinal do tipo mais simples e aguado."},{"id":"b13-semanais-q97","number":97,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Homem, 68 anos, com história de DPOC grave (GOLD IV), ex- tabagista, apresenta- se ao pronto- socorro com quadro de dispneia progressiva, tosse com secreção purulenta há 2 dias, além de piora da saturação e sinais de desconforto respiratório. Ao exame: PA 130x85 mmHg, FC 105 bpm, FR 30 irpm, SatO 82% (ar ambiente), ausculta com roncos e sibilos difusos. Gasometria: pH 7,28, paCO 70 mmHg, HCO 32 mEq/L, PaO 55 mmHg. Ainda dentro desse caso clínico, CASO sejam indicados antimicrobianos, qual esquema antimicrobiano empírico mais apropriado?","options":{"A":"Azitromicina isolada, pela sua cobertura contra germes atípicos, principais agentes na exacerbação do DPOC.","B":"Ceftriaxona associada à azitromicina, pela ampla cobertura de germes típicos e atípicos, especialmente em casos graves.","C":"Vancomicina associada a meropenem, considerando a gravidade do quadro e a necessidade de cobertura para germes multirresistentes como Pseudomonas aeruginosa.","D":"Amoxicilina, devido à sua boa penetração pulmonar e perfil de segurança em idosos."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Exacerbação grave de DPOC (Tipo I) requer cobertura ampla. Ceftriaxona + azitromicina é apropriada para germes típicos e atípicos.\nPor que as outras estão erradas:\nA: Azitromicina isolada não cobre bem em grave.\nC: Vanco + meropenem é exagero inicial.\nD: Amoxicilina é para grave não complicado.\nPonto de prova: ATB na exacerbação grave de DPOC.\nFlashcard sugerado: DPOC grave? Ceftriaxona + azitromicina.\nPérola: DPOC grave pede dupla cobertura.\nArmadilha: Usar amoxicilina.","tags":["Clínica Médica","Pneumologia","DPOC","Gasometria Arterial","Interpretação de Exames","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Numa crise muito grave dessa doença crônica de pulmão, com respiração ofegante e pouco oxigênio no sangue, o antibiótico escolhido precisa cobrir tanto as bactérias mais comuns quanto as mais atípicas, por isso a combinação de dois remédios é a mais indicada."},{"id":"b13-semanais-q98","number":98,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Homem, 30 anos de idade, conta que apresenta anasarca há dois meses. Há uma semana, dispneia e dor torácica esquerda. Nega febre. Ao exame clínico, apresentou PA de 140x90 mmHg, Pulmões: murmúrios vesiculares diminuídos em metade inferior de hemitórax esquerdo, com egofonia; abdome: macicez móvel +, sem visceromegalias. Edema ++/4+ de membros inferiores. Os achados que mais provavelmente indicam que o derrame pleural seja um exsudato são:","options":{"A":"Ser à esquerda e ter anasarca.","B":"Ter anasarca e ser homem jovem.","C":"Ter dor torácica e ser à esquerda.","D":"Ter dor torácica e dispneia."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Dor torácica e localização à esquerda são mais sugestivos de exsudato (processo inflamatório/infeccioso/neoplásico).\nPor que as outras estão erradas:\nA, B, D: Anasarca indica transudato, mas a pergunta pede o que indica exsudato.\nPonto de prova: Características de exsudato.\nFlashcard sugerado: Exsudato dá dor torácica?\nPérola: Transudato não dói.\nArmadilha: Achar que anasarca é exsudato.","tags":["Clínica Médica","Pneumologia","Trauma Torácico","Derrame Pleural","Interpretação de Exames","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Dor no peito e o líquido estar concentrado de um lado só são pistas de que esse líquido é do tipo mais 'inflamado', cheio de proteína, e não do tipo mais simples que costuma vir junto com inchaço no corpo todo."},{"id":"b13-derrame-pleural-q17","number":99,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um homem de 45 anos, tabagista e etilista crônico, procura atendimento médico devido a tosse seca, dor torácica pleurítica e dispneia progressiva há três semanas. Relata febre vespertina, sudorese noturna e perda ponderal de 5 kg no último mês. O exame físico evidencia diminuição do frêmito toracovocal e macicez à percussão no hemitórax direito. A radiografia de tórax confirma um derrame pleural moderado à direita. A toracocentese revela um líquido pleural exsudativo, linfocítico, com ADA (adenosina deaminase) de 75 U/ L e cultura negativa para Mycobacterium tuberculosis. Diante desse quadro, qual o próximo passo mais adequado para o diagnóstico?","options":{"A":"Repetir a toracocentese para nova análise microbiológica do líquido pleural.","B":"Iniciar empiricamente esquema RIPE (rifampicina, isoniazida, pirazinamida e etambutol), pois o diagnóstico já pode ser confirmado.","C":"Realizar biópsia pleural fechada para análise histopatológica e pesquisa de BAAR.","D":"Solicitar teste tuberculínico (PPD) e interferon-gamma (IGRA) para confirmar a infecção tuberculosa."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Exsudato linfocítico com ADA 75 e cultura negativa. O próximo passo clássico para confirmar TB pleural é a biópsia pleural (granuloma).\nPor que as outras estão erradas:\nA, B, D: Repetir cultura é inútil. RIPE sem cultura pode ser feito em alto risco, mas a biópsia confirma.\nPonto de prova: Diagnóstico de tuberculose pleural.\nFlashcard sugerado: TB pleural com ADA alto e cultura neg? Biópsia pleural.\nPérola: Biópsia fecha o diagnóstico de TB.\nArmadilha: Iniciar RIPE sem diagnóstico confirmado.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Tabagismo","Raciocínio Diagnóstico","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Os sintomas, como suor noturno e emagrecimento, e o líquido do pulmão apontam fortemente para tuberculose, mas como a cultura ainda não confirmou, o próximo passo é pegar um pedacinho da membrana que envolve o pulmão para examinar de perto e fechar o diagnóstico."},{"id":"b13-derrame-pleural-q23","number":100,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um homem de 67 anos, portador de insuficiência cardíaca congestiva, apresenta quadro de dispneia progressiva e dor torácica pleurítica há 5 dias. Ao exame físico, observa- se redução do murmúrio vesicular à direita e macicez à percussão do terço inferior do hemitórax correspondente. Realizou-se punção do líquido pleural, que revelou aspecto citrino, pH pleural de 7,18, glicose pleural de 52 mg/dL, LDH pleural de 1100 U/L e proteína pleural de 3,7 g/dL. Com base nesses dados laboratoriais do líquido pleural e nos conhecimentos sobre o manejo do derrame pleural, assinale a alternativa correta:","options":{"A":"O gradiente sérico-pleural de albumina deve ser utilizado apenas para líquidos pleurais sanguinolentos.","B":"O líquido deve ser classificado como transudato pelos critérios de Light.","C":"O uso de diuréticos em pacientes cardiopatas quase sempre impede falso resultado de exsudato pelos critérios de Light.","D":"A infecção é pouco provável, pois o pH e a glicose estão dentro da normalidade.","E":"Há indicação de drenagem torácica, pois o líquido preenche critérios para derrame parapneumônico complicado."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: Mesmo em IC (transudato), se o pH for < 7.2 e glicose < 60 e LDH alto, pode haver outra causa associada (empiema/complicado) exigindo drenagem.\nPor que as outras estão erradas:\nA, B, C, D: O gradiente albumina ajuda, mas os critérios de drenagem (pH/glicose) são mais fortes.\nPonto de prova: Falso exsudato e critérios de drenagem.\nFlashcard sugerado: pH 7.18 e glic 52? Drenar.\nPérola: pH baixo manda drenar, mesmo cardiopata.\nArmadilha: Achar que diurético sempre causa falso exsudato que não precisa drenar.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Insuficiência Cardíaca","Conduta Terapêutica","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Mesmo em quem já tem problema de coração, que costuma dar um líquido mais simples, se os números do líquido do pulmão mostrarem muita acidez e uma enzima bem alta, isso indica que apareceu outra complicação junto, e é preciso drenar."},{"id":"b13-derrame-pleural-q19","number":101,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Derrame Pleural","stem":"Um paciente de 65 anos, tabagista, procura o pronto- socorro com história de dispneia progressiva e dor torácica do tipo pleurítica no hemitórax direito, há 10 dias. Ao exame físico, apresenta- se em regular estado geral, eupneico em repouso, com frequência respiratória de 24 irpm. Na inspeção do tórax, observa-se abaulamento e redução da mobilidade do hemitórax direito, com retificação dos espaços intercostais. À palpação, identifica-se diminuição do frêmito toracovocal nas bases do hemitórax direito. A percussão revela macicez desde o 6º espaço intercostal até as bases pulmonares direitas. À ausculta, constata- se abolição do murmúrio vesicular na área de macicez, com presença de pectorilóquia fônica e egofonia no limite superior entre a macicez e o som claro pulmonar. A ressonância vocal encontra- se diminuída na mesma topografia da alteração do frêmito toracovocal. O conjunto de achados semiológicos descritos no exame físico desse paciente é mais consistente com o diagnóstico de:","options":{"A":"Pneumonia lobar com consolidação extensa.","B":"Pneumotórax hipertensivo do hemitórax direito.","C":"Atelectasia por obstrução brônquica.","D":"Derrame pleural de volume moderado.","E":"Fibrose pulmonar com retração parenquimatosa."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Macicez, MV abolido, egofonia no limite superior são sinais clássicos de derrame pleural.\nPor que as outras estão erradas:\nA: Pneumonia dá MV aumentado/egofonia na área toda.\nB: Pneumotórax dá hipersonoridade.\nC: Atelectasia dá retração.\nE: Fibrose dá crepitações.\nPonto de prova: Semiologia do derrame pleural.\nFlashcard sugerado: Macicez + MV abolido + egofonia no topo = Derrame.\nPérola: Derrame: macio embaixo, egofonia em cima.\nArmadilha: Confundir com pneumonia.","tags":["Clínica Médica","Medicina Interna","Trauma Torácico","Tabagismo","Raciocínio Diagnóstico","Pessoa Idosa"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Esse conjunto de sinais no exame do peito — som mais 'cheio' ao bater, ausência de ar entrando e uma voz que soa estranha bem na linha entre o som cheio e o normal — é a marca registrada de um líquido acumulado ao redor do pulmão."},{"id":"b13-semanais-q102","number":102,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Questões semanais - Bloco 13","stem":"Mulher, 24 anos, previamente hígida, procura atendimento por tosse, dispneia e febre há 4 dias. Recebeu alta com amoxicilina-clavulanato e retorna ao pronto-socorro 5 dias depois, com persistência da febre e evolução com queda do estado geral, vômitos e dor torácica ventilatório dependente. Ao exame físico, FC 120 bpm, PA 100/60 mmHg e SpO2 91% em ar ambiente. Realizou radiografia de tórax que mostrou derrame pleural à direita. Realizada toracocentese diagnóstica com os seguintes resultados: celularidade 10.114/mm³ (neutrófilos 65%); DHL 1500 U/L, proteína total 3,2 g/dL; glicose 20 mg/dL; ADA 70 U/L, pH 7,18. Qual a melhor conduta neste momento?","options":{"A":"Internação hospitalar, prescrição de ceftriaxona e metronidazol e drenagem pleural fechada.","B":"Internação hospitalar, prescrição de piperacilina-tazobactam e RIPE.","C":"Iniciar RIPE e reavaliar paciente em 15 dias.","D":"Modificar amoxicilina-clavulanato por levofloxacino e manter tratamento ambulatorial."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Os exames mostram empiema (pH 7.18, glic 20). Conduta: internação, drenagem fechada e ATB (ceftriaxona + metronidazol).\nPor que as outras estão erradas:\nB, C, D: Outros esquemas ou ambulatorial não tratam o empiema adequadamente.\nPonto de prova: Conduta em empiema.\nFlashcard sugerado: Empiema (pH 7.18)? Dreno + ATB.\nPérola: Empiema = pus na pleura, drena.\nArmadilha: Só trocar antibiótico.","tags":["Cirurgia","Trauma","Gasometria Arterial","Amoxicilina com Clavulanato","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Os números do líquido mostram uma infecção grave formando pus dentro do peito, então é preciso internar, colocar um dreno e usar antibióticos que cobrem bem esse tipo de infecção."},{"id":"b13-semanais-q103","number":103,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Uma paciente de 43 anos vem em consulta com quadro de dispneia progressiva há 2 meses + discreta perda ponderal, com picos subfebris ao entardecer e sudorese mais intensa noturna. Queixa-se de dor ventilatório-dependente em HTD lateral, onde possui leve redução de murmúrio vesicular, sem dessaturações em ar ambiente. Trouxe radiografia de tórax (abaixo). Qual seria o próximo passo para prosseguir rumo ao diagnóstico? ** ** Fonte: Acervo Dr. Renato Miranda Lima.","options":{"A":"Biópsia transtorácica de massa suspeita de neoplasia.","B":"PET-CT para avaliação de imagem.","C":"Toracocentese guiada por ultrassonografia para estudo de líquido pleural.","D":"Encaminhamento para Oncologia clínica para avaliar imunoterapia."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":["data:image/jpeg;base64,"],"comment":"Análise:\nCorreta: C.\nPor que está certa: A imagem e os sintomas (dispneia, dor) com massa/velamento indicam necessidade de toracocentese para análise do líquido antes de biópsia de massa.\nPor que as outras estão erradas:\nA, B, D: Biópsia e PET-CT vêm após a análise do líquido pleural.\nPonto de prova: Propedêutica do derrame pleural.\nFlashcard sugerado: Derrame pleural de causa incerta? Toracocentese.\nPérola: Analisa o líquido antes de furar o peito.\nArmadilha: Pedir PET-CT de cara.","tags":["Clínica Médica","Medicina Interna","Dispneia","Raciocínio Diagnóstico","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Antes de partir para exames mais avançados ou biópsia de uma possível massa, o primeiro passo é sempre analisar o líquido que se acumulou ao redor do pulmão."},{"id":"b13-semanais-q104","number":104,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Homem, 42 anos, previamente saudável, apresenta quadro de febre vespertina, sudorese noturna, emagrecimento e dispneia progressiva há 3 semanas. Ao exame físico, murmúrio vesicular abolido na base do hemitórax esquerdo. A radiografia de tórax mostra derrame pleural de moderado volume à esquerda. Realizada toracocentese, com os seguintes resultados do líquido pleural: proteína 4,8 g/dL, DHL 600 U/L, glicose 65 mg/dL, pH 7,3 e predomínio de linfócitos (90%). Pesquisa de BAAR no líquido pleural é negativa. Diante desse quadro, qual é a conduta mais adequada?","options":{"A":"Observar e aguardar resolução espontânea, pois o quadro é autolimitado.","B":"Iniciar antibioticoterapia empírica para pneumonia e acompanhar a resposta.","C":"Realizar drenagem pleural imediata, pois os parâmetros indicam empiema.","D":"Iniciar tratamento específico para tuberculose, baseado no quadro clínico e bioquímico."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: Exsudato linfocítico com ADA 75 é altamente sugestivo de TB. A conduta atual permite iniciar tratamento (RIPE) baseado no quadro clínico-bioquímico.\nPor que as outras estão erradas:\nA, B, C: Observar, tratar como pneumonia ou drenar são incorretas.\nPonto de prova: Diagnóstico e tratamento de TB pleural.\nFlashcard sugerado: Exsudato linfocítico + ADA 75? Iniciar RIPE.\nPérola: ADA alto = TB, pode tratar.\nArmadilha: Achar que precisa de cultura positiva.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Gasometria Arterial","Conduta Terapêutica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"Febre à tarde, suor à noite e emagrecimento, junto com um líquido do pulmão rico em um tipo de célula de defesa, são sinais tão característicos de tuberculose que o médico já pode começar o tratamento mesmo sem esperar a cultura confirmar."},{"id":"b13-semanais-q105","number":105,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Paciente vem ao Pronto Atendimento queixando-se de estar há 3 dias com tosse + expectoração esverdeada, bem como prostração. Semiologia torácica com egofonia em base direita. Submetido à radiografia que mostrou opacidade em terços médio e inferior de hemitórax direito, tendo sido feita toracocentese guiada por ultrassonografia (quadro de pneumonia adquirida na comunidade - PAC com derrame pleural). Iniciado antibiótico e saem os resultados de alguns exames laboratoriais, incluindo líquido pleural. Qual a melhor alternativa quanto ao diagnóstico do quadro? | @cols=4: | | --- | --- | --- | --- | |","options":{"A":"Derrame pleural transudativo, provável Insuficiência Cardíaca descompensada associada.","B":"Derrame pleural exsudativo por quadro de tuberculose.","C":"Derrame pleural transudativo, provável parapneumônico complicado.","D":"Derrame pleural parapneumônico não complicado."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O quadro descreve PAC com derrame pleural. Se o líquido tem pH > 7.2, glic > 60 e LDH < 1000, é parapneumônico não complicado.\nPor que as outras estão erradas:\nA, B, C: Não há dados de IC, TB ou complicação no caso apresentado.\nPonto de prova: Classificação de derrame parapneumônico.\nFlashcard sugerado: Parapneumônico não complicado? Antibiótico, sem dreno.\nPérola: Simples e não complicado = só antibiótico.\nArmadilha: Achar que é TB.","tags":["Clínica Médica","Pneumologia","Derrame Parapneumônico","Trauma Torácico","Raciocínio Diagnóstico","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-127","kids":"O quadro é de uma infecção pulmonar comum com um pouco de líquido ao redor, mas sem sinais de complicação — então é só continuar com o antibiótico, sem precisar drenar."},{"id":"b13-semanais-q106","number":106,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Questões semanais - Bloco 13","stem":"Considerando o suporte nutricional perioperatório, analise as assertivas e assinale a alternativa que aponta a(s) correta(s).: I. A nutrição parenteral é a via preferencial de suporte nutricional em pacientes cirúrgicos. II. Em pacientes cirúrgicos bem nutridos, o suporte nutricional parenteral pós-operatório só deve ser considerado se a previsão for de que não haverá alimentação enteral adequada por um período inferior a 5 dias. III. A desnutrição hospitalar é um fator de risco significativo para o aumento de complicações pós-operatórias, como infecções e dificuldades na cicatrização. IV. A suplementação imunomoduladora com arginina e glutamina demonstrou impacto robusto na redução da mortalidade em todos os pacientes cirúrgicos. Assinale a alternativa correta:","options":{"A":"Apenas as afirmações I e II estão corretas.","B":"Apenas as afirmações II e IV estão corretas.","C":"Apenas a afirmação III está correta.","D":"Apenas as afirmações III e IV estão corretas."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Apenas a III está correta. A desnutrição aumenta complicações pós-op. A via enteral é preferencial, a parenteral é para >7 dias de jejum, e a suplementação não reduz mortalidade em todos.\nPor que as outras estão erradas:\nA, B, D: Afirmações I, II e IV estão incorretas.\nPonto de prova: Suporte nutricional perioperatório.\nFlashcard sugerado: Via preferencial de nutrição? Enteral.\nPérola: Desnutrido tem mais infecção.\nArmadilha: Preferir parenteral de início.","tags":["Cirurgia","Cirurgia Geral","Cuidados Pós-Operatórios","Estado Nutricional","Epidemiologia Clínica","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Antes de uma cirurgia, estar desnutrido aumenta bastante o risco de complicações, como infecção e dificuldade de cicatrizar — por isso cuidar da alimentação da pessoa é tão importante quanto a própria operação."},{"id":"b13-semanais-q107","number":107,"collectionBlock":13,"documentBlock":13,"area":"Cirurgia","topic":"Questões semanais - Bloco 13","stem":"Durante um procedimento ambulatorial de exérese de lipoma em dorso, um médico residente opta por realizar anestesia local com lidocaína sem vasoconstrictor. O paciente tem 70 kg, sem comorbidades, e o procedimento tem previsão de curta duração. O residente pergunta ao preceptor qual a dose máxima segura de lidocaína sem vasoconstrictor que pode ser utilizada neste caso. Considerando o peso do paciente e os valores de toxicidade dos anestésicos locais, qual é a dose máxima aproximada recomendada para lidocaína sem vasoconstrictor nesse paciente?","options":{"A":"140 mg.","B":"210 mg.","C":"280 mg.","D":"350 mg.","E":"490 mg."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Dose máxima de lido sem vasoconstritor é 4.5 mg/kg. 4.5 x 70 = 315mg. 1% = 10mg/mL. O limite seguro mais próximo é 280mg (usando 4mg/kg).\nPor que as outras estão erradas:\nA, B, D, E: Não correspondem ao cálculo correto de dose.\nPonto de prova: Dose máxima de anestésico local.\nFlashcard sugerado: Dose máx lido sem vasoconstritor? 4.5 mg/kg.\nPérola: Sem vaso, a dose cai.\nArmadilha: Exceder a dose.","tags":["Cirurgia","Anestesiologia","Cálculo Clínico","Paciente Adulto","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-125","kids":"Cada anestésico tem uma dose máxima segura calculada pelo peso da pessoa; para esse paciente de 70 kg, sem o remédio que aperta os vasinhos de sangue, o limite fica em torno de 280 mg."},{"id":"b13-semanais-q108","number":108,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Questões semanais - Bloco 13","stem":"Menino de 2 anos é levado ao pronto atendimento com febre que varia de 38,5° C a 39,2°C há 24 horas, sem sintomas associados. Está ativo, hidratado, responsivo e com exame físico normal. Tem vacinação completa pelo PNI. A mãe está muito preocupada, pois teme convulsões febris, já que um primo teve esse diagnóstico. Ela administrou uma dose de antitérmico (paracetamol) com melhora temporária, mas a febre retornou. A criança não apresenta sinais de toxemia, e não há história de convulsão prévia. Qual é a conduta mais adequada?","options":{"A":"Solicitar hemograma, PCR e urocultura, pois toda febre sem foco em menores de 3 anos deve ser investigada laboratorialmente.","B":"Internar para observação e controle rigoroso da temperatura, devido ao risco familiar de convulsão febril.","C":"Orientar sobre a natureza benigna da febre, reforçar sinais de alerta e manter antitérmico conforme necessidade, evitando alternância de fármacos.","D":"Prescrever dois antitérmicos em esquema alternado para evitar picos febris e reduzir risco de convulsão."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Criança de 2 anos bem, com febre baixa e sem toxemia, não precisa de exames, apenas antitérmico e observação. Intercalação não é recomendada.\nPor que as outras estão erradas:\nA, B, D: Solicitar exames, internar ou intercalar não são necessários.\nPonto de prova: Manejo da febre sem foco em criança vacinada >3 meses.\nFlashcard sugerado: Febre sem foco, criança bem >3 meses? Observar.\nPérola: Bem e vacinado, manda pra casa.\nArmadilha: Intercalar antitérmico.","tags":["Pediatria","Saúde da Criança","Paracetamol","Síndrome Febril","Conduta Terapêutica","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Essa criança está bem, só com febre normal — o certo é explicar para a mãe que é uma coisa benigna, dar um remédio para baixar a febre quando precisar, e não misturar dois remédios diferentes tentando controlar tudo o tempo todo."},{"id":"b13-semanais-q109","number":109,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Questões semanais - Bloco 13","stem":"Você atende um lactente de 2 meses de idade na UPA, com história de febre iniciada há 24 horas. Segundo a mãe, apresentou temperatura axilar de 38ºC, sendo medicado com dipirona gotas (1 gota por Kg de peso). Lactente ativo, reativo ao manuseio, sem alterações no exame físico completo. Assinale abaixo a alternativa que contém a conduta correta neste caso:","options":{"A":"Liberar para casa, orientando sinais de alerta de piora, com prescrição de paracetamol gotas (1 gota por Kg) e retorno em 24 horas.","B":"Internar, coletar exames laboratoriais incluindo coleta de líquor, Rx de tórax e iniciar antibiótico empírico.","C":"Coletar pesquisa de vírus respiratório, hemograma e sedimento urinário, aguardando resultado ainda na unidade, e orientar a mãe sobre o uso correto de antitérmico.","D":"Liberar para casa, manter o antitérmico utilizado e orientar sobre sinais de alerta de piora.","E":"Acalmar a mãe sobre o quadro, pois trata- se de infecção benigna com exame físico normal, devendo esta retornar em 48 horas para reavaliação."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Lactente de 2 meses com febre exige investigação de urina, hemograma e painel viral, mas se está bem, pode aguardar resultado na unidade.\nPor que as outras estão erradas:\nA, D, E: Dar alta pura é errado. Internar com líquor pode ser exagero se não tem alteração, mas o padrão de 2 meses é investigar tudo. O gabarito é C.\nPonto de prova: Investigação de febre em 2 meses.\nFlashcard sugerado: 2 meses febril bem? Investigar urina, sangue e vírus.\nPérola: <3 meses sempre investiga.\nArmadilha: Dar alta sem exames.","tags":["Pediatria","Saúde da Criança","Dipirona","Síndrome Febril","Conduta Terapêutica","Primeira Infância"],"tagSource":"Tags 13.txt","scheduleId":"cron-124","kids":"Para esse bebê de 2 meses com febre, o certo é colher exames de sangue, urina e de vírus ali mesmo na unidade e esperar o resultado antes de liberar, além de ensinar a mãe a usar o remédio para febre direitinho."},{"id":"b13-violencia-sexual-q22","number":110,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Violência Sexual","stem":"Uma mulher de 28 anos procura atendimento após relatar ter sido vítima de violência sexual com penetração por pessoa conhecida. Ela se lembra parcialmente do ocorrido, mas afirma que não houve consentimento e que houve uso de força física. Ela relata também o consumo excessivo de álcool na ocasião. Qual deve ser a abordagem inicial mais apropriada nesta situação?","options":{"A":"Encaminhamento imediato ao Instituto Médico Legal (IML) para coleta de vestígios, seguida de posterior atendimento médico e psicológico.","B":"Avaliar necessidade de profilaxia para infecções sexualmente transmissíveis (ISTs) e contracepção de emergência, além de suporte psicológico inicial.","C":"Realização de exames laboratoriais prévios para avaliação de ISTs, com início de profilaxias apenas após confirmação de alterações nos exames.","D":"Priorizar o acolhimento psicológico da paciente, deixando a decisão sobre profilaxias e demais intervenções médicas para um momento posterior, caso ela se sinta confortável."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: Avaliar e iniciar profilaxias para ISTs e contracepção de emergência, além de suporte.\nPor que as outras estão erradas:\nA: IML não precede o atendimento.\nC: Não se espera exames para profilaxia.\nD: Profilaxias não devem ser adiadas.\nPonto de prova: Abordagem inicial da vítima de violência sexual.\nFlashcard sugerado: Pós-estupro? Avaliar, profilaxia IST e EC.\nPérola: Não espere para medicar.\nArmadilha: Mandar para o IML primeiro.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Mesmo que ela não lembre tudo o que aconteceu por causa do álcool, o atendimento deve avaliar e já começar os remédios de proteção contra infecções e gravidez, junto com apoio emocional, sem esperar resultado de exame."},{"id":"b13-violencia-sexual-q28","number":111,"collectionBlock":13,"documentBlock":13,"area":"Pediatria","topic":"Violência Sexual","stem":"Adolescente, 17 anos de idade, chega ao hospital acompanhada da mãe, relatando violência sexual ocorrida há aproximadamente 80 horas. O teste rápido para HIV foi negativo. Qual das condutas é mais apropriada em relação à Profilaxia Pós-exposição (PEP) ao HIV?","options":{"A":"Iniciar PEP com esquema de 28 dias.","B":"Não iniciar PEP, pois o prazo máximo é 72 horas.","C":"Não há indicação, pois o teste rápido para HIV é negativo.","D":"Aguardar a avaliação da soroconversão em sete dias."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O prazo máximo para PEP HIV é 72 horas. Como se passaram 80 horas, não se inicia.\nPor que as outras estão erradas:\nA: O prazo já passou.\nC: O teste rápido negativo não exclui janela imunológica, mas o tempo é o fator limitante aqui.\nD: Aguardar soroconversão não é conduta profilática.\nPonto de prova: Prazo para PEP HIV.\nFlashcard sugerado: Prazo máx PEP HIV? 72h.\nPérola: Passou de 72h, não faz PEP.\nArmadilha: Iniciar PEP após 72h.","tags":["Pediatria","Saúde da Criança","HIV/AIDS","Violência Sexual","Conhecimento Conceitual","Adolescência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O remédio que evita a infecção pelo HIV só funciona se começar até três dias depois do ocorrido — como já se passaram mais de três dias, não adianta mais começar esse remédio."},{"id":"b13-semanais-q112","number":112,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"“ A atenção às pessoas em situação de violência sexual é composta por ações intersetoriais que possibilitam o atendimento, proteção, prevenc ãode novas situac õese medidas para possibilitar a responsabilizac ãodos(as) autores(as) da agressão”. A partir do trecho acima, retirado do PCDT do Ministério da Saúde para Atenção Integral às Pessoas (2022), assinale a alternativa correta:","options":{"A":"A violência sexual é um evento de notificação compulsória e imediata ao SINAN, ou seja, deve ser realizada dentro de 12 horas do atendimento.","B":"Todas as pessoas vítimas de violência sexual devem receber profilaxia contra o vírus da Hepatite B, com imunoglobulina hiperimune e 3 doses de vacina específica.","C":"A profilaxia das ISTs não virais é indicada para gestantes a depender da idade gestacional, diferentemente da PEP - HIV, que está sempre indicada.","D":"A contracepção de emergência pode ser dispensada no caso de vítimas que façam uso de anticoncepção de alta eficácia, como usuárias de DIU tanto de cobre quanto hormonal, ou implante de etonogestrel."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A contracepção de emergência não é necessária em usuárias de DIU de cobre, hormonal ou implante, pois já usam método altamente eficaz.\nPor que as outras estão erradas:\nA: Notificação é compulsória, mas em até 24h/48h (não 12h).\nB: Nem todas precisam de imunoglobulina (depende da vacinação prévia).\nC: A PEP HIV também é indicada para gestantes.\nPonto de prova: Normas técnicas de atenção à violência sexual.\nFlashcard sugerado: Vítima com DIU precisa de contracepção emergência? Não.\nPérola: DIU já protege.\nArmadilha: Prescrever EC para quem usa DIU.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Quem já usa um método bem eficiente para não engravidar não precisa tomar mais um remédio extra para evitar gravidez depois da violência, porque já está protegida."},{"id":"b13-semanais-q113","number":113,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 13","stem":"Mulher, 25 anos de idade, busca atendimento por atraso menstrual e teste de gravidez positivo. Sem doenças, refere ciclos menstruais prévios regulares, com variação entre 27 e 31 dias de intervalo. A data da última menstruação foi em 10/08/2025. Refere que foi vítima de violência sexual em 23/08/2025, mas não verbalizou por receio de ser punida pelo agressor conhecido. A relação não consensual ocorreu com penetração vaginal, sem uso de preservativo. Após o ocorrido, apresentou corrimento amarelado, que tratou por conta própria com clotrimazol em dose única. Manifesta desejo de interromper a gravidez. Assinale a alternativa correta:","options":{"A":"Como a idade gestacional e o evento são compatíveis, a interrupção de gravidez pode ser realizada diante de relato circunstanciado.","B":"Diante da idade gestacional avançada, indicar suporte multiprofissional integral e iniciar pré-natal de alto risco.","C":"Orientar para que realize boletim de ocorrência para prosseguir com a interrupção de gravidez.","D":"Não há correlação direta entre a gravidez e o evento e, por isso, deve-se garantir assistência pré-natal."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: A idade gestacional (cerca de 5-6 sem) é compatível com a data do estupro (DUM 10/08, estupro 23/08). O aborto pode ser feito mediante relato circunstanciado.\nPor que as outras estão erradas:\nB, C, D: Não há idade gestacional avançada, não precisa de BO e a correlação é direta.\nPonto de prova: Cálculo de IG e permissivo legal de aborto.\nFlashcard sugerado: IG bate com a data do estupro? Pode abortar.\nPérola: DUM + 2 sem = IG. Se bate, libera.\nArmadilha: Exigir BO.","tags":["Ginecologia e Obstetrícia","Ginecologia","Ciclo Menstrual","Violência Sexual","Cálculo Clínico","Paciente Adulto"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Fazendo as contas direitinho, o tempo de gravidez bate exatamente com a data da violência que ela sofreu, então ela pode interromper a gestação só contando o que aconteceu para a equipe de saúde, sem precisar de mais provas."},{"id":"b13-semanais-q115","number":115,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 13","stem":"A interrupção legal da gestação no Brasil é possível ser realizada em contextos de gestação decorrente de violência sexual, risco de vida à gestante ou, ainda, em casos de fetos anencéfalos. Para quaisquer outras situações, há necessidade de autorização judicial, como nos casos de fetos com malformações consideradas letais. Assinale, dentre as condições abaixo, aquela que pode ser considerada como incompatível com a vida extrauterina:","options":{"A":"Agenesia renal unilateral.","B":"Hérnia diafragmática.","C":"Onfalocele.","D":"Síndrome de Patau."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: A Síndrome de Patau (Trissomia 13) é incompatível com a vida extrauterina (sobrevida muito curta).\nPor que as outras estão erradas:\nA, B, C: Agenesia renal unilateral, hérnia diafragmática e onfalocele podem ser compatíveis com a vida após tratamento.\nPonto de prova: Malformações fetais incompatíveis com a vida.\nFlashcard sugerado: Qual síndrome é incompatível com a vida? Patau (T13).\nPérola: Patau e Edwards não vivem.\nArmadilha: Achar que onfalocele é letal.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Violência Sexual","Conhecimento Conceitual","Saúde Materno-Fetal","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Existe uma alteração genética rara e grave em que o bebê tem tantos problemas que não consegue sobreviver fora da barriga da mãe — diferente de outras condições da lista, que podem ser tratadas depois do nascimento."},{"id":"b13-semanais-q116","number":116,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Questões semanais - Bloco 13","stem":"Adolescente de 13 anos, acompanhada da mãe, procura a emergência obstétrica relatando ter sido vítima de estupro por um conhecido da família há cerca de 2 meses. Refere atraso menstrual de 5 dias, náuseas e desconforto abdominal. O teste rápido de gravidez é positivo, mas a idade gestacional da ultrassonografia não bate com a data do relato do estupro. Ao ser acolhida por equipe multiprofissional, a adolescente manifesta expressamente o desejo de interromper a gestação. A mãe também concorda com o procedimento. Todavia, a diretora técnica da unidade alega que o aborto não tem respaldo legal uma vez que a data relatada da violência não bate com a idade gestacional. Além disso, a diretora refere também objeção de consciência institucional e diz que o procedimento não será realizado ali. Com base na legislação brasileira e nas diretrizes técnicas do Ministério da Saúde, a conduta mais adequada nesse caso é:","options":{"A":"Não realizar o aborto, porque a Constituição Brasileira garante a objeção de consciência institucional, devendo a paciente ser transferida de unidade.","B":"Não realizar o aborto, já a idade gestacional não coincide com a data do relato da violência, perdendo o amparo legal dos casos de estupro.","C":"Encaminhar a paciente ao Instituto Médico Legal para comprovação do estupro antes da autorização do aborto legal.","D":"Solicitar autorização judicial, pois a paciente é menor de idade, mesmo com o consentimento da mãe.","E":"Realizar o aborto legal imediatamente, com termo de consentimento assinado pela paciente e responsável, sem necessidade de boletim de ocorrência."},"answer":"E","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: E.\nPor que está certa: A discordância de datas não impede o aborto. Objeção de consciência é individual, não institucional. Basta o relato e o consentimento.\nPor que as outras estão erradas:\nA, B, C, D: Baseiam-se na exigência de comprovação, IML, juiz ou objeção institucional, todas incorretas.\nPonto de prova: Legislação do aborto por estupro.\nFlashcard sugerado: Data do estupro não bate com USG? Aborto permitido mesmo assim.\nPérola: Objeção é individual.\nArmadilha: Objeção de consciência institucional.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Abortamento","Ciclo Menstrual","Conduta Terapêutica","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"Mesmo que a data contada não bata exatamente com o tempo da gravidez, isso não impede o aborto legal; e a pessoa responsável pelo hospital não pode recusar o procedimento para todo mundo só porque ela pessoalmente discorda — essa recusa só pode ser individual, de cada profissional."},{"id":"b13-semanais-q117","number":117,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Uma paciente de 25 anos de idade deu entrada no pronto-socorro referindo ter sido vítima de abuso sexual há duas horas. Conta que foi obrigada a manter relação sexual com penetração vaginal sem preservativo com um desconhecido, e queixa-se de sangramento vaginal de pequena monta, associado a escoriações pelo corpo. Em relação ao atendimento das pacientes vítimas de abuso sexual, assinale a alternativa correta:","options":{"A":"Caso a paciente engravide e opte pela interrupção gestacional, deverá ser orientada a realizar boletim de ocorrência para ter direito ao aborto legal.","B":"A paciente deverá ser acolhida e o atendimento inicial deverá incluir profilaxias para ISTs virais e não virais.","C":"Se for constatado que a paciente não estava no período fértil, não haverá indicação de prescrever contracepção de emergência para essa paciente.","D":"A notificação do caso de violência sexual deverá ser feita em até 7 dias após o evento."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: O atendimento inicial deve acolher a vítima e iniciar profilaxias virais e não virais imediatamente.\nPor que as outras estão erradas:\nA: Não é necessário BO para abortar.\nC: Contracepção é indicada independentemente do ciclo.\nD: A notificação é imediata (24-48h), não 7 dias.\nPonto de prova: Atendimento à vítima de violência sexual.\nFlashcard sugerado: Pós-estupro? Acolher e iniciar profilaxias.\nPérola: Profilaxia viral e bacteriana na hora.\nArmadilha: Exigir BO para abortar.","tags":["Clínica Médica","Medicina Interna","Violência Sexual","Sangramento Vaginal","Conhecimento Conceitual","Urgência e Emergência"],"tagSource":"Tags 13.txt","scheduleId":"cron-123","kids":"O primeiro atendimento deve incluir logo os remédios que previnem tanto infecções causadas por vírus quanto por bactérias."},{"id":"b13-semanais-q118","number":118,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Durante uma reunião da equipe de APS, a enfermeira relata o caso de um paciente com diabetes não controlado, que frequentemente busca atendimento no pronto- socorro por complicações agudas. A equipe decide discutir como otimizar o cuidado desse paciente e de outros com situação semelhante. Com base no conceito de rede de atenção à saúde, qual seria a estratégia mais eficaz para evitar novas internações e melhorar o controle da doença?","options":{"A":"Organizar uma abordagem centralizada na APS, com ênfase em consultas frequentes e acompanhamento exclusivo pela sua equipe de forma a abordar os determinantes sociais da saúde.","B":"Garantir que o paciente seja encaminhado para o nível secundário de atenção à saúde, para atendimento por um especialista em endocrinologia e melhor manejo medicamentoso do caso.","C":"Estabelecer uma linha de cuidado que coordene e monitore o estado de saúde do paciente, desde a atenção primária à saúde até os serviços especializados, quando necessário.","D":"Estabelecer um protocolo clínico que facilite o acesso aos demais níveis da rede de atenção à saúde para todos os pacientes com múltiplas internações por complicações agudas."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: A estratégia mais eficaz nas RAS é estabelecer uma linha de cuidado que coordene a APS e a atenção especializada.\nPor que as outras estão erradas:\nA, B, D: Focar só na APS ou só no especialista não resolve a coordenação do cuidado.\nPonto de prova: Gestão nas Redes de Atenção à Saúde.\nFlashcard sugerado: Como melhorar cuidado de crônico na RAS? Linha de cuidado integrada.\nPérola: Linha de cuida conecta os pontos.\nArmadilha: Centralizar só na APS.","tags":["Clínica Médica","Endocrinologia","Diabetes Mellitus","Conhecimento Conceitual","Paciente Adulto","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Para um paciente com diabetes que vive indo à emergência, o melhor é montar um caminho de cuidado organizado que conecte o postinho de saúde com os especialistas, em vez de cada um cuidar sozinho sem se falar."},{"id":"b13-redes-atencao-q14","number":119,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Redes de Atenção à Saúde","stem":"Durante a visita domiciliar da agente comunitária de saúde de sua área, encontra-se a residência do Seu Jurandir, idoso de 75 anos, diabético e hipertenso, acamado após período de AVE, com dificuldade para organização de medicamentos pois é analfabeto. A residência possui saneamento básico adequado e este mora com a esposa, uma filha de 40 anos desempregada e o neto de 10 anos. Levando em consideração a estrutura familiar e os determinantes socioeconômicos identificados, estratifique o risco dessa família:","options":{"A":"Risco máximo.","B":"Risco moderado.","C":"Risco baixo.","D":"Sem risco."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: Família com idoso acamado, analfabeto, desempregada e criança apresenta alto risco socioeconômico e clínico.\nPor que as outras estão erradas:\nB, C, D: Subestimam a vulnerabilidade da família.\nPonto de prova: Estratificação de risco na APS.\nFlashcard sugerado: Idoso acamado + analfabeto + desemprego = Risco máximo.\nPérola: Vulnerabilidade social soma pontos.\nArmadilha: Classificar como risco baixo.","tags":["Clínica Médica","Geriatria","Acidente Vascular Cerebral","Conhecimento Conceitual","Pessoa Idosa","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Essa família reúne várias dificuldades ao mesmo tempo — um idoso acamado, ninguém que saiba ler para organizar os remédios, desemprego em casa — e por isso ela é classificada como de risco muito alto, precisando de atenção redobrada da equipe de saúde."},{"id":"b13-semanais-q120","number":120,"collectionBlock":13,"documentBlock":13,"area":"Medicina de Família e Comunidade","topic":"Questões semanais - Bloco 13","stem":"O genograma é uma ferramenta utilizada na prática da Atenção Primária para:","options":{"A":"Identificar padrões de saúde, vínculos familiares e fatores de estresse.","B":"Representar apenas relações biológicas da família.","C":"Realizar diagnósticos clínicos a partir de exames laboratoriais.","D":"Descrever somente a configuração atual do domicílio familiar."},"answer":"A","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: A.\nPor que está certa: O genograma identifica padrões de saúde, vínculos e fatores de estresse na família.\nPor que as outras estão erradas:\nB, C, D: O genograma não é apenas biológico, não faz diagnóstico clínico e representa mais que a configuração atual.\nPonto de prova: Uso do genograma na APS.\nFlashcard sugerado: O que o genograma mostra? Padrões de saúde e vínculos familiares.\nPérola: Genograma é a árvore genealógica da saúde.\nArmadilha: Achar que é só biológico.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"O genograma é como um desenho da árvore da família que ajuda o médico a enxergar não só quem é parente de quem, mas também os padrões de saúde e as coisas que causam estresse dentro daquela família."},{"id":"b13-redes-atencao-q16","number":121,"collectionBlock":13,"documentBlock":13,"area":"Medicina de Família e Comunidade","topic":"Redes de Atenção à Saúde","stem":"A Atenção Primária à Saúde é uma complexa estrutura que integra diversos sistemas de saúde, tanto no Brasil quanto em diferentes países do mundo. Tem se consolidado como protagonista no cuidado de indivíduos e populações e, para tanto, baseia seu funcionamento nos atributos preconizados por Barbara Starfield. O atributo “Acesso de Primeiro Contato” na APS refere-se a:","options":{"A":"O acompanhamento contínuo e progressivo do paciente ao longo do tempo, criando vínculo com a equipe de saúde.","B":"A capacidade da APS de ofertar cuidado abrangente, contemplando diferentes dimensões da saúde da pessoa.","C":"A articulação entre a APS e os demais níveis de atenção, assegurando continuidade e integração do cuidado.","D":"A função da APS de ser a porta de entrada preferencial e usual do sistema de saúde, garantindo acesso oportuno às novas necessidades de saúde da população."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O acesso de primeiro contato refere-se à função da APS de ser a porta de entrada preferencial.\nPor que as outras estão erradas:\nA: Refere-se à longitudinalidade.\nB: Refere-se à integralidade.\nC: Refere-se à coordenação.\nPonto de prova: Atributos da APS (Starfield).\nFlashcard sugerado: Porta de entrada usual = Acesso de primeiro contato.\nPérola: Primeiro contato = porta de entrada.\nArmadilha: Confundir com coordenação.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Esse conceito significa que o postinho de saúde deve ser o primeiro lugar que a pessoa procura sempre que tem uma necessidade nova de saúde, funcionando como a porta de entrada principal do sistema."},{"id":"b13-redes-atencao-q17","number":122,"collectionBlock":13,"documentBlock":13,"area":"Ginecologia e Obstetrícia","topic":"Redes de Atenção à Saúde","stem":"Um médico de família e comunidade em uma unidade de saúde localizada no centro de uma grande metrópole, durante uma visita da equipe de Consultório na Rua, atende uma mulher de 18 anos, que é encontrada vivendo em um viaduto. Ela está grávida, aproximadamente no terceiro trimestre (cerca de 32 semanas, segundo seu relato). A paciente não possui documentação, não faz acompanhamento pré-natal e refere não conseguir acessar os serviços de saúde devido a situações de violência que enfrentou ao tentar buscar ajuda anteriormente. Ao exame físico, realizado em condições não ideais, observou-se que ela está pálida, com sinais de má nutrição. O exame obstétrico mostrou um útero compatível com a idade gestacional estimada, mas o batimento cardíaco fetal não pôde ser auscultado claramente com o sonar portátil. Quais estratégias intersetoriais poderiam ser implementadas para assegurar um acompanhamento contínuo e eficaz para essa paciente durante o restante da gestação e no período pós-parto?","options":{"A":"Encaminhar a paciente para internação compulsória em uma Comunidade Terapêutica para monitoramento contínuo devido à alta incidência do uso de drogas em pessoas em situação de rua e pela certeza da adesão ao plano de cuidado.","B":"Estabelecer uma parceria entre a unidade de saúde e a sociedade civil para criar uma rede de suporte que não se utilize da UBS e acompanhe a paciente de maneira integrada, garantindo seu parto em uma maternidade pública.","C":"Cadastrá-la na UBS mais próxima do viaduto onde dorme, acionar a assistência social e buscar parcerias com instituições da sociedade civil para garantir a adesão da paciente ao pré-natal, acionando também o serviço de pré-natal de alto risco.","D":"Reforçar a importância do pré- natal e responsabilizar a paciente pela adesão ao tratamento, tomando o cuidado de encaminhá-la ao serviço de pré-natal de alto risco para que seja decidida a necessidade de internação."},"answer":"C","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: C.\nPor que está certa: Gestante em situação de rua deve ser cadastrada na UBS, acionada a assistência social e parceiras para garantir o pré-natal.\nPor que as outras estão erradas:\nA: Internação compulsória em comunidade terapêutica é proibida.\nB: Não se deve excluir a UBS do cuidado.\nD: Responsabilizar a paciente é punitivo.\nPonto de prova: Manejo de populações vulneráveis na APS.\nFlashcard sugerado: Gestante em rua? UBS + assistência social.\nPérola: Rua precisa de rede de apoio, não de internação.\nArmadilha: Internação compulsória.","tags":["Ginecologia e Obstetrícia","Obstetrícia","Pré-Natal","Assistência ao Parto","Interpretação de Exames","Saúde Materno-Fetal"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Para ajudar essa jovem grávida que vive na rua, o certo é cadastrá-la no postinho mais perto de onde ela dorme, chamar a assistência social e outras organizações para apoiar, e encaminhá-la para um acompanhamento de gravidez mais cuidadoso — nunca internar à força ou culpar ela pela situação."},{"id":"b13-semanais-q123","number":123,"collectionBlock":13,"documentBlock":13,"area":"Clínica Médica","topic":"Questões semanais - Bloco 13","stem":"Em uma cidade, após aumento de casos de Chikungunya, muitos pacientes evoluíram com dor crônica. Inicialmente os casos estavam sendo encaminhados para o reumatologista, porém havia longo tempo de espera. Um médico da ESF decide então solicitar que a secretaria organize matriciamento para melhor manejo dos casos na atenção primária, discussão de casos complexos e melhora dos referenciamentos para atenção especializada. O atributo da Atenção Primária à Saúde em destaque na atitude do médico é:","options":{"A":"Longitudinalidade.","B":"Competência cultural.","C":"Orientação familiar.","D":"Coordenação."},"answer":"D","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: D.\nPor que está certa: O matriciamento e a organização dos fluxos entre APS e especializada é o atributo da coordenação.\nPor que as outras estão erradas:\nA: Longitudinalidade é o vínculo ao longo do tempo.\nB: Competência cultural é derivado.\nC: Orientação familiar é derivado.\nPonto de prova: Atributos da APS.\nFlashcard sugerado: Matriciamento e organização de fluxos = Coordenação.\nPérola: Coordenação une APS e especialista.\nArmadilha: Confundir com longitudinalidade.","tags":["Clínica Médica","Reumatologia","Chikungunya","Conduta Terapêutica","Atenção Primária","Avaliação Clínica"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Quando o médico organiza uma forma de os especialistas ajudarem a equipe do postinho a resolver os casos mais complicados sem precisar encaminhar todo mundo, isso mostra a habilidade da atenção primária de coordenar o cuidado entre os diferentes níveis."},{"id":"b13-semanais-q125","number":125,"collectionBlock":13,"documentBlock":13,"area":"Medicina de Família e Comunidade","topic":"Questões semanais - Bloco 13","stem":"Durante uma reunião de equipe em uma Unidade Básica de Saúde (UBS), os profissionais discutem os desafios de realizar um cuidado centrado na pessoa, especialmente para pacientes com múltiplas demandas psicossociais. Um dos profissionais sugere que, além dos cuidados clínicos, a APS deve integrar abordagens que considerem o contexto familiar, comunitário e as crenças culturais do paciente. Com base nos atributos essenciais e derivados da Atenção Primária à Saúde (APS), assinale a alternativa correta:","options":{"A":"A orientação familiar é suficiente para garantir o conhecimento das necessidades comunitárias, dispensando a orientação comunitária na APS.","B":"A orientação comunitária permite que a equipe de saúde compreenda as demandas locais e envolva a comunidade no planejamento das ações, enquanto a competência cultural possibilita um cuidado mais sensível às crenças e experiências dos pacientes.","C":"A equipe de APS deve focar apenas nos aspectos biomédicos, deixando as questões culturais e comunitárias para outros setores sociais.","D":"A orientação comunitária é dispensável, pois as necessidades individuais sempre se sobrepõem às do coletivo na APS."},"answer":"B","source":"QUESTÕES BLOCO 13 (SEMANAIS).txt","sourceLabel":"Questões semanais - Bloco 13","images":[],"comment":"Análise:\nCorreta: B.\nPor que está certa: A orientação comunitária envolve a comunidade no planejamento, e a competência cultural permite cuidado sensível às crenças.\nPor que as outras estão erradas:\nA: A orientação comunitária não dispensa a familiar.\nC, D: A APS não foca só no biomédico e não dispensa o comunitário.\nPonto de prova: Atributos derivados da APS.\nFlashcard sugerado: Sensibilidade às crenças = Competência cultural.\nPérola: APS cuida da pessoa no seu contexto.\nArmadilha: Focar só no biomédico.","tags":["Medicina de Família e Comunidade","Atenção Primária à Saúde","Conhecimento Conceitual","Atenção Primária","Avaliação Clínica","Caso Clínico"],"tagSource":"Tags 13.txt","scheduleId":"cron-122","kids":"Conhecer bem a comunidade ao redor ajuda a equipe de saúde a entender as necessidades reais das famílias e envolver todo mundo no planejamento do cuidado, enquanto respeitar as crenças e a cultura de cada pessoa torna o atendimento mais sensível e humano."}]};
